-- signature: private.call_cron_endpoint(text)
CREATE OR REPLACE FUNCTION private.call_cron_endpoint(p_path text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
declare
    v_origin text;
    v_secret text;
begin
    if p_path is null or p_path !~ '^/api/cron/[a-z0-9/-]+$' then
        raise exception 'CRON_PATH_INVALID';
    end if;
    select decrypted_secret into v_origin from vault.decrypted_secrets where name = 'kezek_cron_origin';
    select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'kezek_cron_secret';
    if v_origin is null or v_secret is null or v_origin !~ '^https://[^/]+$' then
        return null;
    end if;
    -- Asynchronous: pg_net performs the request in its background worker, so a
    -- slow endpoint never holds the cron job; responses land in net._http_response.
    return net.http_get(
        url := v_origin || p_path,
        headers := jsonb_build_object('Authorization', 'Bearer ' || v_secret),
        timeout_milliseconds := 60000
    );
end;
$function$
;

-- signature: private.ensure_staff_role()
CREATE OR REPLACE FUNCTION private.ensure_staff_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_role uuid;
begin
    if new.user_id is null or not coalesce(new.is_active, false) then
        return new;
    end if;
    if tg_op = 'UPDATE'
        and new.user_id is not distinct from old.user_id
        and new.biz_id is not distinct from old.biz_id
        and new.is_active is not distinct from old.is_active then
        return new;
    end if;
    select id into v_role from public.roles where key = 'staff';
    if v_role is null then
        return new;
    end if;
    begin
        insert into public.user_roles (user_id, biz_id, role_id)
        values (new.user_id, new.biz_id, v_role)
        on conflict (user_id, role_id, biz_key) do nothing;
    exception when others then
        raise warning 'staff role not granted to the account of staff card %: %', new.id, sqlerrm;
    end;
    return new;
end;
$function$
;

