-- signature: public._assert_booking_transition_access(uuid)
CREATE OR REPLACE FUNCTION public._assert_booking_transition_access(p_booking_id uuid)
 RETURNS public.bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_booking public.bookings;
  v_locked public.bookings;
  v_actor uuid := auth.uid();
  v_role text := coalesce(nullif(current_setting('role',true),'none'),session_user);
begin
  select * into v_booking from public.bookings where id=p_booking_id;
  if not found then raise exception using errcode='P0002',message='BOOKING_NOT_FOUND'; end if;
  if v_role not in ('service_role','postgres','supabase_admin') then
    if v_actor is null then raise exception using errcode='42501',message='BOOKING_FORBIDDEN'; end if;
    if v_booking.client_id is distinct from v_actor
      and not public.finance_can_manage_business(v_actor,v_booking.biz_id)
      and not public.has_branch_admin(v_booking.branch_id)
      and not public.is_super_admin()
      and not exists(select 1 from public.staff s where s.id=v_booking.staff_id
        and s.biz_id=v_booking.biz_id and s.user_id=v_actor and s.is_active) then
      raise exception using errcode='42501',message='BOOKING_FORBIDDEN';
    end if;
  end if;
  perform id from public.staff where id=v_booking.staff_id for update;
  select * into v_locked from public.bookings where id=p_booking_id for update;
  if not found then raise exception using errcode='P0002',message='BOOKING_NOT_FOUND'; end if;
  if row(v_locked.client_id,v_locked.biz_id,v_locked.branch_id,v_locked.staff_id)
    is distinct from row(v_booking.client_id,v_booking.biz_id,v_booking.branch_id,v_booking.staff_id) then
    raise exception using errcode='40001',message='BOOKING_CHANGED';
  end if;
  return v_locked;
end;
$function$
;

-- signature: public._assert_internal_booking_access(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public._assert_internal_booking_access(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_actor uuid:=auth.uid(); v_role text:=coalesce(nullif(current_setting('role',true),'none'),session_user);
begin
  if v_role not in ('service_role','postgres','supabase_admin') and (
    v_actor is null or not (public.finance_can_manage_business(v_actor,p_biz_id)
      or public.has_branch_admin(p_branch_id) or public.is_super_admin()
      or exists(select 1 from public.staff s where s.id=p_staff_id and s.biz_id=p_biz_id and s.user_id=v_actor and s.is_active))) then
    raise exception using errcode='42501',message='BOOKING_FORBIDDEN';
  end if;
  if not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id and is_active) then
    raise exception 'branch not found or inactive';
  end if;
  perform id from public.staff where id=p_staff_id and biz_id=p_biz_id and is_active
    and (branch_id=p_branch_id or exists(select 1 from public.staff_schedule_versions where staff_id=p_staff_id)) for update;
  if not found then raise exception 'staff not found or inactive'; end if;
end;
$function$
;

-- signature: public._claim_booking_notifications(integer,integer,uuid[])
CREATE OR REPLACE FUNCTION public._claim_booking_notifications(p_limit integer, p_lease_seconds integer, p_exclude_ids uuid[])
 RETURNS SETOF public.booking_notification_outbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if p_limit is null or p_lease_seconds is null or p_limit not between 1 and 20 or p_lease_seconds not between 30 and 300 then
        raise exception 'INVALID_OUTBOX_CLAIM' using errcode='22023';
    end if;
    if p_exclude_ids is null or cardinality(p_exclude_ids)>100 or array_position(p_exclude_ids,null) is not null then
        raise exception 'INVALID_OUTBOX_CLAIM' using errcode='22023';
    end if;
    -- Old queued events expire rather than sending obsolete reminders months later.
    with stale as (select id from public.booking_notification_outbox where created_at<now()-interval '30 days'
        and (status='pending' or (status='processing' and lease_until<=now()))
        order by created_at for update skip locked limit p_limit)
    update public.booking_notification_outbox o set status='failed',completed_at=now(),lease_token=null,lease_until=null,
        last_error_code='event_expired' from stale s where o.id=s.id;
    -- A worker crash on its final attempt must also reach a visible dead letter.
    with exhausted as (
        select id from public.booking_notification_outbox where status='processing'
            and lease_until<=now() and attempts>=8 order by created_at for update skip locked limit p_limit
    ) update public.booking_notification_outbox o set status='failed',completed_at=now(),lease_token=null,lease_until=null,
        last_error_code='lease_expired_after_final_attempt' from exhausted e where o.id=e.id;
    return query with candidates as (
        select id from public.booking_notification_outbox
        where not(id=any(p_exclude_ids)) and created_at>=now()-interval '30 days' and attempts<8 and available_at<=now() and (status='pending' or (status='processing' and lease_until<=now()))
        order by available_at,created_at for update skip locked limit p_limit
    ) update public.booking_notification_outbox o set status='processing',attempts=o.attempts+1,
        lease_token=gen_random_uuid(),lease_until=now()+make_interval(secs=>p_lease_seconds)
        from candidates c where o.id=c.id returning o.*;
end;
$function$
;

-- signature: public._confirm_booking_transition(uuid)
CREATE OR REPLACE FUNCTION public._confirm_booking_transition(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_current_status booking_status;
begin
    -- Получаем текущий статус бронирования
    select status into v_current_status
    from public.bookings
    where id = p_booking_id for update;
    
    if not found then
        raise exception 'Booking not found';
    end if;
    
    -- Если статус уже confirmed, просто выходим (идемпотентность)
    if v_current_status = 'confirmed' then
        return;
    end if;
    
    -- Проверяем, что статус можно изменить на 'confirmed'
    if v_current_status not in ('hold') then
        raise exception 'Booking status cannot be changed to confirmed. Current status: %', v_current_status;
    end if;
    
    -- Обновляем статус на 'confirmed' и очищаем expires_at
    update public.bookings
    set status = 'confirmed'::booking_status,
        expires_at = null
    where id = p_booking_id;
    
    if not found then
        raise exception 'Failed to update booking status';
    end if;
end;
$function$
;

-- signature: public._confirm_created_booking(uuid,uuid)
CREATE OR REPLACE FUNCTION public._confirm_created_booking(p_booking_id uuid, p_actor_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_client_id uuid;
begin
  select client_id into v_client_id from public.bookings where id=p_booking_id for update;
  if not found then raise exception 'Booking not found'; end if;
  if v_client_id is distinct from p_actor_id then
    raise exception using errcode='42501',message='BOOKING_FORBIDDEN';
  end if;
  perform public._confirm_booking_transition(p_booking_id);
end;
$function$
;

-- signature: public._hold_complex_slot_for_actor(uuid,uuid,uuid,timestamp with time zone,jsonb,uuid)
CREATE OR REPLACE FUNCTION public._hold_complex_slot_for_actor(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_services jsonb, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_booking_id uuid;
    v_expires_at timestamptz;
    v_client_id uuid;
    v_client_name text;
    v_client_phone text;
    v_client_email text;
    v_total_duration_min integer := 0;
    v_item jsonb;
    v_service_id uuid;
    v_duration_min integer;
    v_order_index integer;
    v_index integer := 0;
    v_end timestamptz;
begin
    -- Текущий пользователь
    v_client_id := p_actor_id;
    if v_client_id is null then
        raise exception 'User must be authenticated';
    end if;

    -- Данные клиента из профиля
    select p.full_name, p.phone, u.email
    into v_client_name, v_client_phone, v_client_email
    from public.profiles p
    join auth.users u on u.id = p.id
    where p.id = v_client_id;

    if not found then
        raise exception 'User profile not found';
    end if;

    -- Проверка филиала
    if not exists (
        select 1
        from public.branches
        where id = p_branch_id
          and biz_id = p_biz_id
          and is_active = true
    ) then
        raise exception 'branch not found or inactive';
    end if;

    -- Проверка мастера
    if not exists (
        select 1
        from public.staff
        where id = p_staff_id
          and biz_id = p_biz_id
          and (branch_id = p_branch_id or exists (select 1 from public.staff_schedule_versions v where v.staff_id = p_staff_id))
          and is_active = true
    ) then
        raise exception 'staff not found or inactive';
    end if;

    if p_services is null or jsonb_typeof(p_services) <> 'array'
       or jsonb_array_length(p_services) = 0 or jsonb_array_length(p_services) > 20 then
        raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;
    if p_start < now() - interval '5 minutes' then
        raise exception using errcode = '22023', message = 'SLOT_IN_PAST';
    end if;

    -- Each service: the branch's, active, performed by the master; duration from the catalog.
    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_service_id := (p_services->v_index->>'service_id')::uuid;
        if v_service_id is null then
            raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
        end if;

        select s.duration_min into v_duration_min
          from public.services s
         where s.id = v_service_id and s.biz_id = p_biz_id and s.branch_id = p_branch_id and s.active = true;
        if not found then
            raise exception using errcode = '22023', message = 'service not found or inactive';
        end if;
        if not public._staff_performs_service(p_staff_id, v_service_id, p_branch_id) then
            raise exception using errcode = '22023', message = 'STAFF_DOES_NOT_PERFORM_SERVICE';
        end if;

        v_total_duration_min := v_total_duration_min + v_duration_min;
    end loop;

    if v_total_duration_min <= 0 then
        raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;

    v_end := p_start + (v_total_duration_min || ' minutes')::interval;
    if not public.schedule_contains_booking(p_staff_id, p_branch_id, p_start, v_end) then
        raise exception 'SCHEDULE_OUTSIDE_WORKING_HOURS';
    end if;

    -- Время истечения резерва (2 минуты)
    v_expires_at := now() + interval '2 minutes';

    -- Проверка пересечений с существующими бронированиями
    if exists (
        select 1
        from public.bookings
        where staff_id = p_staff_id
          and (status in ('confirmed','paid') or (status = 'hold' and expires_at > now()))
          and tstzrange(start_at, end_at, '[)') && tstzrange(p_start, v_end, '[)')
    ) then
        raise exception 'time slot is already booked';
    end if;

    -- Создаём бронирование (service_id = первая услуга комплекса)
    insert into public.bookings (
        biz_id,
        branch_id,
        service_id,
        staff_id,
        client_id,
        client_name,
        client_phone,
        client_email,
        start_at,
        end_at,
        status,
        expires_at
    )
    values (
        p_biz_id,
        p_branch_id,
        (p_services->0->>'service_id')::uuid,
        p_staff_id,
        v_client_id,
        v_client_name,
        v_client_phone,
        v_client_email,
        p_start,
        v_end,
        'hold'::booking_status,
        v_expires_at
    )
    returning id into v_booking_id;

    -- Заполняем booking_services
    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_item := p_services->v_index;
        v_service_id := (v_item->>'service_id')::uuid;
        v_order_index := coalesce((v_item->>'order_index')::integer, v_index);
        select s.duration_min into v_duration_min from public.services s where s.id = v_service_id;

        insert into public.booking_services (
            booking_id,
            service_id,
            duration_min,
            order_index
        )
        values (
            v_booking_id,
            v_service_id,
            v_duration_min,
            v_order_index
        );
    end loop;

    return v_booking_id;
end;
$function$
;

-- signature: public._hold_slot_for_actor(uuid,uuid,uuid,uuid,timestamp with time zone,uuid)
CREATE OR REPLACE FUNCTION public._hold_slot_for_actor(p_biz_id uuid, p_branch_id uuid, p_service_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_client_id uuid;
    v_client_name text;
    v_client_phone text;
    v_client_email text;
    v_service_duration_min int;
    v_end timestamptz;
    v_booking_id uuid;
begin
    v_client_id := p_actor_id;
    if v_client_id is null then
        raise exception 'User must be authenticated';
    end if;

    select coalesce(p.full_name, u.raw_user_meta_data->>'full_name', u.email),
           coalesce(p.phone, u.phone), u.email
    into v_client_name, v_client_phone, v_client_email
    from auth.users u left join public.profiles p on p.id = u.id
    where u.id = v_client_id;
    if not found then raise exception 'User not found'; end if;

    if not exists (select 1 from public.profiles where id = v_client_id) then
        insert into public.profiles (id, full_name, phone)
        values (v_client_id, coalesce(v_client_name, 'Пользователь'), v_client_phone)
        on conflict (id) do nothing;
    end if;

    select duration_min into v_service_duration_min
    from public.services
    where id = p_service_id and biz_id = p_biz_id and branch_id = p_branch_id and active = true;
    if not found then raise exception using errcode = '22023', message = 'service not found or inactive'; end if;

    if not exists (select 1 from public.staff
        where id = p_staff_id and biz_id = p_biz_id and is_active = true)
    then raise exception 'staff not found or inactive'; end if;

    if not exists (select 1 from public.branches
        where id = p_branch_id and biz_id = p_biz_id and is_active = true)
    then raise exception 'branch not found or inactive'; end if;

    if not public._staff_performs_service(p_staff_id, p_service_id, p_branch_id) then
        raise exception using errcode = '22023', message = 'STAFF_DOES_NOT_PERFORM_SERVICE';
    end if;
    if p_start < now() - interval '5 minutes' then
        raise exception using errcode = '22023', message = 'SLOT_IN_PAST';
    end if;

    v_end := p_start + (v_service_duration_min || ' minutes')::interval;
    if not public.schedule_contains_booking(p_staff_id, p_branch_id, p_start, v_end)
    then raise exception 'SCHEDULE_OUTSIDE_WORKING_HOURS'; end if;

    if exists (select 1 from public.bookings
        where staff_id = p_staff_id and status in ('confirmed', 'paid')
        and tstzrange(start_at, end_at, '[)') && tstzrange(p_start, v_end, '[)'))
    then raise exception 'time slot is already booked'; end if;

    insert into public.bookings (
        biz_id, branch_id, service_id, staff_id, client_id,
        client_name, client_phone, client_email, start_at, end_at, status, expires_at
    ) values (
        p_biz_id, p_branch_id, p_service_id, p_staff_id, v_client_id,
        v_client_name, v_client_phone, v_client_email, p_start, v_end,
        'confirmed'::booking_status, null
    ) returning id into v_booking_id;
    return v_booking_id;
end;
$function$
;

-- signature: public._internal_booking_actor_allowed(uuid,uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public._internal_booking_actor_allowed(p_actor uuid, p_biz uuid, p_branch uuid, p_staff uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p_actor is not null and (
    public.finance_can_manage_business(p_actor,p_biz)
    or exists(select 1 from public.branch_admins ba join public.branches b on b.id=ba.branch_id
      where ba.user_id=p_actor and b.id=p_branch and b.biz_id=p_biz)
    or exists(select 1 from public.staff where id=p_staff and biz_id=p_biz and user_id=p_actor and is_active)
    or exists(select 1 from public.user_global_roles u join public.roles r on r.id=u.role_id
      where u.user_id=p_actor and r.scope='platform' and r.key='super_admin')
    or exists(select 1 from public.user_roles u join public.roles r on r.id=u.role_id
      where u.user_id=p_actor and u.biz_id is null and r.key='super_admin')
    or exists(select 1 from public.super_admins_legacy where user_id=p_actor));
$function$
;

-- signature: public._locked_whatsapp_inbox(uuid,uuid)
CREATE OR REPLACE FUNCTION public._locked_whatsapp_inbox(p_id uuid, p_token uuid)
 RETURNS public.whatsapp_inbox
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare item public.whatsapp_inbox;
begin
  perform public._require_whatsapp_inbox_service();
  select * into item from public.whatsapp_inbox where id=p_id for update;
  if not found or item.status<>'processing' or item.lease_token is distinct from p_token or item.lease_until<=clock_timestamp() then
    raise exception 'INBOX_LEASE_LOST';
  end if;
  return item;
end;
$function$
;

-- signature: public._require_whatsapp_inbox_service()
CREATE OR REPLACE FUNCTION public._require_whatsapp_inbox_service()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if coalesce(nullif(current_setting('role',true),'none'),session_user) not in ('service_role','postgres','supabase_admin') then
    raise exception using errcode='42501',message='INBOX_SERVICE_ONLY';
  end if;
end;
$function$
;

-- signature: public._staff_performs_service(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public._staff_performs_service(p_staff_id uuid, p_service_id uuid, p_branch_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select exists (
            select 1 from public.service_staff ss
             where ss.service_id = p_service_id and ss.staff_id = p_staff_id and ss.is_active)
        or exists (
            select 1
              from public.services target
              join public.staff st on st.id = p_staff_id and st.biz_id = target.biz_id
              join public.services own on own.biz_id = target.biz_id and own.id <> target.id
                   and own.name_ru = target.name_ru and own.duration_min = target.duration_min
              join public.service_staff ss on ss.service_id = own.id and ss.staff_id = p_staff_id and ss.is_active
             where target.id = p_service_id and st.branch_id is distinct from p_branch_id)
        or not exists (
            select 1
              from public.services s
              join public.staff st on st.biz_id = s.biz_id
              join public.service_staff ss on ss.staff_id = st.id and ss.is_active
             where s.id = p_service_id);
$function$
;

-- signature: public.adjust_closed_shift_hours_command(uuid,uuid,uuid,bigint,numeric,jsonb)
CREATE OR REPLACE FUNCTION public.adjust_closed_shift_hours_command(p_shift_id uuid, p_biz_id uuid, p_actor_id uuid, p_expected_revision bigint, p_hours_worked numeric, p_calculation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare v_shift public.staff_shifts%rowtype; v_tz text; v_day_hours numeric; v_key text;
    v_role text:=coalesce(nullif(current_setting('role',true),'none'),session_user);
begin
    if v_role not in ('service_role','postgres','supabase_admin') or p_actor_id is null
        or not public.finance_can_manage_business(p_actor_id,p_biz_id) then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform st.id from public.staff st join public.staff_shifts sh on sh.staff_id=st.id
        where sh.id=p_shift_id and sh.biz_id=p_biz_id and st.biz_id=p_biz_id for update of st;
    if not found then raise exception using errcode='P0002',message='SHIFT_NOT_FOUND'; end if;
    select * into v_shift from public.staff_shifts where id=p_shift_id and biz_id=p_biz_id for update;
    if v_shift.status<>'closed' or p_expected_revision is distinct from v_shift.ledger_revision then
        raise exception using errcode='40001',message='SHIFT_STALE_OR_REOPENED';
    end if;
    v_tz:=public.finance_business_timezone(p_biz_id);
    v_day_hours:=extract(epoch from ((v_shift.shift_date+1)::timestamp at time zone v_tz)-(v_shift.shift_date::timestamp at time zone v_tz))/3600;
    if p_hours_worked is null or p_hours_worked::text in ('NaN','Infinity','-Infinity') or p_hours_worked<0 or p_hours_worked>v_day_hours then
        raise exception using errcode='22023',message='SHIFT_HOURS_OUTSIDE_LOCAL_DAY';
    end if;
    if jsonb_typeof(p_calculation) is distinct from 'object' then raise exception using errcode='22023',message='SHIFT_CALCULATION_REQUIRED'; end if;
    foreach v_key in array array['totalAmount','totalConsumables','guaranteedAmount','topupAmount','finalMasterShare','finalSalonShare'] loop
        if jsonb_typeof(p_calculation->v_key) is distinct from 'number' or (p_calculation->>v_key)::numeric<0
            or (p_calculation->>v_key)::numeric::text in ('NaN','Infinity','-Infinity') then raise exception using errcode='22023',message='SHIFT_CALCULATION_INVALID'; end if;
    end loop;
    -- Trusted backend uses core-domain with the persisted inputs read at this revision.
    -- Every shift UPDATE and every ledger write bumps revision, so that input snapshot cannot silently change.
    if (p_calculation->>'totalAmount')::numeric is distinct from coalesce(v_shift.total_amount,0)
        or (p_calculation->>'totalConsumables')::numeric is distinct from coalesce(v_shift.consumables_amount,0) then
        raise exception using errcode='40001',message='SHIFT_CALCULATION_CHANGED';
    end if;
    update public.staff_shifts set hours_worked=p_hours_worked,
        guaranteed_amount=(p_calculation->>'guaranteedAmount')::numeric,topup_amount=(p_calculation->>'topupAmount')::numeric,
        master_share=(p_calculation->>'finalMasterShare')::numeric,salon_share=(p_calculation->>'finalSalonShare')::numeric
        where id=p_shift_id returning * into v_shift;
    perform public.update_shift_aggregates(v_shift.staff_id,v_shift.biz_id,v_shift.shift_date,0,0,0,0,0,0);
    return jsonb_build_object('ok',true,'shift',to_jsonb(v_shift));
end;
$function$
;

-- signature: public.admin_list_users(uuid,text,text,integer,integer)
CREATE OR REPLACE FUNCTION public.admin_list_users(p_actor_id uuid, p_q text DEFAULT NULL::text, p_status text DEFAULT 'all'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_q text := left(nullif(btrim(coalesce(p_q, '')), ''), 200);
    v_status text := coalesce(p_status, 'all');
    v_pattern text;
    v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
    v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 1000000);
    v_result jsonb;
begin
    if coalesce(nullif(current_setting('role', true), 'none'), session_user) not in ('service_role', 'postgres', 'supabase_admin') then
        raise exception using errcode = '42501', message = 'ADMIN_USERS_SERVICE_ONLY';
    end if;
    if p_actor_id is null
       or not exists (select 1 from auth.users where id = p_actor_id)
       or not public.finance_is_platform_admin(p_actor_id) then
        raise exception using errcode = '42501', message = 'ADMIN_USERS_FORBIDDEN';
    end if;
    if v_status not in ('all', 'active', 'blocked') then
        raise exception using errcode = '22023', message = 'ADMIN_USERS_BAD_STATUS';
    end if;
    if v_q is not null then
        -- a literal substring: the backslash is the LIKE escape character
        v_pattern := '%' || replace(replace(replace(v_q, chr(92), chr(92) || chr(92)), '%', chr(92) || '%'), '_', chr(92) || '_') || '%';
    end if;

    with matched as (
        select u.id,
               u.email::text as email,
               u.phone::text as phone,
               u.last_sign_in_at,
               u.created_at,
               coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(u.raw_user_meta_data ->> 'full_name'), '')) as full_name,
               s.user_id is not null as is_blocked,
               s.reason as block_reason
          from auth.users u
          left join public.profiles p on p.id = u.id
          left join lateral (
              select us.user_id, us.reason
                from public.user_suspensions us
               where us.user_id = u.id
               order by us.created_at desc
               limit 1) s on true
         where u.deleted_at is null
           and (v_status = 'all'
                or (v_status = 'blocked' and s.user_id is not null)
                or (v_status = 'active' and s.user_id is null))
           and (v_pattern is null
                or coalesce(u.email::text, '') ilike v_pattern
                or coalesce(u.phone::text, '') ilike v_pattern
                or coalesce(nullif(btrim(p.full_name), ''), u.raw_user_meta_data ->> 'full_name', '') ilike v_pattern
                or u.id::text ilike v_pattern)
    )
    select jsonb_build_object(
        'total', (select count(*) from matched),
        'items', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'id', m.id,
                       'full_name', m.full_name,
                       'email', m.email,
                       'phone', m.phone,
                       'last_sign_in_at', m.last_sign_in_at,
                       'is_blocked', m.is_blocked,
                       'block_reason', m.block_reason)
                   order by m.created_at desc nulls last, m.id desc)
              from (select * from matched
                     order by created_at desc nulls last, id desc
                     limit v_limit offset v_offset) m), '[]'::jsonb))
      into v_result;

    return v_result;
end;
$function$
;

-- signature: public.admin_user_stats(uuid)
CREATE OR REPLACE FUNCTION public.admin_user_stats(p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_result jsonb;
begin
    if coalesce(nullif(current_setting('role', true), 'none'), session_user) not in ('service_role', 'postgres', 'supabase_admin') then
        raise exception using errcode = '42501', message = 'ADMIN_USERS_SERVICE_ONLY';
    end if;
    if p_actor_id is null
       or not exists (select 1 from auth.users where id = p_actor_id)
       or not public.finance_is_platform_admin(p_actor_id) then
        raise exception using errcode = '42501', message = 'ADMIN_USERS_FORBIDDEN';
    end if;

    select jsonb_build_object(
               'total', count(*),
               'active', count(*) filter (where not blocked),
               'blocked', count(*) filter (where blocked),
               'super', count(*) filter (where public.finance_is_platform_admin(id)))
      into v_result
      from (select u.id,
                   exists (select 1 from public.user_suspensions s where s.user_id = u.id) as blocked
              from auth.users u
             where u.deleted_at is null) users;

    return v_result;
end;
$function$
;

-- signature: public.anonymize_inactive_profiles_pii(integer)
CREATE OR REPLACE FUNCTION public.anonymize_inactive_profiles_pii(p_inactive_days integer DEFAULT 1095)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_updated_count integer;
    v_cutoff timestamptz;
begin
    v_cutoff := timezone('utc'::text, now()) - (p_inactive_days || ' days')::interval;

    with inactive as (
        select p.id
        from public.profiles p
        join auth.users u on u.id = p.id
        where (p.full_name is not null or p.phone is not null)
          -- Account age and the latest successful sign-in are both activity.
          and u.created_at < v_cutoff
          and coalesce(u.last_sign_in_at, u.created_at) < v_cutoff
          -- Operational accounts remain identifiable while they hold access.
          and not exists (
              select 1
              from public.staff s
              where s.user_id = p.id
          )
          and not exists (
              select 1
              from public.businesses b
              where b.owner_id = p.id
          )
          and not exists (
              select 1
              from public.user_roles ur
              where ur.user_id = p.id
          )
          and not exists (
              select 1
              from public.user_global_roles ugr
              where ugr.user_id = p.id
          )
          and not exists (
              select 1
              from public.bookings b
              where b.client_id = p.id
                and b.start_at >= v_cutoff
          )
    )
    update public.profiles
    set full_name = 'Anonymized',
        phone = null
    from inactive
    where profiles.id = inactive.id;

    get diagnostics v_updated_count = row_count;
    return v_updated_count;
end;
$function$
;

-- signature: public.anonymize_old_bookings_pii(integer)
CREATE OR REPLACE FUNCTION public.anonymize_old_bookings_pii(p_older_than_days integer DEFAULT 2555)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_updated_count integer;
begin
    update public.bookings
    set
        client_name = case when trim(coalesce(client_name, '')) <> '' then 'Anonymized' else client_name end,
        client_phone = null,
        client_email = null
    where start_at < timezone('utc'::text, now()) - (p_older_than_days || ' days')::interval
      and (client_name is not null or client_phone is not null or client_email is not null);
    get diagnostics v_updated_count = row_count;
    return v_updated_count;
end;
$function$
;

-- signature: public.apply_promotion_to_booking(uuid)
CREATE OR REPLACE FUNCTION public.apply_promotion_to_booking(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_booking record;
    v_base_price numeric;
    v_client_id uuid;
    v_branch_id uuid;
    v_biz_id uuid;
    v_service_id uuid;
    v_promotions public.branch_promotions[];
    v_applied_promotion public.branch_promotions;
    v_discount_percent numeric;
    v_final_amount numeric;
    v_visit_count integer;
    v_promotion_type text;
    v_result jsonb;
    v_usage_data jsonb;
    v_has_referral boolean;
    v_referral_id uuid;
begin
    perform 1 from public.bookings where id=p_booking_id for update;
    perform public.assert_booking_finance_access(p_booking_id);
    if exists(select 1 from public.bookings where id=p_booking_id and promotion_applied is not null) then
        return (select jsonb_build_object('applied',true)||promotion_applied from public.bookings where id=p_booking_id);
    end if;
    -- Получаем данные бронирования
    select 
        b.id, b.client_id, b.branch_id, b.biz_id, b.service_id, b.status,
        s.price_from, s.price_to
    into v_booking
    from public.bookings b
    left join public.services s on s.id = b.service_id
    where b.id = p_booking_id;
    
    if v_booking is null then
        raise exception 'Booking not found';
    end if;
    
    -- Проверяем, что статус = 'paid' (услуга выполнена)
    if v_booking.status != 'paid' then
        return jsonb_build_object('applied', false, 'reason', 'Booking status is not paid');
    end if;
    
    -- Проверяем, что есть client_id (только для авторизованных клиентов)
    if v_booking.client_id is null then
        return jsonb_build_object('applied', false, 'reason', 'No client_id (guest booking)');
    end if;
    
    v_client_id := v_booking.client_id;
    v_branch_id := v_booking.branch_id;
    v_biz_id := v_booking.biz_id;
    v_service_id := v_booking.service_id;
    
    -- Получаем все активные и допустимые по условиям использования акции для этого филиала
    select array_agg(p order by case p.promotion_type
        when 'first_visit_discount' then 1 when 'birthday_discount' then 2
        when 'referral_free' then 3 when 'referral_discount_50' then 4 when 'free_after_n_visits' then 5 else 99 end,p.id)
    into v_promotions from public.branch_promotions p
    where p.branch_id=v_branch_id and p.biz_id=v_biz_id and p.is_active=true
        and (p.valid_from is null or p.valid_from<=current_date)
        and (p.valid_to is null or p.valid_to>=current_date)
        and public.can_use_promotion(v_client_id,v_branch_id,p.id);
    
    -- Если нет доступных акций, возвращаем без изменений
    if v_promotions is null or array_length(v_promotions, 1) = 0 then
        return jsonb_build_object('applied', false, 'reason', 'No applicable promotions');
    end if;
    
    -- Берем первую подходящую акцию (с наивысшим приоритетом)
    v_applied_promotion := v_promotions[1];
    v_promotion_type := v_applied_promotion.promotion_type;
    
    -- Проверяем, не использована ли уже эта акция для этого бронирования
    if exists (
        select 1 from public.client_promotion_usage
        where booking_id = p_booking_id and promotion_id = v_applied_promotion.id
    ) then
        return jsonb_build_object('applied', false, 'reason', 'Promotion already applied to this booking');
    end if;
    
    -- Рассчитываем сумму с учетом акции
    -- Используем price_from как базовую цену (или среднее между price_from и price_to)
        if v_booking.price_from is not null and v_booking.price_to is not null then
            v_base_price := (v_booking.price_from + v_booking.price_to) / 2;
        elsif v_booking.price_from is not null then
            v_base_price := v_booking.price_from;
        elsif v_booking.price_to is not null then
            v_base_price := v_booking.price_to;
        else
            v_base_price := 0;
        end if;
        
        -- Применяем акцию
        case v_promotion_type
            when 'free_after_n_visits', 'referral_free' then
                -- Бесплатная услуга
                v_final_amount := 0;
                v_discount_percent := 100;
                
            when 'referral_discount_50' then
                -- Скидка 50%
                v_final_amount := round(v_base_price * 0.5, 2);
                v_discount_percent := 50;
                
            when 'first_visit_discount', 'birthday_discount' then
                -- Скидка в процентах из параметров
                v_discount_percent := (v_applied_promotion.params->>'discount_percent')::numeric;
                if v_discount_percent is null or v_discount_percent < 0 or v_discount_percent > 100 then
                    v_discount_percent := 0;
                end if;
                v_final_amount := round(v_base_price * (1 - v_discount_percent / 100), 2);
                
            else
                v_final_amount := v_base_price;
                v_discount_percent := 0;
        end case;
    
    -- Записываем использование акции
    v_usage_data := jsonb_build_object(
        'original_amount', v_base_price,
        'final_amount', v_final_amount,
        'discount_percent', v_discount_percent,
        'applied_at', now()
    );
    
    -- Для free_after_n_visits добавляем счетчик посещений
    if v_promotion_type = 'free_after_n_visits' then
        v_visit_count := public.get_client_visit_count(v_client_id, v_branch_id);
        v_usage_data := v_usage_data || jsonb_build_object('visit_count', v_visit_count + 1);
    end if;
    
    -- Для реферальных акций - отмечаем реферальную связь как использованную
    if v_promotion_type in ('referral_free', 'referral_discount_50') then
        -- Находим неиспользованную реферальную связь
        select id into v_referral_id
        from public.client_referrals
        where referrer_id = v_client_id
          and branch_id = v_branch_id
          and referrer_bonus_used = false
        order by id limit 1 for update;
        
        if v_referral_id is null then raise exception using errcode='40001',message='PROMOTION_CHANGED'; end if;
        if v_referral_id is not null then
            -- Отмечаем реферальную связь как использованную
            update public.client_referrals
            set referrer_bonus_used = true, referrer_booking_id = p_booking_id
            where id = v_referral_id;
        end if;
    end if;
    
    -- Сохраняем факт использования акции
    insert into public.client_promotion_usage (
        client_id, branch_id, biz_id, promotion_id, promotion_type,
        booking_id, usage_data
    ) values (
        v_client_id, v_branch_id, v_biz_id, v_applied_promotion.id, v_applied_promotion.promotion_type,
        p_booking_id, v_usage_data
    );
    
    -- Формируем результат
    v_result := jsonb_build_object(
        'applied', true,
        'promotion_id', v_applied_promotion.id,
        'promotion_type', v_promotion_type,
        'promotion_title', v_applied_promotion.title_ru,
        'original_amount', v_base_price,
        'final_amount', v_final_amount,
        'discount_percent', v_discount_percent,
        'discount_amount', v_base_price - v_final_amount
    );
    
    update public.bookings set promotion_applied=(v_result-'applied')||jsonb_build_object('applied_at',now()) where id=p_booking_id;
    return v_result;
end;
$function$
;

-- signature: public.apply_registration_links_to_first_branch()
CREATE OR REPLACE FUNCTION public.apply_registration_links_to_first_branch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    submitted_links jsonb;
begin
    if coalesce(new.directory_links, '{}'::jsonb) <> '{}'::jsonb then
        return new;
    end if;

    if exists (select 1 from public.branches where biz_id = new.biz_id) then
        return new;
    end if;

    select coalesce(directory_links, '{}'::jsonb)
      into submitted_links
      from public.business_registration_applications
     where created_business_id = new.biz_id
       and jsonb_typeof(directory_links) = 'object'
       and directory_links <> '{}'::jsonb
     order by created_at asc
     limit 1;

    if submitted_links is not null and submitted_links <> '{}'::jsonb then
        new.directory_links := submitted_links;
    end if;

    return new;
end;
$function$
;

-- signature: public.apply_visit_package_to_booking_impl_20261109(uuid)
CREATE OR REPLACE FUNCTION public.apply_visit_package_to_booking_impl_20261109(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_cvp_id uuid;
    v_booking record;
    v_plan record;
    v_base_price numeric;
    v_final_amount numeric;
    v_remaining_after int;
    v_plan_name_ru text;
begin
    v_cvp_id := public.get_applicable_visit_package_for_booking(p_booking_id);
    if v_cvp_id is null then
        return jsonb_build_object('applied', false, 'reason', 'No applicable visit package');
    end if;

    select b.id, b.client_id, b.branch_id, b.service_id
    into v_booking
    from public.bookings b
    where b.id = p_booking_id;

    select p.id, p.name_ru, p.discount_type, p.discount_value
    into v_plan
    from public.visit_package_plans p
    join public.client_visit_packages cvp on cvp.plan_id = p.id
    where cvp.id = v_cvp_id;

    select coalesce(
        (select (s.price_from + s.price_to) / 2 from public.services s where s.id = v_booking.service_id),
        (select s.price_from from public.services s where s.id = v_booking.service_id),
        0
    ) into v_base_price;

    if v_base_price is null then
        v_base_price := 0;
    end if;

    if v_plan.discount_type = 'percent' then
        v_final_amount := round(v_base_price * (1 - least(v_plan.discount_value, 100) / 100), 2);
    else
        v_final_amount := least(v_plan.discount_value, v_base_price);
    end if;
    v_final_amount := greatest(0, v_final_amount);

    update public.client_visit_packages
    set remaining_visits = remaining_visits - 1
    where id = v_cvp_id
      and remaining_visits > 0
    returning remaining_visits into v_remaining_after;

    if v_remaining_after is null then
        return jsonb_build_object('applied', false, 'reason', 'Package visit count race');
    end if;

    insert into public.client_visit_package_uses (client_visit_package_id, booking_id)
    values (v_cvp_id, p_booking_id);

    v_plan_name_ru := v_plan.name_ru;

    update public.bookings
    set subscription_applied = jsonb_build_object(
        'plan_id', v_plan.id,
        'plan_name_ru', v_plan_name_ru,
        'client_visit_package_id', v_cvp_id,
        'final_amount', v_final_amount,
        'remaining_after', v_remaining_after,
        'applied_at', now()
    )
    where id = p_booking_id;

    return jsonb_build_object(
        'applied', true,
        'plan_id', v_plan.id,
        'plan_name_ru', v_plan_name_ru,
        'promotion_title', v_plan_name_ru,
        'final_amount', v_final_amount,
        'remaining_after', v_remaining_after
    );
end;
$function$
;

-- signature: public.apply_visit_package_to_booking(uuid)
CREATE OR REPLACE FUNCTION public.apply_visit_package_to_booking(p_booking_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_booking public.bookings%rowtype; v_existing jsonb;
begin
    -- Every debit for the same booking serializes here, including direct RPC retries.
    select * into v_booking from public.bookings where id=p_booking_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform public.assert_finance_access(v_booking.biz_id,v_booking.staff_id);
    v_existing:=v_booking.subscription_applied;
    if exists(select 1 from public.client_visit_package_uses where booking_id=p_booking_id) then
        return jsonb_build_object('applied',true)||coalesce(v_existing,'{}'::jsonb);
    end if;
    return public.apply_visit_package_to_booking_impl_20261109(p_booking_id);
end;
$function$
;

-- signature: public.approve_staff_application(uuid,uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.approve_staff_application(p_application_id uuid, p_reviewer_user_id uuid, p_branch_id uuid, p_is_active boolean DEFAULT true)
 RETURNS TABLE(staff_id uuid, biz_id uuid, branch_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_application public.business_role_applications%rowtype;
    v_role_id uuid;
    v_staff_id uuid;
    v_today date := current_date;
begin
    select *
      into v_application
      from public.business_role_applications
     where id = p_application_id
     for update;

    if not found then
        raise exception using errcode = 'P0002', message = 'application_not_found';
    end if;

    if v_application.status <> 'pending' then
        raise exception using errcode = '23505', message = 'application_already_processed';
    end if;

    if v_application.requested_role <> 'staff' then
        raise exception using errcode = '22023', message = 'application_is_not_staff';
    end if;

    if not exists (
        select 1
          from public.branches b
         where b.id = p_branch_id
           and b.biz_id = v_application.biz_id
           and coalesce(b.is_active, true)
    ) then
        raise exception using errcode = '22023', message = 'invalid_or_inactive_branch';
    end if;

    select r.id
      into v_role_id
      from public.roles r
     where r.key = 'staff'
     limit 1;

    if v_role_id is null then
        raise exception using errcode = 'P0002', message = 'staff_role_not_found';
    end if;

    select s.id
      into v_staff_id
      from public.staff s
     where s.user_id = v_application.applicant_user_id
       and s.biz_id = v_application.biz_id
     for update;

    if v_staff_id is null then
        insert into public.staff (
            user_id,
            biz_id,
            branch_id,
            full_name,
            email,
            phone,
            is_active
        ) values (
            v_application.applicant_user_id,
            v_application.biz_id,
            p_branch_id,
            coalesce(
                nullif(btrim(v_application.applicant_name), ''),
                nullif(btrim(v_application.applicant_email), ''),
                nullif(btrim(v_application.applicant_phone), ''),
                'Сотрудник'
            ),
            v_application.applicant_email,
            v_application.applicant_phone,
            p_is_active
        )
        returning id into v_staff_id;
    else
        update public.staff
           set branch_id = p_branch_id,
               is_active = p_is_active,
               email = coalesce(email, v_application.applicant_email),
               phone = coalesce(phone, v_application.applicant_phone)
         where id = v_staff_id;
    end if;

    insert into public.user_roles (user_id, role_id, biz_id)
    select v_application.applicant_user_id, v_role_id, v_application.biz_id
     where not exists (
        select 1
          from public.user_roles ur
         where ur.user_id = v_application.applicant_user_id
           and ur.role_id = v_role_id
           and ur.biz_id = v_application.biz_id
    );

    insert into public.staff_branch_assignments (
        biz_id,
        staff_id,
        branch_id,
        valid_from
    )
    select v_application.biz_id, v_staff_id, p_branch_id, v_today
     where not exists (
        select 1
          from public.staff_branch_assignments sba
         where sba.biz_id = v_application.biz_id
           and sba.staff_id = v_staff_id
           and sba.branch_id = p_branch_id
           and sba.valid_to is null
    );

    update public.business_role_applications
       set status = 'approved',
           reviewed_at = now(),
           reviewed_by = p_reviewer_user_id,
           review_note = null,
           updated_at = now()
     where id = p_application_id;

    return query
    select v_staff_id, v_application.biz_id, p_branch_id;
end;
$function$
;

-- signature: public.assert_booking_finance_access(uuid)
CREATE OR REPLACE FUNCTION public.assert_booking_finance_access(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_booking record;
begin
    select biz_id,staff_id into v_booking from public.bookings where id=p_booking_id;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform public.assert_finance_access(v_booking.biz_id,v_booking.staff_id);
end;
$function$
;

-- signature: public.assert_finance_access(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.assert_finance_access(p_biz_id uuid, p_staff_id uuid DEFAULT NULL::uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_actor uuid;
begin
    -- Only a trusted service caller may supply an actor. User RPCs always use their JWT identity.
    v_actor := case when auth.role()='service_role' then p_actor_id else auth.uid() end;
    if p_biz_id is null or not exists(select 1 from public.businesses where id=p_biz_id) then
        raise exception using errcode='42501', message='FINANCE_FORBIDDEN';
    end if;
    if p_staff_id is not null and not exists(select 1 from public.staff where id=p_staff_id and biz_id=p_biz_id) then
        raise exception using errcode='42501', message='FINANCE_FORBIDDEN';
    end if;
    if auth.role()='service_role' and p_actor_id is null then return; end if;
    if public.finance_can_manage_business(v_actor,p_biz_id) then return; end if;
    if p_staff_id is not null and exists(select 1 from public.staff
        where id=p_staff_id and biz_id=p_biz_id and user_id=v_actor and is_active=true) then return; end if;
    raise exception using errcode='42501', message='FINANCE_FORBIDDEN';
end;
$function$
;

-- signature: public.audit_business_creation()
CREATE OR REPLACE FUNCTION public.audit_business_creation()
 RETURNS trigger
 LANGUAGE plpgsql
