    );
    return new;
end;
$function$
;

-- signature: public.begin_booking_notification_delivery(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.begin_booking_notification_delivery(p_event_id uuid, p_lease_token uuid, p_delivery_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox; v_delivery public.booking_notification_deliveries;
begin
    select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
    if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp()+interval '15 seconds' then
        raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
    end if;
    if not exists(select 1 from public.bookings where id=v_event.booking_id and notification_revision=v_event.booking_revision) then
        return 'obsolete';
    end if;
    select * into v_delivery from public.booking_notification_deliveries where event_id=p_event_id and delivery_key=p_delivery_key for update;
    if not found then raise exception 'OUTBOX_DELIVERY_NOT_FOUND' using errcode='P0002'; end if;
    if v_delivery.status in ('sent','failed','ambiguous') then return v_delivery.status; end if;
    if (v_delivery.channel<>'email' and v_delivery.status='sending') or
       (v_delivery.channel='email' and v_delivery.first_attempt_at<=now()-interval '23 hours') then
        update public.booking_notification_deliveries set status='ambiguous',last_error_code='provider_outcome_unknown'
            where event_id=p_event_id and delivery_key=p_delivery_key;
        return 'ambiguous';
    end if;
    update public.booking_notification_deliveries set status='sending',attempts=attempts+1,
        first_attempt_at=coalesce(first_attempt_at,now()) where event_id=p_event_id and delivery_key=p_delivery_key;
    return 'send';
end;
$function$
;

-- signature: public.begin_whatsapp_inbox_reply(uuid,uuid)
CREATE OR REPLACE FUNCTION public.begin_whatsapp_inbox_reply(p_id uuid, p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare item public.whatsapp_inbox;
begin
  item:=public._locked_whatsapp_inbox(p_id,p_token);
  if item.reply_payload is null or item.reply_started_at is not null then raise exception 'INBOX_REPLY_NOT_SENDABLE'; end if;
  if item.provider_timestamp<clock_timestamp()-interval '24 hours' then raise exception 'INBOX_MESSAGE_EXPIRED'; end if;
  update public.whatsapp_inbox set reply_started_at=clock_timestamp() where id=p_id;
end;
$function$
;

-- signature: public.booking_notification_backlog_health()
CREATE OR REPLACE FUNCTION public.booking_notification_backlog_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with state as (select o.*, (o.attempts<8 and o.created_at>=now()-interval '30 days' and o.available_at<=now()
    and (o.status='pending' or (o.status='processing' and o.lease_until<=now()))) as due
    from public.booking_notification_outbox o)
  select jsonb_build_object('pending',count(*) filter(where status='pending'),
    'due',count(*) filter(where due),'processing',count(*) filter(where status='processing'),
    'failed',count(*) filter(where status='failed'),
    'ambiguous',count(*) filter(where exists(select 1 from public.booking_notification_deliveries d where d.event_id=state.id and d.status='ambiguous')),
    'oldest_due_age_seconds',coalesce(greatest(0,extract(epoch from now()-min(created_at) filter(where due))),0)) from state;
$function$
;

-- signature: public.booking_notification_enqueue_trigger()
CREATE OR REPLACE FUNCTION public.booking_notification_enqueue_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_type text;
begin
    if tg_op='UPDATE' and new.notification_revision=old.notification_revision then return new; end if;
    v_type:=case new.status::text when 'hold' then 'hold' when 'pending_hold' then 'hold' when 'confirmed' then 'confirm' when 'cancelled' then 'cancel' end;
    if v_type is not null then perform public.enqueue_booking_notification(new.id,v_type); end if;
    return new;
end;
$function$
;

-- signature: public.booking_notification_revision_guard()
CREATE OR REPLACE FUNCTION public.booking_notification_revision_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if tg_op='INSERT' then new.notification_revision:=0;
    elsif (new.status,new.start_at,new.end_at,new.staff_id,new.branch_id,new.biz_id,new.service_id)
        is distinct from (old.status,old.start_at,old.end_at,old.staff_id,old.branch_id,old.biz_id,old.service_id) then
        new.notification_revision:=old.notification_revision+1;
    else new.notification_revision:=old.notification_revision;
    end if;
    return new;
end;
$function$
;

-- signature: public.booking_receipt_public(uuid)
CREATE OR REPLACE FUNCTION public.booking_receipt_public(p_id uuid)
 RETURNS TABLE(id uuid, status public.booking_status, start_at timestamp with time zone, end_at timestamp with time zone, staff_name text, services jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select b.id, b.status, b.start_at, b.end_at, st.full_name,
    case when exists(select 1 from public.booking_services bs where bs.booking_id=b.id)
      then (select jsonb_agg(jsonb_build_object(
        'name_ru',s.name_ru,'name_ky',s.name_ky,'name_en',s.name_en,
        'duration_min',bs.duration_min) order by bs.order_index,bs.service_id)
        from public.booking_services bs join public.services s on s.id=bs.service_id
        where bs.booking_id=b.id)
      else jsonb_build_array(jsonb_build_object(
        'name_ru',primary_service.name_ru,'name_ky',primary_service.name_ky,
        'name_en',primary_service.name_en,'duration_min',primary_service.duration_min))
    end
  from public.bookings b
  join public.staff st on st.id=b.staff_id
  join public.services primary_service on primary_service.id=b.service_id
  where b.id=p_id;
$function$
;

-- signature: public.branch_admins_effective(uuid)
CREATE OR REPLACE FUNCTION public.branch_admins_effective(p_branch_id uuid)
 RETURNS TABLE(user_id uuid, source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    v_biz_id uuid;
BEGIN
    -- Получаем biz_id филиала
    SELECT biz_id INTO v_biz_id
    FROM branches
    WHERE id = p_branch_id;
    
    IF v_biz_id IS NULL THEN
        RETURN;
    END IF;
    
    -- Возвращаем UNION всех администраторов:
    -- 1. Владелец бизнеса
    RETURN QUERY
    SELECT 
        b.owner_id as user_id,
        'owner'::text as source
    FROM businesses b
    WHERE b.id = v_biz_id
      AND b.owner_id IS NOT NULL;
    
    -- 2. Администраторы бизнеса (через user_roles с ролью 'admin')
    RETURN QUERY
    SELECT DISTINCT
        ur.user_id,
        'biz_admin'::text as source
    FROM user_roles ur
    JOIN roles r ON ur.role_id = r.id
    WHERE ur.biz_id = v_biz_id
      AND r.key = 'admin';
    
    -- 3. Явные администраторы филиала
    RETURN QUERY
    SELECT 
        ba.user_id,
        'branch_admin'::text as source
    FROM branch_admins ba
    WHERE ba.branch_id = p_branch_id;
    
END;
$function$
;

