$function$
;

-- signature: public.can_use_promotion(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.can_use_promotion(p_client_id uuid, p_branch_id uuid, p_promotion_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_promotion public.branch_promotions;
    v_visit_count integer;
    v_has_referral boolean;
    v_is_first_visit boolean;
    v_today_birthday boolean;
begin
    -- Получаем акцию
    select * into v_promotion
    from public.branch_promotions
    where id = p_promotion_id
      and branch_id = p_branch_id
      and is_active = true
      and (valid_from is null or valid_from <= CURRENT_DATE)
      and (valid_to is null or valid_to >= CURRENT_DATE);
    
    if v_promotion is null then
        return false; -- Акция не найдена или неактивна
    end if;
    
    -- Проверяем по типу акции
    case v_promotion.promotion_type
        when 'free_after_n_visits' then
            -- Для free_after_n_visits: проверяем, что текущее количество посещений кратно N-1
            -- Например, для 7-й услуги бесплатно: visit_count должно быть 6, 13, 20, и т.д.
            v_visit_count := public.get_client_visit_count(p_client_id, p_branch_id);
            declare
                v_n integer := (v_promotion.params->>'visit_count')::integer;
            begin
                if v_n is null or v_n < 1 then
                    return false;
                end if;
                -- Проверяем, что следующее посещение будет N-м (например, 7-м)
                return (v_visit_count + 1) % v_n = 0;
            end;
            
        when 'referral_free', 'referral_discount_50' then
            -- Для реферальных акций: проверяем, что у клиента есть неиспользованный бонус
            select exists (
                select 1
                from public.client_referrals
                where referrer_id = p_client_id
                  and branch_id = p_branch_id
                  and referrer_bonus_used = false
            ) into v_has_referral;
            return v_has_referral;
            
        when 'first_visit_discount' then
            -- Для скидки за первый визит: проверяем, что это первый визит в этот филиал
            v_visit_count := public.get_client_visit_count(p_client_id, p_branch_id);
            return v_visit_count = 0;
            
        when 'birthday_discount' then
            -- Для скидки в день рождения: проверяем, что сегодня день рождения клиента
            -- TODO: Нужно добавить поле birthday в profiles или clients
            -- Пока возвращаем false
            return false;
            
        else
            return false;
    end case;
end;
$function$
;

-- signature: public.cancel_booking(uuid)
CREATE OR REPLACE FUNCTION public.cancel_booking(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
declare v_booking public.bookings;
begin
  v_booking := public._assert_booking_transition_access(p_booking_id);
  if v_booking.status='cancelled' then return; end if;
  if v_booking.status='paid' or v_booking.promotion_applied is not null
    or v_booking.subscription_applied is not null
    or exists(select 1 from public.staff_shift_items i where i.booking_id=p_booking_id) then
    raise exception using errcode='P0001',message='BOOKING_FINANCIAL_REVERSAL_REQUIRED';
  end if;
  if v_booking.status not in ('hold','confirmed') then
    raise exception using errcode='P0001',message='BOOKING_STATUS_NOT_CANCELLABLE';
  end if;
  update public.bookings set status='cancelled',expires_at=null where id=p_booking_id;
end;
$function$
;

-- signature: public.cancel_business_role_application(uuid,uuid)
CREATE OR REPLACE FUNCTION public.cancel_business_role_application(p_application_id uuid, p_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_biz_id uuid;
    v_role text;
begin
    update public.business_role_applications
       set status = 'cancelled', updated_at = now()
     where id = p_application_id
       and applicant_user_id = p_user_id
       and status = 'pending'
     returning biz_id, requested_role into v_biz_id, v_role;

    if not found then return false; end if;

    insert into public.application_moderation_actions(
        application_kind, application_id, action, actor_user_id,
        target_user_id, biz_id, reason
    ) values (
        v_role, p_application_id, 'cancelled', p_user_id,
        p_user_id, v_biz_id, 'Отозвано заявителем'
    );
    return true;
end;
$function$
;

-- signature: public.cat_remove_slug(text)
CREATE OR REPLACE FUNCTION public.cat_remove_slug(the_slug text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_count integer;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception 'forbidden' using errcode = 'P0001';
    end if;

    update public.businesses
       set categories = array(
               select x from unnest(coalesce(categories, '{}'::text[])) as t(x) where x <> the_slug)
     where categories @> array[the_slug];
    get diagnostics v_count = row_count;
    return v_count;
end;
$function$
;

-- signature: public.cat_replace_slug(text,text)
CREATE OR REPLACE FUNCTION public.cat_replace_slug(old_slug text, new_slug text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_count integer;
begin
    if coalesce(auth.role(), '') <> 'service_role' then
        raise exception 'forbidden' using errcode = 'P0001';
    end if;

    update public.businesses
       set categories = array(
               select case when x = old_slug then new_slug else x end
                 from unnest(coalesce(categories, '{}'::text[])) as t(x))
     where categories @> array[old_slug];
    get diagnostics v_count = row_count;
    return v_count;
end;
$function$
;

-- signature: public.categories_with_usage_v2()
CREATE OR REPLACE FUNCTION public.categories_with_usage_v2()
 RETURNS TABLE(id uuid, name_ru text, slug text, is_active boolean, usage_count integer)
 LANGUAGE sql
 STABLE
AS $function$
  select
    c.id,
    c.name_ru,
    c.slug,
    c.is_active,
    coalesce(count(b.id), 0)::int as usage_count
  from public.categories c
  left join public.businesses b
    on c.slug = any (coalesce(b.categories, '{}'::text[]))
  group by c.id, c.name_ru, c.slug, c.is_active
  order by c.name_ru asc
$function$
;

-- signature: public.check_booking_branch_match()
CREATE OR REPLACE FUNCTION public.check_booking_branch_match()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_date date;
    v_exists_in_assignments boolean;
    v_exists_in_schedule_rules boolean;
begin
    -- Explicit schedules determine the work location, without duplicate assignments.
    if exists(select 1 from public.staff_schedule_versions where staff_id=NEW.staff_id) then
        -- check_explicit_schedule_booking owns validation and locking. Do not
        -- revalidate historical bookings on unrelated financial/status updates.
        return NEW;
    end if;
    -- Дата брони
    v_date := (NEW.start_at)::date;

    -- Проверяем, что в истории назначений есть запись для этого мастера,
    -- филиала и бизнеса, перекрывающая дату брони.
    select exists (
        select 1
        from public.staff_branch_assignments sba
        where sba.staff_id = NEW.staff_id
          and sba.branch_id = NEW.branch_id
          and sba.biz_id = NEW.biz_id
          and sba.valid_from <= v_date
          and (sba.valid_to is null or sba.valid_to >= v_date)
    )
    into v_exists_in_assignments;

    -- Также проверяем временные переводы через staff_schedule_rules
    select exists (
        select 1
        from public.staff_schedule_rules ssr
        where ssr.staff_id = NEW.staff_id
          and ssr.branch_id = NEW.branch_id
          and ssr.biz_id = NEW.biz_id
          and ssr.kind = 'date'
          and ssr.date_on = v_date
          and ssr.is_active = true
    )
    into v_exists_in_schedule_rules;

    -- Если нет ни в assignments, ни в schedule_rules - ошибка
    if not v_exists_in_assignments and not v_exists_in_schedule_rules then
        raise exception
            'Staff % is not assigned to branch % on date %',
            NEW.staff_id, NEW.branch_id, v_date
            using errcode = '22023';
    end if;

    return NEW;
end;
$function$
;

-- signature: public.check_explicit_schedule_booking()
CREATE OR REPLACE FUNCTION public.check_explicit_schedule_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    perform 1 from public.staff where id=new.staff_id for update;
    if new.status::text in ('hold','confirmed','paid')
        and exists(select 1 from public.staff_schedule_versions where staff_id=new.staff_id)
        and (TG_OP='INSERT' or new.start_at is distinct from old.start_at or new.end_at is distinct from old.end_at
             or new.staff_id is distinct from old.staff_id or new.branch_id is distinct from old.branch_id
             or (new.status::text in ('confirmed','paid') and old.status::text not in ('confirmed','paid')))
    then
        if not public.schedule_contains_booking(new.staff_id,new.branch_id,new.start_at,new.end_at)
            then raise exception 'SCHEDULE_OUTSIDE_WORKING_HOURS'; end if;
        if exists(select 1 from public.bookings b where b.staff_id=new.staff_id and b.id is distinct from new.id
            and (b.status::text in ('confirmed','paid') or (b.status::text='hold' and b.expires_at>now()))
            and tstzrange(b.start_at,b.end_at,'[)') && tstzrange(new.start_at,new.end_at,'[)'))
            then raise exception 'SCHEDULE_SLOT_TAKEN'; end if;
    end if;
    return new;
end;
$function$
;

-- signature: public.check_owner_not_suspended()
CREATE OR REPLACE FUNCTION public.check_owner_not_suspended()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.owner_id is null then
    return new;
  end if;

  if exists (select 1 from public.user_suspensions s where s.user_id = new.owner_id) then
    raise exception 'USER_SUSPENDED';
  end if;

  return new;
end
$function$
;

-- signature: public.check_user_lifecycle_request()
CREATE OR REPLACE FUNCTION public.check_user_lifecycle_request()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if not public.user_lifecycle_access_allowed() then raise exception 'USER_SESSION_REVOKED' using errcode='42501'; end if;
end;
$function$
;

-- signature: public.claim_booking_notification_batch(integer,integer,uuid[])
CREATE OR REPLACE FUNCTION public.claim_booking_notification_batch(p_limit integer, p_lease_seconds integer, p_exclude_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_result jsonb;
begin
  if p_limit is null or p_limit not between 1 and 2 then raise exception 'INVALID_OUTBOX_CLAIM' using errcode='22023'; end if;
  select coalesce(jsonb_agg(to_jsonb(e)),'[]') into v_result
    from public._claim_booking_notifications(p_limit,p_lease_seconds,p_exclude_ids) e;
  return v_result;
end;
$function$
;

-- signature: public.claim_overdue_staff_shifts(uuid,integer,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.claim_overdue_staff_shifts(p_claim_token uuid, p_limit integer DEFAULT 25, p_now timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
 SET lock_timeout TO '2s'
AS $function$
declare v_ids uuid[]; v_rows jsonb; v_more boolean; v_configuration_errors jsonb;
begin
    if p_claim_token is null or p_now is null or p_limit not between 1 and 100 then raise exception using errcode='22023',message='CLOSE_BATCH_INVALID'; end if;
    -- Old failures rotate behind never-attempted work; the lease prevents two
    -- schedulers claiming the same shift after the short row-lock transaction ends.
    select coalesce(array_agg(id),'{}'::uuid[]) into v_ids from (
        select sh.id from public.staff_shifts sh join public.businesses b on b.id=sh.biz_id
        join pg_catalog.pg_timezone_names tz on tz.name=coalesce(nullif(btrim(b.tz),''),'Asia/Bishkek')
        left join public.staff_shift_close_attempts a on a.shift_id=sh.id
        where sh.status='open' and sh.shift_date<(p_now at time zone tz.name)::date
            and (a.shift_id is null or a.lease_until<=p_now)
        order by coalesce(a.attempted_at,'-infinity'::timestamptz),sh.shift_date,sh.id
        limit p_limit for update of sh skip locked
    ) selected;
    insert into public.staff_shift_close_attempts(shift_id,attempted_at,lease_until,claim_token)
        select unnest(v_ids),p_now,p_now+interval '5 minutes',p_claim_token
        on conflict(shift_id) do update set attempted_at=excluded.attempted_at,lease_until=excluded.lease_until,claim_token=excluded.claim_token;
    select coalesce(jsonb_agg(public.read_staff_shift_close_snapshot(sh.biz_id,sh.staff_id,sh.id) order by sh.shift_date,sh.id),'[]'::jsonb)
        into v_rows from public.staff_shifts sh where sh.id=any(v_ids);
    select exists(select 1 from public.staff_shifts sh join public.businesses b on b.id=sh.biz_id
        join pg_catalog.pg_timezone_names tz on tz.name=coalesce(nullif(btrim(b.tz),''),'Asia/Bishkek') where sh.status='open'
        and sh.shift_date<(p_now at time zone tz.name)::date and not(sh.id=any(v_ids))) into v_more;
    select coalesce(jsonb_agg(message),'[]'::jsonb) into v_configuration_errors from (
        select distinct b.id::text||': invalid_business_timezone' as message from public.businesses b join public.staff_shifts sh on sh.biz_id=b.id
        where sh.status='open' and not exists(select 1 from pg_catalog.pg_timezone_names where name=coalesce(nullif(btrim(b.tz),''),'Asia/Bishkek')) limit 25
    ) invalid;
    v_more:=v_more or jsonb_array_length(v_configuration_errors)>0;
    return jsonb_build_object('rows',v_rows,'hasMore',v_more,'configurationErrors',v_configuration_errors);
end;
$function$
;

-- signature: public.claim_whatsapp_inbox(text,integer)
CREATE OR REPLACE FUNCTION public.claim_whatsapp_inbox(p_receiver text, p_limit integer DEFAULT 4)
 RETURNS TABLE(id uuid, lease_token uuid, attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
begin
  perform public._require_whatsapp_inbox_service();
  if p_receiver is null or p_receiver !~ '^[0-9]{1,32}$' or p_limit is null or p_limit not between 1 and 4 then raise exception 'INBOX_INVALID_INPUT'; end if;
  -- Bounded maintenance also recovers a crashed final attempt and uncertain send.
  with stale as (
    select i.id from public.whatsapp_inbox i where i.receiver=p_receiver and i.status in ('pending','processing')
      and (i.status='pending' or i.lease_until<=clock_timestamp())
      and (i.reply_started_at is not null or i.attempts>=8 or i.provider_timestamp<clock_timestamp()-interval '24 hours'
        or (i.command_receipt is null and exists(select 1 from public.whatsapp_messages m where m.whatsapp_message_id=i.message_id)))
    order by i.created_at for update skip locked limit 100
  ) update public.whatsapp_inbox i set
      status=case when i.reply_started_at is not null then 'ambiguous' when i.command_receipt is null and exists(select 1 from public.whatsapp_messages m where m.whatsapp_message_id=i.message_id) then 'legacy_manual' when i.attempts>=8 then 'failed' else 'expired' end,
      last_error_code=case when i.reply_started_at is not null then 'reply_outcome_unknown' when i.command_receipt is null and exists(select 1 from public.whatsapp_messages m where m.whatsapp_message_id=i.message_id) then 'legacy_outcome_unknown' when i.attempts>=8 then 'attempts_exhausted' else 'message_expired' end,
      completed_at=clock_timestamp(),lease_token=null,lease_until=null
    from stale where i.id=stale.id;
  return query with candidates as (
    select i.id from public.whatsapp_inbox i where i.receiver=p_receiver and i.status in ('pending','processing')
      and (i.status='pending' or i.lease_until<=clock_timestamp()) and i.available_at<=clock_timestamp()
      and i.attempts<8 and i.reply_started_at is null and i.provider_timestamp>=clock_timestamp()-interval '24 hours'
      and (i.command_receipt is not null or not exists(select 1 from public.whatsapp_messages m where m.whatsapp_message_id=i.message_id))
    order by i.created_at,i.id for update skip locked limit p_limit
  ) update public.whatsapp_inbox i set status='processing',attempts=i.attempts+1,lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '90 seconds'
    from candidates where i.id=candidates.id returning i.id,i.lease_token,i.attempts;
end;
$function$
;

-- signature: public.cleanup_expired_telegram_mobile_auth_attempts(integer)
CREATE OR REPLACE FUNCTION public.cleanup_expired_telegram_mobile_auth_attempts(p_keep_minutes integer DEFAULT 1440)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_deleted_count integer;
begin
    delete from public.telegram_mobile_auth_attempts
    where expires_at < timezone('utc'::text, now())
        - (greatest(p_keep_minutes, 0) || ' minutes')::interval;

    get diagnostics v_deleted_count = row_count;
    return v_deleted_count;
end;
$function$
;

