-- signature: public.cleanup_old_api_metrics(integer)
CREATE OR REPLACE FUNCTION public.cleanup_old_api_metrics(p_keep_days integer DEFAULT 30)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_deleted_count integer;
begin
    -- Удаляем метрики старше указанного количества дней
    -- Оставляем только ошибки (4xx/5xx) навсегда
    delete from public.api_request_metrics
    where created_at < timezone('utc'::text, now()) - (p_keep_days || ' days')::interval
      and status_code < 400;
    
    get diagnostics v_deleted_count = row_count;
    
    return v_deleted_count;
end;
$function$
;

-- signature: public.cleanup_old_finance_logs(integer)
CREATE OR REPLACE FUNCTION public.cleanup_old_finance_logs(p_keep_days integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_deleted_count integer;
begin
    -- Удаляем логи старше указанного количества дней
    -- Оставляем только ошибки (error level) навсегда
    delete from public.staff_finance_operation_logs
    where created_at < timezone('utc'::text, now()) - (p_keep_days || ' days')::interval
      and log_level != 'error';
    
    get diagnostics v_deleted_count = row_count;
    
    return v_deleted_count;
end;
$function$
;

