-- signature: public.close_staff_shift_command(uuid,uuid,bigint,jsonb,jsonb)
CREATE OR REPLACE FUNCTION public.close_staff_shift_command(p_shift_id uuid, p_actor_id uuid, p_expected_revision bigint, p_expected_settings jsonb, p_calculation jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '10s'
 SET lock_timeout TO '2s'
AS $function$
declare v_shift public.staff_shifts%rowtype; v_staff record; v_booking record; v_result jsonb; v_total numeric; v_consumables numeric;
begin
    -- Only the trusted backend may submit a result computed by core-domain.
    if auth.role() is distinct from 'service_role' then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    select s.* into v_staff from public.staff s join public.staff_shifts sh on sh.staff_id=s.id where sh.id=p_shift_id for update of s;
    select * into v_shift from public.staff_shifts where id=p_shift_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform public.assert_finance_access(v_shift.biz_id,v_shift.staff_id,p_actor_id);
    if v_shift.status='closed' then return jsonb_build_object('ok',true,'action','already_closed','shift',to_jsonb(v_shift)); end if;
    if v_shift.status<>'open' then raise exception using errcode='40001',message='SHIFT_CLOSED'; end if;
    if p_expected_revision is null or v_shift.ledger_revision<>p_expected_revision then
        raise exception using errcode='40001',message='SHIFT_STALE';
    end if;
    if jsonb_build_object('percent_master',v_staff.percent_master,'percent_salon',v_staff.percent_salon,'hourly_rate',v_staff.hourly_rate)
        is distinct from p_expected_settings then raise exception using errcode='40001',message='SHIFT_SETTINGS_CHANGED'; end if;
    if jsonb_typeof(p_calculation) is distinct from 'object' then raise exception using errcode='22023',message='SHIFT_CALCULATION_INVALID'; end if;
    if (p_calculation->>'closedAt')::timestamptz < (v_shift.shift_date::timestamp at time zone public.finance_business_timezone(v_shift.biz_id))
        or (p_calculation->>'closedAt')::timestamptz > ((v_shift.shift_date+1)::timestamp at time zone public.finance_business_timezone(v_shift.biz_id))
        or (v_shift.opened_at is not null and (v_shift.opened_at < (v_shift.shift_date::timestamp at time zone public.finance_business_timezone(v_shift.biz_id))
            or v_shift.opened_at > (p_calculation->>'closedAt')::timestamptz)) then
        raise exception using errcode='22023',message='SHIFT_TIME_OUTSIDE_LOCAL_DAY';
    end if;
    if exists(select 1 from public.staff_shift_items where shift_id=p_shift_id) then
        select sum(service_amount),sum(consumables_amount) into v_total,v_consumables from public.staff_shift_items where shift_id=p_shift_id;
        if v_total is distinct from (p_calculation->>'totalAmount')::numeric or v_consumables is distinct from (p_calculation->>'totalConsumables')::numeric then
            raise exception using errcode='40001',message='SHIFT_STALE';
        end if;
    end if;
    -- Validate every persisted relationship under the same transaction before finalizing.
    if exists(select 1 from public.staff_shift_items i left join public.bookings b on b.id=i.booking_id
        where i.shift_id=p_shift_id and i.booking_id is not null and (b.id is null or b.biz_id<>v_shift.biz_id
            or b.staff_id<>v_shift.staff_id or (b.start_at at time zone public.finance_business_timezone(v_shift.biz_id))::date<>v_shift.shift_date)) then
        raise exception using errcode='42501',message='SHIFT_BOOKING_SCOPE';
    end if;
    for v_booking in select b.* from public.bookings b where (b.biz_id=v_shift.biz_id and b.staff_id=v_shift.staff_id
        and (b.start_at at time zone public.finance_business_timezone(v_shift.biz_id))::date=v_shift.shift_date)
        or exists(select 1 from public.staff_shift_items i where i.shift_id=p_shift_id and i.booking_id=b.id)
        order by b.id for update loop
        if p_actor_id is null and v_booking.status in ('paid','confirmed')
            and not exists(select 1 from public.staff_shift_items where shift_id=p_shift_id) then
            raise exception using errcode='40001',message='SHIFT_NEEDS_REVIEW';
        end if;
        if exists(select 1 from public.staff_shift_items where shift_id=p_shift_id and booking_id=v_booking.id) then
            if v_booking.status='cancelled' then raise exception using errcode='22023',message='SHIFT_BOOKING_CANCELLED'; end if;
            if v_booking.biz_id is distinct from v_shift.biz_id or v_booking.staff_id is distinct from v_shift.staff_id
                or (v_booking.start_at at time zone public.finance_business_timezone(v_shift.biz_id))::date is distinct from v_shift.shift_date then
                raise exception using errcode='42501',message='SHIFT_BOOKING_SCOPE';
            end if;
            if v_booking.status not in ('paid','no_show') then perform public.update_booking_status_with_promotion(v_booking.id,'paid'); end if;
        elsif v_booking.status='hold' then
            perform public.update_booking_status_no_check(v_booking.id,'no_show');
        end if;
    end loop;
    if exists(select 1 from public.staff_shift_items i join public.bookings b on b.id=i.booking_id where i.shift_id=p_shift_id
        and coalesce(b.subscription_applied,b.promotion_applied)->>'final_amount' is not null
        and i.service_amount is distinct from (coalesce(b.subscription_applied,b.promotion_applied)->>'final_amount')::numeric) then
        raise exception using errcode='40001',message='SHIFT_PRICING_CHANGED';
    end if;
    v_result:=public.close_staff_shift_safe(p_shift_id,
        (p_calculation->>'totalAmount')::numeric,(p_calculation->>'totalConsumables')::numeric,
        (p_calculation->>'normalizedPercentMaster')::numeric,(p_calculation->>'normalizedPercentSalon')::numeric,
        (p_calculation->>'finalMasterShare')::numeric,(p_calculation->>'finalSalonShare')::numeric,
        (p_calculation->>'hoursWorked')::numeric,(p_calculation->>'hourlyRate')::numeric,
        (p_calculation->>'guaranteedAmount')::numeric,(p_calculation->>'topupAmount')::numeric,
        (p_calculation->>'closedAt')::timestamptz);
    -- The legacy function catches SQL exceptions. Re-raise so earlier attendance/package writes roll back too.
    if v_result->>'ok' is distinct from 'true' then raise exception using errcode='P0001',message='SHIFT_CLOSE_FAILED'; end if;
    return v_result;
end;
$function$
;

-- signature: public.close_staff_shift_safe(uuid,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,numeric,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.close_staff_shift_safe(p_shift_id uuid, p_total_amount numeric DEFAULT 0, p_consumables_amount numeric DEFAULT 0, p_percent_master numeric DEFAULT 60, p_percent_salon numeric DEFAULT 40, p_master_share numeric DEFAULT 0, p_salon_share numeric DEFAULT 0, p_hours_worked numeric DEFAULT NULL::numeric, p_hourly_rate numeric DEFAULT NULL::numeric, p_guaranteed_amount numeric DEFAULT 0, p_topup_amount numeric DEFAULT 0, p_closed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
    v_existing_status text;
    v_result jsonb;
    v_shift_record public.staff_shifts%rowtype;
begin
    -- Lock row and load full shift record
    select *
    into v_shift_record
    from public.staff_shifts
    where id = p_shift_id
    for update;

    v_existing_status := v_shift_record.status;

    -- Shift not found
    if v_existing_status is null then
        return jsonb_build_object(
            'ok', false,
            'error', 'Смена не найдена'
        );
    end if;

    -- Shift already closed or has unexpected status
    if v_existing_status != 'open' then
        if v_existing_status = 'closed' then
            select row_to_json(s)::jsonb
            into v_result
            from public.staff_shifts s
            where s.id = p_shift_id;

            return jsonb_build_object(
                'ok', true,
                'shift', v_result,
                'action', 'already_closed'
            );
        end if;

        return jsonb_build_object(
            'ok', false,
            'error', 'Смена имеет неожиданный статус: ' || v_existing_status
        );
    end if;

    -- Update shift with optimistic check on status
    update public.staff_shifts
    set total_amount       = p_total_amount,
        consumables_amount = p_consumables_amount,
        percent_master     = p_percent_master,
        percent_salon      = p_percent_salon,
        master_share       = p_master_share,
        salon_share        = p_salon_share,
        hours_worked       = p_hours_worked,
        hourly_rate        = p_hourly_rate,
        guaranteed_amount  = p_guaranteed_amount,
        topup_amount       = p_topup_amount,
        status             = 'closed',
        closed_at          = coalesce(p_closed_at, timezone('utc'::text, now()))
    where id = p_shift_id
      and status = 'open';

    if not found then
        return jsonb_build_object(
            'ok', false,
            'error', 'Смена была изменена другим запросом. Попробуйте снова.'
        );
    end if;

    -- Update aggregates using fully initialized v_shift_record
    perform public.update_shift_aggregates(
        v_shift_record.staff_id,
        v_shift_record.biz_id,
        v_shift_record.shift_date,
        p_total_amount,
        p_master_share,
        p_salon_share,
        coalesce(v_shift_record.late_minutes, 0),
        p_guaranteed_amount,
        p_topup_amount
    );

    -- Return updated shift
    select row_to_json(s)::jsonb
    into v_result
    from public.staff_shifts s
    where s.id = p_shift_id;

    return jsonb_build_object(
        'ok', true,
        'shift', v_result,
        'action', 'closed'
    );

exception
    when others then
        return jsonb_build_object(
            'ok', false,
            'error', 'Ошибка при закрытии смены: ' || sqlerrm
        );
end;
$function$
;

-- signature: public.commit_user_lifecycle()
CREATE OR REPLACE FUNCTION public.commit_user_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare c public.user_lifecycle_commands; marker text;
begin
  -- Auth updates app_metadata before banned_until, in the same transaction.
  -- Metadata alone must never complete a command.
  if tg_op='UPDATE' then
    marker:=new.raw_app_meta_data->>'kezek_lifecycle_command';
    if tg_argv[0]='metadata' and marker is not distinct from (old.raw_app_meta_data->>'kezek_lifecycle_command') then return new; end if;
  end if;
  perform pg_advisory_xact_lock(184207,1);
  select * into c from public.user_lifecycle_commands where user_id=old.id for update;
  -- The existing service-only retention command has its own durable, due
  -- self-deletion request. Preserve that path, with blockers rechecked at the
  -- actual Auth DELETE (not just before its earlier anonymization statements).
  if tg_op='DELETE' and (c.user_id is null or c.completed)
    and coalesce(nullif(current_setting('role',true),'none'),session_user) in ('service_role','postgres','supabase_admin') then
    perform 1 from public.account_deletion_requests where user_id=old.id
      and status='pending' and scheduled_for<=now() for update;
    if found then
      if public.finance_is_platform_admin(old.id)
        or exists(select 1 from public.businesses where owner_id=old.id)
        or exists(select 1 from public.staff where user_id=old.id)
        or exists(select 1 from public.user_roles where user_id=old.id)
        or exists(select 1 from public.user_global_roles where user_id=old.id)
        or exists(select 1 from public.branch_admins where user_id=old.id)
        or exists(select 1 from public.bookings where client_id=old.id and status in ('hold','confirmed','paid') and start_at>=now()) then
        raise exception 'USER_LIFECYCLE_DELETION_BLOCKED';
      end if;
      return old;
    end if;
  end if;
  if c.user_id is null or c.completed or (tg_op='DELETE' and c.action<>'delete')
    or (tg_op='UPDATE' and (c.action='delete' or marker is distinct from c.command_id::text)) then
    raise exception 'USER_LIFECYCLE_COMMAND_REQUIRED';
  end if;
  if not exists(select 1 from auth.users where id=c.actor_id and coalesce(banned_until,now())<=now())
    or exists(select 1 from public.user_suspensions where user_id=c.actor_id)
    or not public.finance_is_platform_admin(c.actor_id) then raise exception 'USER_LIFECYCLE_FORBIDDEN'; end if;
  if c.actor_id=old.id or public.finance_is_platform_admin(old.id) then raise exception 'USER_LIFECYCLE_PROTECTED'; end if;
  if tg_op='DELETE' then
    if exists(select 1 from public.businesses where owner_id=old.id) then raise exception 'USER_LIFECYCLE_OWNER'; end if;
    -- FK SET NULL preserves staff, bookings and finance history. No profile or
    -- role is removed unless the Auth DELETE transaction itself succeeds.
    delete from public.branch_admins where user_id=old.id;
    update public.staff set is_active=false where user_id=old.id;
  else
    if tg_argv[0]='metadata' then return new; end if;
    if (c.action='block') is distinct from coalesce(new.banned_until>now(),false) then raise exception 'USER_LIFECYCLE_STATE_MISMATCH'; end if;
    if c.action='block' then
      insert into public.user_suspensions(user_id,reason,created_by) values(old.id,c.reason,c.actor_id)
        on conflict(user_id) do update set reason=excluded.reason,created_by=excluded.created_by,created_at=now();
      -- Auth v2.180 Ban does not revoke sessions. Delete only this user's sessions;
      -- refresh tokens linked to them cascade. This runs inside the ban transaction.
      delete from auth.refresh_tokens where user_id=old.id::text;
      delete from auth.sessions where user_id=old.id;
    else
      delete from public.user_suspensions where user_id=old.id;
    end if;
  end if;
  update public.user_lifecycle_commands set completed=true,completed_at=now() where user_id=old.id;
  if tg_op='DELETE' then return old; end if;
  return new;
end;
$function$
;

-- signature: public.confirm_booking(uuid)
CREATE OR REPLACE FUNCTION public.confirm_booking(p_booking_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
begin
  perform public._assert_booking_transition_access(p_booking_id);
  perform public._confirm_booking_transition(p_booking_id);
end;
$function$
;

-- signature: public.consume_mobile_session_grant(text,text)
CREATE OR REPLACE FUNCTION public.consume_mobile_session_grant(p_code_hash text, p_code_challenge text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target_user uuid;
begin
    -- UPDATE locks the row and rechecks the predicate after a concurrent consumer.
    update public.mobile_session_grants
       set consumed_at = now()
     where code_hash = p_code_hash and code_challenge = p_code_challenge
       and consumed_at is null and expires_at > now()
     returning user_id into target_user;
    return target_user;
end $function$
;

-- signature: public.consume_whatsapp_mobile_otp(uuid,text,text)
CREATE OR REPLACE FUNCTION public.consume_whatsapp_mobile_otp(p_attempt_id uuid, p_otp_hash text, p_code_challenge text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare claimed uuid;
begin
    update public.whatsapp_otp_codes
       set used_at = now(), consumed_at = now(), status = 'consumed'
     where id = p_attempt_id and otp_hash = p_otp_hash and code_challenge = p_code_challenge
       and used_at is null and consumed_at is null and status = 'pending'
       and expires_at > now() and coalesce(failed_attempts, 0) < 5
       and (locked_until is null or locked_until <= now())
     returning id into claimed;
    return claimed is not null;
end $function$
;

-- signature: public.consume_yandex_oauth_state(text,text,uuid)
CREATE OR REPLACE FUNCTION public.consume_yandex_oauth_state(p_state_hash text, p_flow text, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
    with consumed as (
        delete from public.yandex_oauth_states
        where state_hash = p_state_hash
          and flow = p_flow
          and user_id is not distinct from p_user_id
          and expires_at > now()
        returning flow, user_id, return_path
    )
    select jsonb_build_object('flow', flow, 'user_id', user_id, 'return_path', return_path)
    from consumed;
$function$
;

-- signature: public.create_confirmed_booking(uuid,jsonb,text,uuid)
CREATE OR REPLACE FUNCTION public.create_confirmed_booking(p_request_id uuid, p_payload jsonb, p_guest_secret text, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
declare
  v_user_id uuid := p_actor_id;
  v_guest boolean := p_guest_secret is not null;
  v_caller_hash text;
  v_payload_hash text;
  v_payload jsonb;
  v_receipt public.booking_creation_requests%rowtype;
  v_biz_id uuid;
  v_branch_id uuid;
  v_service_id uuid;
  v_staff_id uuid;
  v_start timestamptz;
  v_services jsonb;
  v_booking_id uuid;
  v_response jsonb;
begin
  if p_request_id is null or p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  if v_guest and v_user_id is not null then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  if v_guest then
    if p_guest_secret !~ '^[a-f0-9]{64}$' then
      raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;
    v_caller_hash := encode(sha256(convert_to('guest:' || p_guest_secret, 'UTF8')), 'hex');
  else
    if v_user_id is null then
      raise exception using errcode = '42501', message = 'BOOKING_AUTH_REQUIRED';
    end if;
    v_caller_hash := encode(sha256(convert_to('user:' || v_user_id::text, 'UTF8')), 'hex');
  end if;

  v_biz_id := (p_payload->>'biz_id')::uuid;
  v_branch_id := (p_payload->>'branch_id')::uuid;
  v_service_id := (p_payload->>'service_id')::uuid;
  v_staff_id := (p_payload->>'staff_id')::uuid;
  v_start := (p_payload->>'start_at')::timestamptz;
  v_services := nullif(p_payload->'services', 'null'::jsonb);
  if v_biz_id is null or v_staff_id is null or v_start is null or
     (v_guest and v_branch_id is null) or
     (v_services is not null and (jsonb_typeof(v_services) <> 'array' or jsonb_array_length(v_services) > 20)) then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  if v_service_id is null then v_service_id := (v_services->0->>'service_id')::uuid; end if;
  if v_service_id is null then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  -- Hash the effective command, not JSON property order, timestamp spelling,
  -- ignored extra fields, or caller-supplied identity fields.
  v_payload := jsonb_build_object(
    'biz_id', v_biz_id, 'branch_id', v_branch_id, 'service_id', v_service_id,
    'staff_id', v_staff_id, 'start_at', extract(epoch from v_start), 'services', v_services,
    'client_name', case when v_guest then trim(p_payload->>'client_name') end,
    'client_phone', case when v_guest then trim(p_payload->>'client_phone') end,
    'client_email', case when v_guest then trim(p_payload->>'client_email') end
  );
  v_payload_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');

  insert into public.booking_creation_requests(request_id, caller_hash, payload_hash)
  values(p_request_id, v_caller_hash, v_payload_hash)
  on conflict(request_id) do nothing;
  select * into strict v_receipt from public.booking_creation_requests
    where request_id = p_request_id for update;
  if v_receipt.caller_hash <> v_caller_hash or v_receipt.payload_hash <> v_payload_hash then
    raise exception using errcode = 'P0001', message = 'BOOKING_REQUEST_CONFLICT';
  end if;
  if v_receipt.response is not null then return v_receipt.response; end if;

  if v_branch_id is null then
    select id into v_branch_id from public.branches
      where biz_id = v_biz_id and is_active order by id limit 1;
    if not found then
      raise exception using errcode = 'P0001', message = 'NO_ACTIVE_BRANCH_FOR_BIZ';
    end if;
  end if;
  -- Serialize different request keys for the same staff too. Existing writers
  -- perform their conflict check after this lock, including legacy schedules.
  perform id from public.staff where id = v_staff_id and biz_id = v_biz_id for update;
  if not found then
    raise exception using errcode = '22023', message = 'staff not found or inactive';
  end if;
  if v_guest then
    if coalesce(jsonb_array_length(v_services), 0) > 1 then
      v_booking_id := public.hold_complex_slot_guest(v_biz_id, v_branch_id, v_staff_id, v_start,
        v_services, p_payload->>'client_name', p_payload->>'client_phone', p_payload->>'client_email');
    else
      v_booking_id := public.hold_slot_guest(v_biz_id, v_branch_id, v_service_id, v_staff_id, v_start,
        p_payload->>'client_name', p_payload->>'client_phone', p_payload->>'client_email');
    end if;
  else
    if coalesce(jsonb_array_length(v_services), 0) > 0 then
      v_booking_id := public._hold_complex_slot_for_actor(v_biz_id, v_branch_id, v_staff_id, v_start, v_services, v_user_id);
    else
      v_booking_id := public._hold_slot_for_actor(v_biz_id, v_branch_id, v_service_id, v_staff_id, v_start, v_user_id);
    end if;
  end if;
  perform public._confirm_created_booking(v_booking_id, v_user_id);
  perform public.enqueue_booking_notification(v_booking_id, 'confirm');
  v_response := jsonb_build_object('booking_id', v_booking_id, 'confirmed', true);
  update public.booking_creation_requests set booking_id = v_booking_id, response = v_response
    where request_id = p_request_id;
  return v_response;
end;
$function$
;

-- signature: public.create_confirmed_booking(uuid,jsonb,text)
CREATE OR REPLACE FUNCTION public.create_confirmed_booking(p_request_id uuid, p_payload jsonb, p_guest_secret text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_guest boolean := p_guest_secret is not null;
  v_caller_hash text;
  v_payload_hash text;
  v_payload jsonb;
  v_receipt public.booking_creation_requests%rowtype;
  v_biz_id uuid;
  v_branch_id uuid;
  v_service_id uuid;
  v_staff_id uuid;
  v_start timestamptz;
  v_services jsonb;
  v_booking_id uuid;
  v_response jsonb;
begin
  if p_request_id is null or p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  if v_guest then
    if p_guest_secret !~ '^[a-f0-9]{64}$' then
      raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;
    v_caller_hash := encode(sha256(convert_to('guest:' || p_guest_secret, 'UTF8')), 'hex');
  else
    if v_user_id is null then
      raise exception using errcode = '42501', message = 'BOOKING_AUTH_REQUIRED';
    end if;
    v_caller_hash := encode(sha256(convert_to('user:' || v_user_id::text, 'UTF8')), 'hex');
  end if;

  v_biz_id := (p_payload->>'biz_id')::uuid;
  v_branch_id := (p_payload->>'branch_id')::uuid;
  v_service_id := (p_payload->>'service_id')::uuid;
  v_staff_id := (p_payload->>'staff_id')::uuid;
  v_start := (p_payload->>'start_at')::timestamptz;
  v_services := nullif(p_payload->'services', 'null'::jsonb);
  if v_biz_id is null or v_staff_id is null or v_start is null or
     (v_guest and v_branch_id is null) or
     (v_services is not null and (jsonb_typeof(v_services) <> 'array' or jsonb_array_length(v_services) > 20)) then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  if v_service_id is null then v_service_id := (v_services->0->>'service_id')::uuid; end if;
  if v_service_id is null then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
  end if;
  -- Hash the effective command, not JSON property order, timestamp spelling,
  -- ignored extra fields, or caller-supplied identity fields.
  v_payload := jsonb_build_object(
    'biz_id', v_biz_id, 'branch_id', v_branch_id, 'service_id', v_service_id,
    'staff_id', v_staff_id, 'start_at', extract(epoch from v_start), 'services', v_services,
    'client_name', case when v_guest then trim(p_payload->>'client_name') end,
    'client_phone', case when v_guest then trim(p_payload->>'client_phone') end,
    'client_email', case when v_guest then trim(p_payload->>'client_email') end
  );
  v_payload_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');

  insert into public.booking_creation_requests(request_id, caller_hash, payload_hash)
  values(p_request_id, v_caller_hash, v_payload_hash)
  on conflict(request_id) do nothing;
  select * into strict v_receipt from public.booking_creation_requests
    where request_id = p_request_id for update;
  if v_receipt.caller_hash <> v_caller_hash or v_receipt.payload_hash <> v_payload_hash then
    raise exception using errcode = 'P0001', message = 'BOOKING_REQUEST_CONFLICT';
  end if;
  if v_receipt.response is not null then return v_receipt.response; end if;

  if v_branch_id is null then
    select id into v_branch_id from public.branches
      where biz_id = v_biz_id and is_active order by id limit 1;
    if not found then
      raise exception using errcode = 'P0001', message = 'NO_ACTIVE_BRANCH_FOR_BIZ';
    end if;
  end if;
  -- Serialize different request keys for the same staff too. Existing writers
  -- perform their conflict check after this lock, including legacy schedules.
  perform id from public.staff where id = v_staff_id and biz_id = v_biz_id for update;
  if not found then
    raise exception using errcode = '22023', message = 'staff not found or inactive';
  end if;
  if v_guest then
    if coalesce(jsonb_array_length(v_services), 0) > 1 then
      v_booking_id := public.hold_complex_slot_guest(v_biz_id, v_branch_id, v_staff_id, v_start,
        v_services, p_payload->>'client_name', p_payload->>'client_phone', p_payload->>'client_email');
    else
      v_booking_id := public.hold_slot_guest(v_biz_id, v_branch_id, v_service_id, v_staff_id, v_start,
        p_payload->>'client_name', p_payload->>'client_phone', p_payload->>'client_email');
    end if;
  else
    if coalesce(jsonb_array_length(v_services), 0) > 0 then
      v_booking_id := public.hold_complex_slot(v_biz_id, v_branch_id, v_staff_id, v_start, v_services);
    else
      v_booking_id := public.hold_slot(v_biz_id, v_branch_id, v_service_id, v_staff_id, v_start);
    end if;
  end if;
  perform public.confirm_booking(v_booking_id);
  perform public.enqueue_booking_notification(v_booking_id, 'confirm');
  v_response := jsonb_build_object('booking_id', v_booking_id, 'confirmed', true);
  update public.booking_creation_requests set booking_id = v_booking_id, response = v_response
    where request_id = p_request_id;
  return v_response;
end;
$function$
;

-- signature: public.create_internal_booking_request(uuid,jsonb,uuid)
CREATE OR REPLACE FUNCTION public.create_internal_booking_request(p_request_id uuid, p_payload jsonb, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
declare
  v_biz uuid; v_branch uuid; v_staff uuid; v_service uuid; v_client uuid; v_start timestamptz;
  v_mode text; v_minutes integer; v_services jsonb; v_payload jsonb;
  v_caller_hash text; v_payload_hash text; v_receipt public.booking_creation_requests;
  v_booking uuid; v_response jsonb;
begin
  if p_actor_id is null then raise exception using errcode='42501',message='BOOKING_AUTH_REQUIRED'; end if;
  if p_request_id is null or p_payload is null or jsonb_typeof(p_payload)<>'object' or octet_length(p_payload::text)>32768 then
    raise exception using errcode='22023',message='INVALID_BOOKING_REQUEST';
  end if;
  v_biz:=(p_payload->>'biz_id')::uuid;v_branch:=(p_payload->>'branch_id')::uuid;v_staff:=(p_payload->>'staff_id')::uuid;
  v_client:=(p_payload->>'client_id')::uuid;v_start:=(p_payload->>'start_at')::timestamptz;v_mode:=p_payload->>'mode';
  if v_biz is null or v_branch is null or v_staff is null or v_start is null or not isfinite(v_start)
    or v_mode is null or v_mode not in ('simple','complex') then
    raise exception using errcode='22023',message='INVALID_BOOKING_REQUEST';
  end if;
  if not public._internal_booking_actor_allowed(p_actor_id,v_biz,v_branch,v_staff) then
    raise exception using errcode='42501',message='BOOKING_FORBIDDEN';
  end if;
  if length(coalesce(p_payload->>'client_name',''))>100 or length(coalesce(p_payload->>'client_phone',''))>32
    or length(coalesce(p_payload->>'client_email',''))>254 then raise exception 'INVALID_BOOKING_REQUEST'; end if;
  if v_mode='simple' then
    v_service:=(p_payload->>'service_id')::uuid;v_minutes:=(p_payload->>'duration_min')::integer;
    if v_service is null or v_minutes is null or v_minutes not between 1 and 1440 then raise exception 'INVALID_BOOKING_REQUEST'; end if;
  else
    v_services:=p_payload->'services';
    if v_services is null or jsonb_typeof(v_services)<>'array' or jsonb_array_length(v_services) not between 1 and 20 then raise exception 'INVALID_BOOKING_REQUEST'; end if;
    select jsonb_agg(jsonb_build_object('service_id',(s.value->>'service_id')::uuid,'duration_min',(s.value->>'duration_min')::integer,
      'order_index',coalesce((s.value->>'order_index')::integer,s.ordinality::integer-1)) order by s.ordinality)
      into v_services from jsonb_array_elements(v_services) with ordinality s;
  end if;
  v_payload:=jsonb_build_object('kind','internal','mode',v_mode,'biz_id',v_biz,'branch_id',v_branch,'staff_id',v_staff,
    'start_at',extract(epoch from v_start),'service_id',v_service,'duration_min',v_minutes,'services',v_services,'client_id',v_client,
    'client_name',nullif(trim(p_payload->>'client_name'),''),'client_phone',nullif(trim(p_payload->>'client_phone'),''),'client_email',nullif(trim(p_payload->>'client_email'),''));
  v_caller_hash:=encode(sha256(convert_to('internal:'||p_actor_id::text,'UTF8')),'hex');
  v_payload_hash:=encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');
  insert into public.booking_creation_requests(request_id,caller_hash,payload_hash) values(p_request_id,v_caller_hash,v_payload_hash)
    on conflict(request_id) do nothing;
  select * into strict v_receipt from public.booking_creation_requests where request_id=p_request_id for update;
  if v_receipt.caller_hash<>v_caller_hash or v_receipt.payload_hash<>v_payload_hash then raise exception 'BOOKING_REQUEST_CONFLICT'; end if;
  if v_receipt.response is not null then return v_receipt.response; end if;
  -- The checked legacy implementation owns entity/schedule/overlap validation
  -- and staff locking. Only its owner may call it after this migration.
  if v_mode='simple' then
    v_booking:=public.create_internal_booking(v_biz,v_branch,v_service,v_staff,v_start,v_minutes,v_client,
      v_payload->>'client_name',v_payload->>'client_phone');
  else
    v_booking:=public.create_internal_complex_booking(v_biz,v_branch,v_staff,v_start,v_services,v_client,
      v_payload->>'client_name',v_payload->>'client_phone',v_payload->>'client_email');
  end if;
  v_response:=jsonb_build_object('booking_id',v_booking,'confirmed',true);
  update public.booking_creation_requests set booking_id=v_booking,response=v_response where request_id=p_request_id;
  return v_response;
end;
$function$
;

-- signature: public.create_internal_booking(uuid,uuid,uuid,uuid,timestamp with time zone,integer,uuid,text,text)
CREATE OR REPLACE FUNCTION public.create_internal_booking(p_biz_id uuid, p_branch_id uuid, p_service_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_minutes integer, p_client_id uuid DEFAULT NULL::uuid, p_client_name text DEFAULT NULL::text, p_client_phone text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
declare v_id uuid; v_end timestamptz;
begin
  perform public._assert_internal_booking_access(p_biz_id,p_branch_id,p_staff_id);
  if p_start is null or not isfinite(p_start) or p_minutes is null or p_minutes<1 or p_minutes>1440 then
    raise exception using errcode='22023',message='INVALID_BOOKING_REQUEST';
  end if;
  if not exists(select 1 from public.services where id=p_service_id and biz_id=p_biz_id and active) then
    raise exception 'service not found or inactive';
  end if;
  v_end:=p_start+make_interval(mins=>p_minutes);
  if exists(select 1 from public.staff_schedule_versions where staff_id=p_staff_id)
    and not public.schedule_contains_booking(p_staff_id,p_branch_id,p_start,v_end) then
    raise exception 'booking is outside effective schedule';
  end if;
  if exists(select 1 from public.bookings where staff_id=p_staff_id
    and (status in ('confirmed','paid') or (status='hold' and expires_at>now()))
    and tstzrange(start_at,end_at,'[)') && tstzrange(p_start,v_end,'[)')) then
    raise exception 'time slot is already booked';
  end if;
  insert into public.bookings(biz_id,branch_id,service_id,staff_id,start_at,end_at,status,client_id,client_name,client_phone)
    values(p_biz_id,p_branch_id,p_service_id,p_staff_id,p_start,v_end,'confirmed',p_client_id,
      case when p_client_id is null then nullif(btrim(p_client_name),'') end,
      case when p_client_id is null then nullif(btrim(p_client_phone),'') end) returning id into v_id;
  return v_id;
end;
$function$
;

-- signature: public.create_internal_complex_booking(uuid,uuid,uuid,timestamp with time zone,jsonb,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.create_internal_complex_booking(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_services jsonb, p_client_id uuid DEFAULT NULL::uuid, p_client_name text DEFAULT NULL::text, p_client_phone text DEFAULT NULL::text, p_client_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET lock_timeout TO '5s'
AS $function$
declare
    v_booking_id uuid;
    v_total_duration_min integer := 0;
    v_item jsonb;
    v_service_id uuid;
    v_duration_min integer;
    v_order_index integer;
    v_index integer := 0;
    v_end timestamptz;
begin
    perform public._assert_internal_booking_access(p_biz_id,p_branch_id,p_staff_id);
    if p_start is null or not isfinite(p_start) then raise exception 'INVALID_BOOKING_REQUEST'; end if;

    -- Валидация и суммирование услуг
    if p_services is null or jsonb_typeof(p_services) <> 'array' or jsonb_array_length(p_services) = 0 or jsonb_array_length(p_services)>20 then
        raise exception 'services array must be a non-empty JSON array';
    end if;

    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_item := p_services->v_index;
        v_service_id := (v_item->>'service_id')::uuid;
        v_duration_min := (v_item->>'duration_min')::integer;
        v_order_index := coalesce((v_item->>'order_index')::integer, v_index);

        if v_service_id is null then
            raise exception 'service_id is required in services[%]', v_index;
        end if;
        if v_duration_min is null or v_duration_min <= 0 or v_duration_min>1440 then
            raise exception 'duration_min must be positive in services[%]', v_index;
        end if;

        -- Проверяем, что услуга существует и активна в этом бизнесе
        if not exists (
            select 1
            from public.services s
            where s.id = v_service_id
              and s.biz_id = p_biz_id
              and s.active = true
        ) then
            raise exception 'service not found or inactive: %', v_service_id;
        end if;

        v_total_duration_min := v_total_duration_min + v_duration_min;
    end loop;

    if v_total_duration_min <= 0 or v_total_duration_min>1440 then
        raise exception 'total duration must be positive';
    end if;

    v_end := p_start + (v_total_duration_min || ' minutes')::interval;

    if exists(select 1 from public.staff_schedule_versions where staff_id=p_staff_id)
      and not public.schedule_contains_booking(p_staff_id,p_branch_id,p_start,v_end) then
      raise exception 'booking is outside effective schedule';
    end if;

    -- Проверка пересечений с существующими бронированиями мастера
    if exists (
        select 1
        from public.bookings b
        where b.staff_id = p_staff_id
          and (b.status in ('confirmed','paid') or (b.status = 'hold' and b.expires_at > now()))
          and tstzrange(b.start_at, b.end_at, '[)') && tstzrange(p_start, v_end, '[)')
    ) then
        raise exception 'time slot is already booked';
    end if;

    -- Создаём бронирование (service_id = первая услуга комплекса)
    insert into public.bookings (
        biz_id,
        branch_id,
        service_id,
        staff_id,
        client_id,
        client_name,
        client_phone,
        client_email,
        start_at,
        end_at,
        status,
        expires_at
    )
    values (
        p_biz_id,
        p_branch_id,
        (p_services->0->>'service_id')::uuid,
        p_staff_id,
        p_client_id,
        p_client_name,
        p_client_phone,
        p_client_email,
        p_start,
        v_end,
        'confirmed'::booking_status,
        null
    )
    returning id into v_booking_id;

    -- Заполняем booking_services
    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_item := p_services->v_index;
        v_service_id := (v_item->>'service_id')::uuid;
        v_duration_min := (v_item->>'duration_min')::integer;
        v_order_index := coalesce((v_item->>'order_index')::integer, v_index);

        insert into public.booking_services (
            booking_id,
            service_id,
            duration_min,
            order_index
        )
        values (
            v_booking_id,
            v_service_id,
            v_duration_min,
            v_order_index
        );
    end loop;

    return v_booking_id;
end;
$function$
;

-- signature: public.create_mobile_session_grant(text,text,uuid)
CREATE OR REPLACE FUNCTION public.create_mobile_session_grant(p_code_hash text, p_code_challenge text, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    -- Bound the work per issuance; expired grants never authorize redemption.
    delete from public.mobile_session_grants where code_hash in (
        select code_hash from public.mobile_session_grants
        where expires_at <= now() order by expires_at limit 500
    );
    insert into public.mobile_session_grants(code_hash, code_challenge, user_id)
    values (p_code_hash, p_code_challenge, p_user_id);
end $function$
;

-- signature: public.create_yandex_oauth_state(text,text,uuid,text)
CREATE OR REPLACE FUNCTION public.create_yandex_oauth_state(p_state_hash text, p_flow text, p_user_id uuid, p_return_path text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
    -- Bounded maintenance: expired records never authorize a callback.
    delete from public.yandex_oauth_states where state_hash in (
        select state_hash from public.yandex_oauth_states
        where expires_at <= now() order by expires_at limit 500
    );
    insert into public.yandex_oauth_states (state_hash, flow, user_id, return_path)
    values (p_state_hash, p_flow, p_user_id, p_return_path);
end;
$function$
;

-- signature: public.dashboard_bookings_page(uuid,text,uuid,uuid,timestamp with time zone,timestamp with time zone,text,integer,integer)
CREATE OR REPLACE FUNCTION public.dashboard_bookings_page(p_biz_id uuid, p_status text DEFAULT 'notCancelled'::text, p_branch_id uuid DEFAULT NULL::uuid, p_staff_id uuid DEFAULT NULL::uuid, p_start_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_start_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_search text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_actor uuid := auth.uid();
    v_statuses public.booking_status[];
    v_exclude_cancelled boolean := false;
    v_raw text := left(nullif(btrim(coalesce(p_search, '')), ''), 100);
    v_pattern text;
    v_hex text;
    v_id_prefix text;
    v_digits text;
    v_limit integer := least(greatest(coalesce(p_limit, 30), 1), 100);
    v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 100000);
    v_result jsonb;
begin
    if p_biz_id is null
       or not (coalesce(auth.role(), '') = 'service_role'
               or coalesce(public.finance_can_manage_business(v_actor, p_biz_id), false)) then
        raise exception 'DASHBOARD_BOOKINGS_FORBIDDEN' using errcode = '42501';
    end if;

    case coalesce(p_status, 'notCancelled')
        when 'notCancelled' then v_exclude_cancelled := true;
        when 'any' then null;
        when 'holdConfirmed' then v_statuses := array['hold', 'confirmed']::public.booking_status[];
        when 'hold', 'confirmed', 'paid', 'cancelled', 'no_show' then v_statuses := array[p_status]::public.booking_status[];
        else raise exception 'DASHBOARD_BOOKINGS_BAD_STATUS' using errcode = '22023';
    end case;

    if v_raw is not null then
        -- a literal substring: the backslash is the LIKE escape character
        v_pattern := '%' || replace(replace(replace(v_raw, chr(92), chr(92) || chr(92)), '%', chr(92) || '%'), '_', chr(92) || '_') || '%';
        -- the list shows '#' and the first 8 characters of the id; dashes are ignored
        v_hex := replace(lower(ltrim(v_raw, '#')), '-', '');
        if v_hex ~ '^[0-9a-f]{4,32}$' then
            v_id_prefix := v_hex;
        end if;
        -- phones are stored as +996555123456 and as free text from the desk (0555 12-34-56)
        if v_raw ~ '^[0-9 ()+.-]+$' and length(regexp_replace(v_raw, '[^0-9]', '', 'g')) >= 3 then
            v_digits := regexp_replace(v_raw, '[^0-9]', '', 'g');
        end if;
    end if;

    with matched as (
        select b.id, b.start_at
          from public.bookings b
         where b.biz_id = p_biz_id
           and (v_statuses is null or b.status = any (v_statuses))
           and (not v_exclude_cancelled or b.status <> 'cancelled')
           and (p_branch_id is null or b.branch_id = p_branch_id)
           and (p_staff_id is null or b.staff_id = p_staff_id)
           and (p_start_from is null or b.start_at >= p_start_from)
           and (p_start_before is null or b.start_at < p_start_before)
           and (v_raw is null
                or (v_id_prefix is not null and replace(b.id::text, '-', '') like v_id_prefix || '%')
                or b.client_name ilike v_pattern
                or b.client_phone ilike v_pattern
                or (v_digits is not null
                    and regexp_replace(coalesce(b.client_phone, ''), '[^0-9]', '', 'g') like '%' || v_digits || '%')
                or (b.client_id is not null and nullif(btrim(b.client_name), '') is null
                    and exists (select 1 from public.profiles pr
                                 where pr.id = b.client_id and pr.full_name ilike v_pattern))
                or exists (select 1 from public.staff s
                            where s.id = b.staff_id and s.biz_id = p_biz_id and s.full_name ilike v_pattern)
                or exists (select 1 from public.services sv
                            where sv.id = b.service_id and sv.biz_id = p_biz_id
                              and (sv.name_ru ilike v_pattern or sv.name_ky ilike v_pattern or sv.name_en ilike v_pattern))
                or exists (select 1 from public.booking_services bs
                             join public.services sv on sv.id = bs.service_id
                            where bs.booking_id = b.id and sv.biz_id = p_biz_id
                              and (sv.name_ru ilike v_pattern or sv.name_ky ilike v_pattern or sv.name_en ilike v_pattern)))
    ), page as (
        select m.id, m.start_at
          from matched m
         order by m.start_at desc, m.id desc
         limit v_limit offset v_offset
    )
    select jsonb_build_object(
        'total', (select count(*) from matched),
        'rows', coalesce((
            select jsonb_agg(jsonb_build_object(
                       'id', b.id,
                       'status', b.status,
                       'start_at', b.start_at,
                       'end_at', b.end_at,
                       'branch_id', b.branch_id,
                       'staff_id', b.staff_id,
                       'client_id', b.client_id,
                       'client_name', coalesce(nullif(btrim(b.client_name), ''), nullif(btrim(pr.full_name), '')),
                       'client_phone', b.client_phone,
                       'service', case when sv.id is null then null
                                       else jsonb_build_object('name_ru', sv.name_ru, 'name_ky', sv.name_ky, 'name_en', sv.name_en) end,
                       'staff_name', st.full_name,
                       'booking_services', coalesce((
                           select jsonb_agg(jsonb_build_object(
                                      'duration_min', bs.duration_min,
                                      'service', case when s2.id is null then null
                                                      else jsonb_build_object('name_ru', s2.name_ru, 'name_ky', s2.name_ky, 'name_en', s2.name_en) end)
                                  order by bs.order_index nulls last, bs.id)
                             from public.booking_services bs
                             left join public.services s2 on s2.id = bs.service_id
                            where bs.booking_id = b.id), '[]'::jsonb))
                   order by p.start_at desc, p.id desc)
              from page p
              join public.bookings b on b.id = p.id
              left join public.services sv on sv.id = b.service_id
              left join public.staff st on st.id = b.staff_id
              left join public.profiles pr on pr.id = b.client_id and nullif(btrim(b.client_name), '') is null
        ), '[]'::jsonb))
      into v_result;

    return v_result;
end;
$function$
;

-- signature: public.delete_branch_without_history(uuid,uuid)
CREATE OR REPLACE FUNCTION public.delete_branch_without_history(p_biz_id uuid, p_branch_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_staff_id uuid;
begin
    perform 1 from public.branches where id = p_branch_id and biz_id = p_biz_id for update;
    if not found then
        raise exception using errcode = 'P0002', message = 'BRANCH_NOT_FOUND';
    end if;

    -- Still used: active masters or services, or a visit package plan sold for its services.
    if exists (select 1 from public.staff where branch_id = p_branch_id and is_active)
       or exists (select 1 from public.services where branch_id = p_branch_id and active)
       or exists (select 1 from public.visit_package_plans p join public.services s on s.id = p.service_id
                   where s.branch_id = p_branch_id) then
        raise exception using errcode = 'P0001', message = 'BRANCH_IN_USE';
    end if;

    -- History of the branch, or of an inactive master homed there (ENG-69's definition).
    if exists (select 1 from public.bookings where branch_id = p_branch_id)
       or exists (select 1 from public.bookings b join public.services s on s.id = b.service_id where s.branch_id = p_branch_id)
       or exists (select 1 from public.booking_services bs join public.services s on s.id = bs.service_id where s.branch_id = p_branch_id)
       or exists (select 1 from public.staff_shifts where branch_id = p_branch_id)
       or exists (select 1 from public.staff_schedule_versions where branch_id = p_branch_id)
       or exists (select 1 from public.staff_home_branch_changes where from_branch_id = p_branch_id or to_branch_id = p_branch_id)
       or exists (select 1 from public.client_promotion_usage where branch_id = p_branch_id)
       or exists (select 1 from public.client_referrals where branch_id = p_branch_id)
       or exists (select 1 from public.staff st
                   where st.branch_id = p_branch_id
                     and (exists (select 1 from public.bookings where staff_id = st.id)
                          or exists (select 1 from public.staff_shifts where staff_id = st.id)
                          or exists (select 1 from public.staff_schedule_versions where staff_id = st.id)
                          or exists (select 1 from public.staff_home_branch_changes where staff_id = st.id)
                          or exists (select 1 from public.staff_finance_operation_logs where staff_id = st.id))) then
        raise exception using errcode = 'P0001', message = 'BRANCH_HAS_HISTORY';
    end if;

    for v_staff_id in select id from public.staff where branch_id = p_branch_id loop
        perform public.delete_staff_without_history(p_biz_id, v_staff_id);
    end loop;
    delete from public.staff_schedule_rules where branch_id = p_branch_id;
    delete from public.staff_branch_assignments where branch_id = p_branch_id;
    delete from public.services where branch_id = p_branch_id;
    -- Working hours, branch admins, unused promotions and metrics cascade with the branch.
    delete from public.branches where id = p_branch_id and biz_id = p_biz_id;
end;
$function$
;

-- signature: public.delete_business_without_history(uuid)
CREATE OR REPLACE FUNCTION public.delete_business_without_history(p_biz_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    perform 1 from public.businesses where id = p_biz_id for update;
    if not found then
        raise exception using errcode = 'P0002', message = 'BUSINESS_NOT_FOUND';
    end if;

    if exists (select 1 from public.bookings where biz_id = p_biz_id)
       or exists (select 1 from public.staff_shifts where biz_id = p_biz_id)
       or exists (select 1 from public.staff_finance_operation_logs where biz_id = p_biz_id)
       or exists (select 1 from public.staff_schedule_versions where biz_id = p_biz_id)
       or exists (select 1 from public.staff_home_branch_changes where biz_id = p_biz_id)
       or exists (select 1 from public.client_promotion_usage where biz_id = p_biz_id)
       or exists (select 1 from public.client_referrals where biz_id = p_biz_id)
       or exists (select 1 from public.client_visit_packages cvp join public.visit_package_plans p on p.id = cvp.plan_id
                   where p.biz_id = p_biz_id) then
        raise exception using errcode = 'P0001', message = 'BUSINESS_HAS_HISTORY';
    end if;

    -- Rows without a cascading path (no foreign key, or RESTRICT to a branch) go first.
    delete from public.staff_branch_assignments where biz_id = p_biz_id;
    delete from public.staff_schedule_rules where biz_id = p_biz_id;
    delete from public.user_roles where biz_id = p_biz_id;
    update public.businesses set owner_id = null where id = p_biz_id;
    delete from public.businesses where id = p_biz_id;
end;
$function$
;

-- signature: public.delete_staff_without_history(uuid,uuid)
CREATE OR REPLACE FUNCTION public.delete_staff_without_history(p_biz_id uuid, p_staff_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_user_id uuid;
begin
    select s.user_id into v_user_id
      from public.staff s
     where s.id = p_staff_id and s.biz_id = p_biz_id
     for update;
    if not found then
        raise exception using errcode = 'P0002', message = 'STAFF_NOT_FOUND';
    end if;

    if exists (select 1 from public.bookings where staff_id = p_staff_id)
       or exists (select 1 from public.staff_shifts where staff_id = p_staff_id)
       or exists (select 1 from public.staff_schedule_versions where staff_id = p_staff_id)
       or exists (select 1 from public.staff_home_branch_changes where staff_id = p_staff_id)
       or exists (select 1 from public.staff_finance_operation_logs where staff_id = p_staff_id) then
        raise exception using errcode = 'P0001', message = 'STAFF_HAS_HISTORY';
    end if;

    -- staff_branch_assignments has no foreign key to staff; the other per-master rows
    -- (working hours, service links, schedule rules, time off, day metrics, finance settings
    -- audit) cascade with the staff row.
    delete from public.staff_branch_assignments where staff_id = p_staff_id and biz_id = p_biz_id;

    if v_user_id is not null then
        delete from public.user_roles ur
         using public.roles r
         where r.id = ur.role_id and r.key = 'staff' and ur.user_id = v_user_id and ur.biz_id = p_biz_id;
        begin
            insert into public.user_roles(user_id, biz_id, role_id)
            select v_user_id, p_biz_id, r.id from public.roles r where r.key = 'client'
            on conflict do nothing;
        exception when raise_exception then
            -- A suspended account, or one with a pending lifecycle command, takes no new roles;
            -- the staff card is removed all the same.
            if sqlerrm not in ('USER_SUSPENDED', 'USER_LIFECYCLE_ASSIGNMENT_BLOCKED') then
                raise;
            end if;
        end;
    end if;

    delete from public.staff where id = p_staff_id and biz_id = p_biz_id;
end;
$function$
;

-- signature: public.enforce_business_branch_limit()
CREATE OR REPLACE FUNCTION public.enforce_business_branch_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    allowed_count integer;
    current_count integer;
begin
    select branch_limit
    into allowed_count
    from public.businesses
    where id = new.biz_id
    for update;

    if allowed_count is null then
        raise exception using errcode = '23503', message = 'BUSINESS_NOT_FOUND';
    end if;

    select count(*)::integer
    into current_count
    from public.branches
    where biz_id = new.biz_id;

    if current_count >= allowed_count then
        raise exception using
            errcode = 'P0001',
            message = format('BRANCH_LIMIT_REACHED:%s:%s', current_count, allowed_count);
    end if;

    return new;
end;
$function$
;

-- signature: public.enforce_business_registration_application_policy()
CREATE OR REPLACE FUNCTION public.enforce_business_registration_application_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_identity text;
    v_active_count integer;
    v_month_count integer;
    v_prior_count integer;
    v_rejected_count integer;
begin
    v_identity := coalesce(new.applicant_user_id::text, new.phone);
    perform pg_advisory_xact_lock(hashtextextended('business-registration:' || v_identity, 0));

    if exists (
        select 1
        from public.application_submission_blocks b
        where b.application_kind = 'business_registration'
          and b.blocked_until > now()
          and (
              (new.applicant_user_id is not null and b.subject_user_id = new.applicant_user_id)
              or (b.subject_phone is not null and b.subject_phone = new.phone)
          )
    ) then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:blocked';
    end if;

    if exists (
        select 1
        from public.business_registration_applications a
        where a.status in ('new', 'contacted')
          and lower(btrim(a.business_name)) = lower(btrim(new.business_name))
          and (
              (new.applicant_user_id is not null and a.applicant_user_id = new.applicant_user_id)
              or a.phone = new.phone
          )
    ) then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:pending_duplicate';
    end if;

    select count(*) into v_active_count
    from public.business_registration_applications a
    where a.status in ('new', 'contacted')
      and (
          (new.applicant_user_id is not null and a.applicant_user_id = new.applicant_user_id)
          or a.phone = new.phone
      );
    if v_active_count >= 2 then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:active_limit';
    end if;

    select count(*) into v_month_count
    from public.business_registration_applications a
    where a.created_at >= now() - interval '30 days'
      and (
          (new.applicant_user_id is not null and a.applicant_user_id = new.applicant_user_id)
          or a.phone = new.phone
      );
    if v_month_count >= 3 then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:monthly_limit';
    end if;

    if exists (
        select 1
        from public.business_registration_applications a
        where a.status = 'rejected'
          and coalesce(a.reviewed_at, a.updated_at) > now() - interval '24 hours'
          and (
              (new.applicant_user_id is not null and a.applicant_user_id = new.applicant_user_id)
              or a.phone = new.phone
          )
    ) then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:cooldown_24h';
    end if;

    select count(*), count(*) filter (where a.status = 'rejected')
      into v_prior_count, v_rejected_count
    from public.business_registration_applications a
    where (new.applicant_user_id is not null and a.applicant_user_id = new.applicant_user_id)
       or a.phone = new.phone;

    new.prior_submission_count := v_prior_count;
    new.risk_flags := array_remove(array[
        case when new.applicant_user_id is null then 'guest_submission' end,
        case when v_prior_count > 0 then 'repeat_applicant' end,
        case when v_rejected_count >= 2 then 'multiple_rejections' end
    ], null);
    return new;
end;
$function$
;

-- signature: public.enforce_business_role_application_policy()
CREATE OR REPLACE FUNCTION public.enforce_business_role_application_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_pending_limit integer;
    v_cooldown interval;
    v_prior_count integer;
    v_rejected_count integer;
begin
    perform pg_advisory_xact_lock(hashtextextended('business-role:' || new.applicant_user_id::text || ':' || new.requested_role, 0));

    if new.requested_role not in ('owner', 'staff') then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:unsupported_role';
    end if;

    if new.policy_version >= 1
       and new.requested_role = 'owner'
       and coalesce(length(btrim(new.message)), 0) < 20
       and new.evidence_links = '{}'::jsonb then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:owner_evidence_required';
    end if;

    if exists (
        select 1
        from public.application_submission_blocks b
        where b.application_kind = new.requested_role
          and b.subject_user_id = new.applicant_user_id
          and b.blocked_until > now()
          and (b.biz_id is null or b.biz_id = new.biz_id)
    ) then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:blocked';
    end if;

    if new.requested_role = 'staff' and exists (
        select 1
        from public.user_roles ur
        join public.roles r on r.id = ur.role_id
        where ur.user_id = new.applicant_user_id
          and ur.biz_id = new.biz_id
          and r.key = 'owner'
    ) then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:owner_cannot_be_staff';
    end if;

    v_pending_limit := case when new.requested_role = 'owner' then 3 else 5 end;
    if (select count(*) from public.business_role_applications a
        where a.applicant_user_id = new.applicant_user_id
          and a.requested_role = new.requested_role
          and a.status = 'pending') >= v_pending_limit then
        raise exception using errcode = 'P0001', message = 'APPLICATION_POLICY:active_limit';
    end if;

    v_cooldown := case when new.requested_role = 'owner' then interval '7 days' else interval '3 days' end;
    if exists (
        select 1
        from public.business_role_applications a
        where a.applicant_user_id = new.applicant_user_id
          and a.biz_id = new.biz_id
          and a.requested_role = new.requested_role
          and a.status = 'rejected'
          and coalesce(a.reviewed_at, a.updated_at) > now() - v_cooldown
    ) then
        raise exception using errcode = 'P0001', message = case
            when new.requested_role = 'owner' then 'APPLICATION_POLICY:cooldown_7d'
            else 'APPLICATION_POLICY:cooldown_3d'
        end;
    end if;

    select count(*), count(*) filter (where a.status = 'rejected')
      into v_prior_count, v_rejected_count
    from public.business_role_applications a
    where a.applicant_user_id = new.applicant_user_id
      and a.requested_role = new.requested_role;

    new.prior_submission_count := v_prior_count;
    new.risk_flags := array_remove(array[
        case when v_prior_count > 0 then 'repeat_applicant' end,
        case when v_rejected_count > 0 then 'prior_rejection' end,
        case when v_prior_count >= 3 then 'high_submission_volume' end
    ], null);
    return new;
end;
$function$
;

-- signature: public.enqueue_booking_notification(uuid,text)
CREATE OR REPLACE FUNCTION public.enqueue_booking_notification(p_booking_id uuid, p_type text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_status text; v_revision bigint; v_id uuid;
begin
    select status::text,notification_revision into v_status,v_revision from public.bookings where id=p_booking_id;
    if not found then raise exception 'NOTIFICATION_BOOKING_NOT_FOUND' using errcode='P0002'; end if;
    if not ((p_type='hold' and v_status in ('hold','pending_hold')) or (p_type='confirm' and v_status='confirmed')
        or (p_type='cancel' and v_status='cancelled')) then
        raise exception 'NOTIFICATION_STATE_MISMATCH' using errcode='22023';
    end if;
    insert into public.booking_notification_outbox(booking_id,booking_revision,event_type)
        values(p_booking_id,v_revision,p_type) on conflict (booking_id,booking_revision,event_type) do nothing returning id into v_id;
    if v_id is null then
        select id into v_id from public.booking_notification_outbox
            where booking_id=p_booking_id and booking_revision=v_revision and event_type=p_type;
    end if;
    return v_id;
end;
$function$
;

-- signature: public.fail_booking_notification_delivery(uuid,uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.fail_booking_notification_delivery(p_event_id uuid, p_lease_token uuid, p_delivery_key text, p_outcome text, p_error_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox;
begin
    select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
    if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp() then
        raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
    end if;
    if p_outcome is null or p_outcome not in ('retry','failed','ambiguous') then raise exception 'INVALID_DELIVERY_OUTCOME' using errcode='22023'; end if;
    update public.booking_notification_deliveries set status=case when p_outcome='retry' then 'pending' else p_outcome end,
        last_error_code=left(p_error_code,120)
        where event_id=p_event_id and delivery_key=p_delivery_key and status='sending';
    if not found then raise exception 'OUTBOX_DELIVERY_NOT_SENDING' using errcode='P0002'; end if;
end;
$function$
;

-- signature: public.fail_whatsapp_inbox(uuid,uuid,text,text,integer)
CREATE OR REPLACE FUNCTION public.fail_whatsapp_inbox(p_id uuid, p_token uuid, p_outcome text, p_code text, p_retry_after integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare item public.whatsapp_inbox; terminal boolean;
begin
  item:=public._locked_whatsapp_inbox(p_id,p_token);
  if p_outcome is null or p_outcome not in ('retry','failed','ambiguous') or p_code is null or p_code !~ '^[a-z_0-9]{1,80}$'
    or p_retry_after is null or p_retry_after not between 0 and 3600 then raise exception 'INBOX_INVALID_INPUT'; end if;
  -- After begin, only a known rejection / pre-send configuration failure permits another send.
  if item.reply_started_at is not null and p_outcome='retry' and p_code not in ('provider_rate_limited','provider_config_missing') then raise exception 'INBOX_UNSAFE_RETRY'; end if;
  terminal:=p_outcome<>'retry' or item.attempts>=8;
  update public.whatsapp_inbox set status=case when p_outcome='ambiguous' then 'ambiguous' when terminal then 'failed' else 'pending' end,
    reply_started_at=case when not terminal then null else reply_started_at end,
    last_error_code=case when p_outcome='retry' and terminal then 'attempts_exhausted' else p_code end,
    completed_at=case when terminal then clock_timestamp() end,lease_token=null,lease_until=null,
    available_at=clock_timestamp()+make_interval(secs=>greatest(p_retry_after,least(3600,15*(2^item.attempts)::integer))) where id=p_id;
end;
$function$
;

-- signature: public.finalize_due_account_deletions(integer)
CREATE OR REPLACE FUNCTION public.finalize_due_account_deletions(batch_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    request_row record;
    completed_count integer := 0;
    has_blocker boolean;
begin
    for request_row in
        select user_id
        from public.account_deletion_requests
        where status = 'pending' and scheduled_for <= now()
        order by scheduled_for
        limit greatest(1, least(batch_limit, 200))
        for update skip locked
    loop
        select
            exists(select 1 from public.businesses where owner_id = request_row.user_id)
            or exists(select 1 from public.staff where user_id = request_row.user_id)
            or exists(select 1 from public.user_roles where user_id = request_row.user_id)
            or exists(select 1 from public.user_global_roles where user_id = request_row.user_id)
            or exists(select 1 from public.super_admins_legacy where user_id = request_row.user_id)
            or exists(
                select 1 from public.bookings
                where client_id = request_row.user_id
                  and status in ('hold', 'confirmed', 'paid')
                  and start_at >= now()
            )
        into has_blocker;

        if has_blocker then
            update public.account_deletion_requests
            set status = 'blocked', updated_at = now()
            where user_id = request_row.user_id;
            continue;
        end if;

        delete from public.reviews where client_id = request_row.user_id;
        update public.bookings
        set client_id = null,
            client_name = 'Удалённый пользователь',
            client_email = null,
            client_phone = null
        where client_id = request_row.user_id;

        delete from public.user_current_business where user_id = request_row.user_id;
        delete from public.profiles where id = request_row.user_id;
        delete from auth.users where id = request_row.user_id;

        update public.account_deletion_requests
        set status = 'completed', completed_at = now(), updated_at = now()
        where user_id = request_row.user_id;
        completed_count := completed_count + 1;
    end loop;

    return completed_count;
end;
$function$
;

-- signature: public.finance_business_timezone(uuid)
CREATE OR REPLACE FUNCTION public.finance_business_timezone(p_biz_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text;
begin
    select coalesce(nullif(btrim(tz),''),'Asia/Bishkek') into v_tz from public.businesses where id=p_biz_id;
    if v_tz is null then raise exception using errcode='42501',message='FINANCE_BUSINESS_NOT_FOUND'; end if;
    perform now() at time zone v_tz; -- Invalid configured timezone fails, never silently changes a financial day.
    return v_tz;
end;
$function$
;

-- signature: public.finance_can_manage_business(uuid,uuid)
CREATE OR REPLACE FUNCTION public.finance_can_manage_business(p_actor_id uuid, p_biz_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select p_actor_id is not null and (
        exists(select 1 from public.businesses b where b.id=p_biz_id and b.owner_id=p_actor_id)
        or exists(select 1 from public.user_roles u join public.roles r on r.id=u.role_id
            where u.user_id=p_actor_id and u.biz_id=p_biz_id and r.key in ('owner','admin','manager'))
        or public.finance_is_platform_admin(p_actor_id)
    );
$function$
;

-- signature: public.finance_is_platform_admin(uuid)
CREATE OR REPLACE FUNCTION public.finance_is_platform_admin(p_actor_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select p_actor_id is not null and (
        exists(select 1 from public.user_global_roles u join public.roles r on r.id=u.role_id
            where u.user_id=p_actor_id and r.scope='platform' and r.key='super_admin')
        or exists(select 1 from public.super_admins_legacy s where s.user_id=p_actor_id)
        -- Current admin issuance and user_roles_with_user view still use this legacy store.
        or exists(select 1 from public.user_roles u join public.roles r on r.id=u.role_id
            where u.user_id=p_actor_id and u.biz_id is null and r.key='super_admin')
    );
$function$
;

-- signature: public.find_accounts_by_contact(text,text)
CREATE OR REPLACE FUNCTION public.find_accounts_by_contact(p_email text DEFAULT NULL::text, p_phone_digits text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, email text, phone text, full_name text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select u.id, u.email::text, u.phone::text, nullif(u.raw_user_meta_data ->> 'full_name', '')
      from auth.users u
     where u.deleted_at is null
       and ((nullif(btrim(p_email), '') is not null
             and lower(u.email) = lower(btrim(p_email))
             and u.email_confirmed_at is not null)
         or (nullif(p_phone_digits, '') is not null
             and u.phone in (p_phone_digits, '+' || p_phone_digits)
             and u.phone_confirmed_at is not null))
     order by u.created_at
     limit 5;
$function$
;

-- signature: public.finish_booking_notification(uuid,uuid,text,text,integer)
CREATE OR REPLACE FUNCTION public.finish_booking_notification(p_event_id uuid, p_lease_token uuid, p_outcome text, p_error_code text DEFAULT NULL::text, p_retry_after_seconds integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox; v_status text;
begin
    select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
    if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp() then
        raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
    end if;
    if p_outcome is null or p_outcome not in ('sent','retry','continue','obsolete','failed') then raise exception 'INVALID_OUTBOX_OUTCOME' using errcode='22023'; end if;
    if p_outcome='sent' and (v_event.prepared_at is null or exists(
        select 1 from public.booking_notification_deliveries where event_id=p_event_id and sent_at is null
    )) then raise exception 'OUTBOX_DELIVERIES_PENDING' using errcode='22023'; end if;
    v_status:=case when p_outcome='continue' then 'pending' when p_outcome='retry' then case when v_event.attempts>=8 then 'failed' else 'pending' end else p_outcome end;
    update public.booking_notification_outbox set status=v_status,lease_token=null,lease_until=null,
        attempts=case when p_outcome='continue' then greatest(attempts-1,0) else attempts end,
        last_error_code=left(p_error_code,120),completed_at=case when v_status='pending' then null else now() end,
        available_at=case when p_outcome='continue' then now() else now()+make_interval(secs=>greatest(least(coalesce(p_retry_after_seconds,0),3600),least(3600,15*(2^least(v_event.attempts,8))::integer))) end
        where id=p_event_id;
end;
$function$
;

-- signature: public.finish_cron_execution(uuid,text,integer,text)
CREATE OR REPLACE FUNCTION public.finish_cron_execution(p_id uuid, p_outcome text, p_http_status integer, p_error_code text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_run public.cron_executions;
begin
    if p_outcome is null or p_outcome not in ('succeeded','failed') or p_http_status is null
       or p_http_status not between 100 and 599 or length(p_error_code)>80
       or (p_outcome='succeeded' and p_http_status not between 200 and 299) then
        raise exception using errcode='22023',message='CRON_EXECUTION_INVALID';
    end if;
    select * into v_run from public.cron_executions where id=p_id for update;
    if not found then raise exception using errcode='P0002',message='CRON_EXECUTION_NOT_FOUND'; end if;
    if v_run.outcome<>'running' then
        if v_run.outcome=p_outcome and v_run.http_status=p_http_status then return; end if;
        raise exception using errcode='40001',message='CRON_EXECUTION_ALREADY_FINISHED';
    end if;
    update public.cron_executions set outcome=p_outcome,http_status=p_http_status,error_code=p_error_code,
        completed_at=clock_timestamp() where id=p_id;
end $function$
;

-- signature: public.get_api_metrics_stats(text,integer,text)
CREATE OR REPLACE FUNCTION public.get_api_metrics_stats(p_endpoint text, p_window_minutes integer DEFAULT 60, p_method text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_result jsonb;
    v_window_start timestamptz;
    v_status_codes jsonb;
begin
    v_window_start := timezone('utc'::text, now()) - (p_window_minutes || ' minutes')::interval;

    select jsonb_object_agg(codes.status_code::text, codes.requests)
      into v_status_codes
      from (
            select status_code, count(*) as requests
              from public.api_request_metrics
             where endpoint = p_endpoint
               and created_at >= v_window_start
               and (p_method is null or method = p_method)
               and status_code is not null
             group by status_code
           ) codes;

    select jsonb_build_object(
        'endpoint', p_endpoint,
        'method', coalesce(p_method, 'all'),
        'window_minutes', p_window_minutes,
        'total_requests', count(*),
        'success_count', count(*) filter (where status_code < 400),
        'client_error_count', count(*) filter (where status_code >= 400 and status_code < 500),
        'server_error_count', count(*) filter (where status_code >= 500),
        'avg_duration_ms', coalesce(avg(duration_ms), 0),
        'min_duration_ms', coalesce(min(duration_ms), 0),
        'max_duration_ms', coalesce(max(duration_ms), 0),
        'p95_duration_ms', coalesce(percentile_cont(0.95) within group (order by duration_ms), 0),
        'p99_duration_ms', coalesce(percentile_cont(0.99) within group (order by duration_ms), 0),
        'error_rate', case
            when count(*) > 0 then
                round((count(*) filter (where status_code >= 400)::numeric / count(*)::numeric) * 100, 2)
            else 0
        end,
        'error_types', jsonb_agg(distinct error_type) filter (where error_type is not null),
        'status_codes', v_status_codes
    )
    into v_result
    from public.api_request_metrics
    where endpoint = p_endpoint
      and created_at >= v_window_start
      and (p_method is null or method = p_method);

    return coalesce(v_result, jsonb_build_object('error', 'No data'));
end;
$function$
;

-- signature: public.get_applicable_visit_package_for_booking(uuid)
CREATE OR REPLACE FUNCTION public.get_applicable_visit_package_for_booking(p_booking_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_booking record; v_package_id uuid; v_today date;
begin
    perform public.assert_booking_finance_access(p_booking_id);
    select b.id, b.biz_id, b.client_id, b.branch_id, b.service_id, b.status, coalesce(z.tz, 'Asia/Bishkek') as tz
      into v_booking
      from public.bookings b
      join public.businesses z on z.id = b.biz_id
     where b.id = p_booking_id;
    if v_booking.client_id is null or v_booking.status<>'paid'
        or exists(select 1 from public.client_visit_package_uses where booking_id=p_booking_id) then return null; end if;
    -- The package is valid through valid_until in the business's own calendar.
    v_today := (now() at time zone v_booking.tz)::date;
    select cvp.id into v_package_id
    from public.client_visit_packages cvp join public.visit_package_plans p on p.id=cvp.plan_id
    where cvp.client_id=v_booking.client_id and p.biz_id=v_booking.biz_id
        and cvp.remaining_visits>0 and cvp.valid_until>=v_today and p.is_active=true
        and (p.service_id is null or p.service_id=v_booking.service_id)
        and (p.branch_ids is null or array_length(p.branch_ids,1) is null or v_booking.branch_id=any(p.branch_ids))
    order by cvp.valid_until,cvp.id limit 1;
    return v_package_id;
end;
$function$
;

-- signature: public.get_business_finance_stats_impl_20261109(uuid,date,date,uuid,boolean)
CREATE OR REPLACE FUNCTION public.get_business_finance_stats_impl_20261109(p_biz_id uuid, p_date_from date, p_date_to date, p_branch_id uuid DEFAULT NULL::uuid, p_include_open boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_result jsonb;
    v_today date;
BEGIN
    v_today := current_date;
    
    -- Сначала получаем статистику по каждому сотруднику
    WITH staff_data AS (
        SELECT 
            st.id AS staff_id,
            st.full_name AS staff_name,
            st.is_active,
            st.branch_id,
            COUNT(s.id) AS total_shifts,
            COUNT(*) FILTER (WHERE s.status = 'closed') AS closed_shifts,
            COUNT(*) FILTER (WHERE s.status = 'open') AS open_shifts,
            COALESCE(SUM(s.total_amount) FILTER (WHERE s.status = 'closed'), 0) AS total_amount,
            COALESCE(SUM(s.master_share) FILTER (WHERE s.status = 'closed'), 0) AS total_master,
            COALESCE(SUM(s.salon_share) FILTER (WHERE s.status = 'closed'), 0) AS total_salon,
            COALESCE(SUM(s.consumables_amount) FILTER (WHERE s.status = 'closed'), 0) AS total_consumables,
            COALESCE(SUM(s.late_minutes) FILTER (WHERE s.status = 'closed'), 0) AS total_late_minutes
        FROM public.staff st
        LEFT JOIN public.staff_shifts s ON s.staff_id = st.id
            AND s.biz_id = p_biz_id
            AND s.shift_date >= p_date_from
            AND s.shift_date <= p_date_to
        WHERE st.biz_id = p_biz_id
          AND (p_branch_id IS NULL OR st.branch_id = p_branch_id)
        GROUP BY st.id, st.full_name, st.is_active, st.branch_id
    ),
    staff_stats_json AS (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'staff_id', sd.staff_id,
                'staff_name', sd.staff_name,
                'is_active', sd.is_active,
                'branch_id', sd.branch_id,
                'shifts', jsonb_build_object(
                    'total', sd.total_shifts,
                    'closed', sd.closed_shifts,
                    'open', sd.open_shifts
                ),
                'stats', jsonb_build_object(
                    'total_amount', sd.total_amount,
                    'total_master', sd.total_master,
                    'total_salon', sd.total_salon,
                    'total_consumables', sd.total_consumables,
                    'total_late_minutes', sd.total_late_minutes
                )
            )
            ORDER BY sd.staff_name
        ), '[]'::jsonb) AS staff_stats
        FROM staff_data sd
    ),
    total_data AS (
        SELECT 
            COUNT(s.id) AS total_shifts,
            COUNT(*) FILTER (WHERE s.status = 'closed') AS closed_shifts,
            COUNT(*) FILTER (WHERE s.status = 'open') AS open_shifts,
            COALESCE(SUM(s.total_amount) FILTER (WHERE s.status = 'closed'), 0) AS total_amount,
            COALESCE(SUM(s.master_share) FILTER (WHERE s.status = 'closed'), 0) AS total_master,
            COALESCE(SUM(s.salon_share) FILTER (WHERE s.status = 'closed'), 0) AS total_salon,
            COALESCE(SUM(s.consumables_amount) FILTER (WHERE s.status = 'closed'), 0) AS total_consumables,
            COALESCE(SUM(s.late_minutes) FILTER (WHERE s.status = 'closed'), 0) AS total_late_minutes
        FROM public.staff st
        LEFT JOIN public.staff_shifts s ON s.staff_id = st.id
            AND s.biz_id = p_biz_id
            AND s.shift_date >= p_date_from
            AND s.shift_date <= p_date_to
        WHERE st.biz_id = p_biz_id
          AND (p_branch_id IS NULL OR st.branch_id = p_branch_id)
    )
    SELECT jsonb_build_object(
        'staff_stats', ssj.staff_stats,
        'total_stats', jsonb_build_object(
            'total_shifts', td.total_shifts,
            'closed_shifts', td.closed_shifts,
            'open_shifts', td.open_shifts,
            'total_amount', td.total_amount,
            'total_master', td.total_master,
            'total_salon', td.total_salon,
            'total_consumables', td.total_consumables,
            'total_late_minutes', td.total_late_minutes
        )
    )
    INTO v_result
    FROM staff_stats_json ssj
    CROSS JOIN total_data td;
    
    -- Если нужно включить открытые смены, добавляем их расчеты
    IF p_include_open THEN
        -- Для открытых смен нужно считать из позиций
        -- Это делается отдельно, так как требует JOIN с staff_shift_items
        -- Пока оставляем это на стороне API для гибкости
    END IF;
    
    RETURN v_result;
END;
$function$
;

-- signature: public.get_business_finance_stats(uuid,date,date,uuid,boolean)
CREATE OR REPLACE FUNCTION public.get_business_finance_stats(p_biz_id uuid, p_date_from date, p_date_to date, p_branch_id uuid DEFAULT NULL::uuid, p_include_open boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    perform public.assert_finance_access(p_biz_id);
    if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id) then
        raise exception using errcode='42501',message='FINANCE_FORBIDDEN';
    end if;
    return public.get_business_finance_stats_impl_20261109(p_biz_id,p_date_from,p_date_to,p_branch_id,p_include_open);
end;
$function$
;

-- signature: public.get_client_visit_count(uuid,uuid)
CREATE OR REPLACE FUNCTION public.get_client_visit_count(p_client_id uuid, p_branch_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_count integer;
begin
    -- Считаем только завершенные (paid) бронирования в этом филиале
    select count(*)::integer
    into v_count
    from public.bookings
    where client_id = p_client_id
      and branch_id = p_branch_id
      and status = 'paid'
      and end_at < now();
    
    return coalesce(v_count, 0);
end;
$function$
;

-- signature: public.get_free_slots_complex_day_v1(uuid,uuid,uuid,date,integer,integer,integer)
CREATE OR REPLACE FUNCTION public.get_free_slots_complex_day_v1(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid, p_day date, p_duration_min integer, p_step_min integer DEFAULT 15, p_per_staff integer DEFAULT 200)
 RETURNS TABLE(staff_id uuid, branch_id uuid, start_at timestamp with time zone, end_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_staff record;
    v_sched record;
    v_biz_tz text;
    v_effective_branch_id uuid;
begin
  -- current_user is the definer; the SET ROLE/session login identifies the invoker.
  IF p_staff_id IS NULL AND coalesce(nullif(current_setting('role',true),'none'),session_user)
    NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'USE_PAGED_SLOTS';
  END IF;
    if p_duration_min is null or p_duration_min <= 0 then
        raise exception 'INVALID_DURATION_MIN';
    end if;

    select b.tz into v_biz_tz from public.businesses b where b.id = p_biz_id;
    if v_biz_tz is null then
        v_biz_tz := 'Asia/Bishkek';
    end if;

    for v_staff in
        select st.id as staff_id, st.branch_id as home_branch_id
        from public.staff st
        where st.biz_id = p_biz_id
          and st.is_active
          and (p_staff_id is null or st.id = p_staff_id)
    loop
        select * into v_sched from public.resolve_staff_day(v_staff.staff_id, p_day);
        if not found then continue; end if;
        if v_sched.intervals is null or jsonb_array_length(v_sched.intervals) = 0 then
            continue;
        end if;

        v_effective_branch_id := v_sched.branch_id;
        if p_branch_id is not null and v_effective_branch_id is distinct from p_branch_id then
            continue;
        end if;

        return query
        with
            raw_intervals as (
                select jsonb_array_elements(v_sched.intervals) as j
            ),
            work as (
                select
                    ((p_day::text || ' ' || (j->>'start'))::timestamp) as begin_local,
                    ((p_day::text || ' ' || (j->>'end'))::timestamp)   as end_local
                from raw_intervals
            ),
            timeline as (
                select
                    generate_series(
                        w.begin_local,
                        w.end_local - make_interval(mins => p_duration_min),
                        make_interval(mins => p_step_min)
                    ) as slot_local_start
                from work w
                where w.end_local > w.begin_local
            ),
            slots_local as (
                select
                    t.slot_local_start,
                    t.slot_local_start + make_interval(mins => p_duration_min) as slot_local_end
                from timeline t
            ),
            breaks_local as (
                select
                    ((p_day::text || ' ' || (j->>'start'))::timestamp) as b_start_local,
                    ((p_day::text || ' ' || (j->>'end'))::timestamp)   as b_end_local
                from jsonb_array_elements(coalesce(v_sched.breaks, '[]'::jsonb)) as j
            ),
            slots_no_breaks as (
                select s.*
                from slots_local s
                where not exists (
                    select 1
                    from breaks_local b
                    where tstzrange((s.slot_local_start at time zone v_biz_tz), (s.slot_local_end at time zone v_biz_tz), '[)')
                          && tstzrange((b.b_start_local at time zone v_biz_tz), (b.b_end_local at time zone v_biz_tz), '[)')
                )
            ),
            slots_tz as (
                select
                    (s.slot_local_start at time zone v_biz_tz) as slot_start,
                    (s.slot_local_end   at time zone v_biz_tz) as slot_end
                from slots_no_breaks s
            ),
            free as (
                select stz.slot_start, stz.slot_end
                from slots_tz stz
                where not exists (
                    select 1
                    from public.bookings bk
                    where bk.biz_id = p_biz_id
                      and bk.staff_id = v_staff.staff_id
                      and (bk.status in ('confirmed', 'paid') or (bk.status='hold' and bk.expires_at>now()))
                      and tstzrange(bk.start_at, bk.end_at, '[)') && tstzrange(stz.slot_start, stz.slot_end, '[)')
                )
                order by stz.slot_start
                limit p_per_staff
            )
        select v_staff.staff_id, coalesce(p_branch_id, v_effective_branch_id), f.slot_start, f.slot_end
        from free f;
    end loop;

    return;
end;
$function$
;

-- signature: public.get_free_slots_page_v1(uuid,uuid,date,uuid,integer,uuid,jsonb,integer)
CREATE OR REPLACE FUNCTION public.get_free_slots_page_v1(p_biz_id uuid, p_branch_id uuid, p_day date, p_service_id uuid, p_duration_min integer, p_staff_id uuid, p_cursor jsonb, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_scope text;
  v_after_staff uuid;
  v_after_start timestamptz;
  v_staff record;
  v_slot record;
  v_scanned integer := 0;
  v_slots jsonb := '[]'::jsonb;
  v_next jsonb := null;
BEGIN
  IF p_biz_id IS NULL OR p_branch_id IS NULL OR p_day IS NULL
    OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100
    OR (p_service_id IS NULL AND (p_duration_min IS NULL OR p_duration_min NOT BETWEEN 1 AND 1440))
    OR (p_service_id IS NOT NULL AND p_duration_min IS NOT NULL) THEN
    RAISE EXCEPTION 'INVALID_SLOTS_PAGE_INPUT';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.branches b WHERE b.id=p_branch_id AND b.biz_id=p_biz_id AND b.is_active) THEN
    RAISE EXCEPTION 'BRANCH_NOT_FOUND_OR_INACTIVE';
  END IF;
  IF p_service_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM public.services s WHERE s.id=p_service_id AND s.biz_id=p_biz_id AND s.branch_id=p_branch_id AND s.active
  ) THEN RAISE EXCEPTION 'SERVICE_NOT_FOUND_OR_INACTIVE'; END IF;
  v_scope := md5(jsonb_build_array(p_biz_id,p_branch_id,p_day,p_service_id,p_duration_min,p_staff_id)::text);
  IF p_cursor IS NOT NULL THEN
    IF jsonb_typeof(p_cursor) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'INVALID_SLOTS_CURSOR'; END IF;
    IF NOT (p_cursor ?& ARRAY['v','scope','staff_id','start_at'])
      OR (SELECT count(*) FROM jsonb_object_keys(p_cursor))<>4
      OR p_cursor->'v' IS DISTINCT FROM '1'::jsonb
      OR p_cursor->>'scope' IS DISTINCT FROM v_scope
      OR jsonb_typeof(p_cursor->'staff_id') IS DISTINCT FROM 'string'
      OR (p_cursor->>'staff_id') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      OR jsonb_typeof(p_cursor->'start_at') NOT IN ('string','null') THEN
      RAISE EXCEPTION 'INVALID_SLOTS_CURSOR';
    END IF;
    v_after_staff := (p_cursor->>'staff_id')::uuid;
    BEGIN
      v_after_start := (p_cursor->>'start_at')::timestamptz;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'INVALID_SLOTS_CURSOR'; END;
    IF (v_after_start IS NOT NULL AND NOT isfinite(v_after_start))
      OR (p_staff_id IS NOT NULL AND p_staff_id<>v_after_staff) THEN RAISE EXCEPTION 'INVALID_SLOTS_CURSOR'; END IF;
  END IF;
  FOR v_staff IN
    SELECT st.id FROM public.staff st
    WHERE st.biz_id=p_biz_id AND st.is_active AND (p_staff_id IS NULL OR st.id=p_staff_id)
      AND (v_after_staff IS NULL OR st.id>v_after_staff OR (st.id=v_after_staff AND v_after_start IS NOT NULL))
    ORDER BY st.id LIMIT 9
  LOOP
    -- Ninth candidate is a cheap lookahead only, never a ninth resolver call.
    IF v_scanned=8 THEN RETURN jsonb_build_object('slots',v_slots,'next_cursor',v_next); END IF;
    v_scanned := v_scanned+1;
    FOR v_slot IN
      SELECT DISTINCT s.staff_id,s.branch_id,s.start_at,s.end_at FROM (
        SELECT a.* FROM public.get_free_slots_service_day_v2(
          p_biz_id,p_service_id,p_day,2147483647,15,v_staff.id
        ) a WHERE p_service_id IS NOT NULL
        UNION ALL
        SELECT a.* FROM public.get_free_slots_complex_day_v1(
          p_biz_id,p_branch_id,v_staff.id,p_day,p_duration_min,15,2147483647
        ) a WHERE p_service_id IS NULL
      ) s
      WHERE s.branch_id=p_branch_id
        AND (v_after_staff IS DISTINCT FROM v_staff.id OR v_after_start IS NULL OR s.start_at>v_after_start)
      ORDER BY s.start_at,s.end_at
      LIMIT p_limit+1
    LOOP
      IF jsonb_array_length(v_slots)=p_limit THEN
        RETURN jsonb_build_object('slots',v_slots,'next_cursor',v_next);
      END IF;
      v_slots := v_slots || jsonb_build_array(to_jsonb(v_slot));
      v_next := jsonb_build_object('v',1,'scope',v_scope,'staff_id',v_staff.id,'start_at',v_slot.start_at);
    END LOOP;
    -- NULL start means this staff was exhausted, including empty schedules.
    v_next := jsonb_build_object('v',1,'scope',v_scope,'staff_id',v_staff.id,'start_at',null);
  END LOOP;
  RETURN jsonb_build_object('slots',v_slots,'next_cursor',null);
END;
$function$
;

-- signature: public.get_free_slots_service_day_v2(uuid,uuid,date,integer,integer,uuid)
CREATE OR REPLACE FUNCTION public.get_free_slots_service_day_v2(p_biz_id uuid, p_service_id uuid, p_day date, p_per_staff integer, p_step_min integer, p_staff_id uuid)
 RETURNS TABLE(staff_id uuid, branch_id uuid, start_at timestamp with time zone, end_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_service record;
  v_staff record;
  v_sched record;
  v_dur_min int;
  v_biz_tz text;
  v_effective_branch_id uuid;
BEGIN
  -- current_user is the definer; the SET ROLE/session login identifies the invoker.
  IF p_staff_id IS NULL AND coalesce(nullif(current_setting('role',true),'none'),session_user)
    NOT IN ('service_role','postgres','supabase_admin') THEN
    RAISE EXCEPTION 'USE_PAGED_SLOTS';
  END IF;
  -- 1) сервис и его филиал
  SELECT s.id, s.biz_id, s.branch_id, s.duration_min
  INTO v_service
  FROM public.services s
  WHERE s.id = p_service_id AND s.biz_id = p_biz_id AND s.active;

  IF v_service.id IS NULL THEN
    RAISE EXCEPTION 'SERVICE_NOT_FOUND_OR_INACTIVE';
  END IF;

  v_dur_min := v_service.duration_min;

  -- tz бизнеса
  SELECT b.tz INTO v_biz_tz FROM public.businesses b WHERE b.id = p_biz_id;
  IF v_biz_tz IS NULL THEN v_biz_tz := 'Asia/Bishkek'; END IF;

  -- 2) Select the requested staff before resolving any schedules.
  -- Separate UNION branches retain a primary-key lookup even with a generic plan.
  FOR v_staff IN
    SELECT st.id AS staff_id, st.branch_id AS home_branch_id
    FROM public.staff st
    WHERE p_staff_id IS NULL AND st.biz_id = p_biz_id AND st.is_active
      AND public._staff_performs_service(st.id, p_service_id, v_service.branch_id)
    UNION ALL
    SELECT st.id AS staff_id, st.branch_id AS home_branch_id
    FROM public.staff st
    WHERE p_staff_id IS NOT NULL AND st.id = p_staff_id
      AND st.biz_id = p_biz_id AND st.is_active
      AND public._staff_performs_service(st.id, p_service_id, v_service.branch_id)
  LOOP
    -- Получаем расписание на дату (resolve_staff_day уже учитывает временные переводы)
    SELECT * INTO v_sched FROM public.resolve_staff_day(v_staff.staff_id, p_day);
    IF NOT FOUND THEN CONTINUE; END IF;

    -- Проверяем, что в расписании есть интервалы работы
    IF v_sched.intervals IS NULL OR jsonb_array_length(v_sched.intervals) = 0 THEN
      CONTINUE;
    END IF;

    -- Определяем эффективный филиал мастера на эту дату из расписания
    v_effective_branch_id := v_sched.branch_id;

    -- The canonical resolver already decided the branch. A second lookup must
    -- never resurrect a superseded transfer in a different branch.
    IF v_effective_branch_id IS DISTINCT FROM v_service.branch_id THEN CONTINUE; END IF;

    -- генерим сетку слотов в локальном времени бизнеса → переводим в timestamptz
    RETURN QUERY
      WITH
        raw_intervals AS (
          SELECT jsonb_array_elements(v_sched.intervals) AS j
        ),
        work AS (
          SELECT
            -- локальный старт/финиш (ts without tz), собранные из p_day + 'HH:MM'
            ( (p_day::text || ' ' || (j->>'start'))::timestamp ) AS begin_local,
            ( (p_day::text || ' ' || (j->>'end'))::timestamp )   AS end_local
          FROM raw_intervals
        ),
        timeline AS (
          SELECT
            generate_series(
              w.begin_local,
              w.end_local - make_interval(mins => v_dur_min),
              make_interval(mins => p_step_min)
            ) AS slot_local_start
          FROM work w
          WHERE w.end_local > w.begin_local
        ),
        slots_local AS (
          SELECT
            t.slot_local_start,
            t.slot_local_start + make_interval(mins => v_dur_min) AS slot_local_end
          FROM timeline t
        ),
        -- убираем перерывы
        breaks_local AS (
          SELECT
            ( (p_day::text || ' ' || (j->>'start'))::timestamp ) AS b_start_local,
            ( (p_day::text || ' ' || (j->>'end'))::timestamp )   AS b_end_local
          FROM jsonb_array_elements(v_sched.breaks) AS j
        ),
        slots_no_breaks AS (
          SELECT s.*
          FROM slots_local s
          WHERE NOT EXISTS (
            SELECT 1
            FROM breaks_local b
            WHERE tstzrange((s.slot_local_start AT TIME ZONE v_biz_tz), (s.slot_local_end AT TIME ZONE v_biz_tz), '[)')
                  && tstzrange((b.b_start_local AT TIME ZONE v_biz_tz), (b.b_end_local AT TIME ZONE v_biz_tz), '[)')
          )
        ),
        slots_tz AS (
          SELECT
            -- приводим «локальное» время бизнеса к timestamptz (UTC)
            (s.slot_local_start AT TIME ZONE v_biz_tz) AS slot_start,
            (s.slot_local_end   AT TIME ZONE v_biz_tz) AS slot_end
          FROM slots_no_breaks s
        ),
        free AS (
          SELECT stz.slot_start, stz.slot_end
          FROM slots_tz stz
          WHERE NOT EXISTS (
            SELECT 1
            FROM public.bookings bk
            WHERE bk.biz_id = p_biz_id
              AND bk.staff_id = v_staff.staff_id
              AND (bk.status IN ('confirmed', 'paid') OR (bk.status='hold' AND bk.expires_at>now()))
              AND tstzrange(bk.start_at, bk.end_at, '[)') && tstzrange(stz.slot_start, stz.slot_end, '[)')
          )
          ORDER BY stz.slot_start
          LIMIT p_per_staff
        )
    SELECT v_staff.staff_id, v_effective_branch_id, f.slot_start, f.slot_end
    FROM free f;
  END LOOP;

  RETURN;
END$function$
;

-- signature: public.get_free_slots_service_day_v2(uuid,uuid,date,integer,integer)
CREATE OR REPLACE FUNCTION public.get_free_slots_service_day_v2(p_biz_id uuid, p_service_id uuid, p_day date, p_per_staff integer DEFAULT 200, p_step_min integer DEFAULT 15)
 RETURNS TABLE(staff_id uuid, branch_id uuid, start_at timestamp with time zone, end_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
    SELECT * FROM public.get_free_slots_service_day_v2(
        p_biz_id, p_service_id, p_day, p_per_staff, p_step_min, NULL::uuid
    );
$function$
;

-- signature: public.get_free_slots_service_day(uuid,uuid,date,integer,integer,text)
CREATE OR REPLACE FUNCTION public.get_free_slots_service_day(p_biz_id uuid, p_service_id uuid, p_day date, p_per_staff integer DEFAULT 3, p_step_min integer DEFAULT 15, p_tz text DEFAULT 'Asia/Bishkek'::text)
 RETURNS TABLE(staff_id uuid, start_at timestamp with time zone, end_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with svc as (
  select duration_min from services
  where id = p_service_id and biz_id = p_biz_id and active = true
),
masters as (
  select st.id as staff_id
  from service_staff ss
  join staff st on st.id = ss.staff_id and st.biz_id = p_biz_id and st.is_active = true
  where ss.service_id = p_service_id
),
hours as (
  select
    wh.staff_id,
    -- границы окна локально
    make_timestamptz(extract(year from p_day)::int,
                     extract(month from p_day)::int,
                     extract(day from p_day)::int,
                     split_part(i->>'start',':',1)::int,
                     split_part(i->>'start',':',2)::int,
                     0, p_tz) at time zone p_tz as start_local,
    make_timestamptz(extract(year from p_day)::int,
                     extract(month from p_day)::int,
                     extract(day from p_day)::int,
                     split_part(i->>'end',':',1)::int,
                     split_part(i->>'end',':',2)::int,
                     0, p_tz) at time zone p_tz as end_local
  from working_hours wh
  join masters m on m.staff_id = wh.staff_id
  cross join lateral jsonb_array_elements(wh.intervals) as i
  where wh.biz_id = p_biz_id
    and wh.day_of_week = extract(isodow from p_day)::int % 7
),
grid as (
  select
    h.staff_id,
    (gs.slot at time zone p_tz) at time zone 'UTC' as start_at, -- делаем timestamptz корректно
    (gs.slot + (svc.duration_min || ' minutes')::interval) at time zone 'UTC' as end_at
  from hours h
  cross join svc
  cross join lateral generate_series(
    h.start_local,
    h.end_local - (svc.duration_min || ' minutes')::interval,
    (p_step_min || ' minutes')::interval
  ) as gs(slot)
),
free as (
  select g.*
  from grid g
  where not exists (
    select 1 from bookings b
    where b.biz_id = p_biz_id
      and b.staff_id = g.staff_id
      and b.status in ('hold','confirmed','paid')
      and tstzrange(b.start_at, b.end_at, '[)') && tstzrange(g.start_at, g.end_at, '[)')
  )
)
select staff_id, start_at, end_at
from (
  select f.*,
         row_number() over (partition by staff_id order by start_at asc) as rn
  from free f
) t
where rn <= p_per_staff
order by staff_id, start_at;
$function$
;

-- signature: public.get_my_notification_emails()
CREATE OR REPLACE FUNCTION public.get_my_notification_emails()
 RETURNS TABLE(email text, verified boolean, enabled boolean, sources text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        email.email,
        email.verified,
        email.enabled,
        coalesce(array_agg(source.source order by source.source), array[]::text[]) as sources
    from public.user_notification_emails email
    left join public.user_notification_email_sources source
        on source.email_id = email.id
    where email.user_id = auth.uid()
    group by email.id
    order by email.created_at, email.email;
$function$
;

-- signature: public.get_staff_finance_stats_impl_20261109(uuid,uuid,date,date,boolean)
CREATE OR REPLACE FUNCTION public.get_staff_finance_stats_impl_20261109(p_staff_id uuid, p_biz_id uuid, p_date_from date, p_date_to date, p_include_open boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
    v_result jsonb;
    v_today date;
    v_open_shift_id uuid;
    v_open_shift_data jsonb;
begin
    v_today := current_date;
    
    -- Получаем закрытые смены за период
    select jsonb_build_object(
        'closed_shifts', coalesce(jsonb_agg(
            jsonb_build_object(
                'id', s.id,
                'shift_date', s.shift_date,
                'status', s.status,
                'opened_at', s.opened_at,
                'closed_at', s.closed_at,
                'total_amount', s.total_amount,
                'consumables_amount', s.consumables_amount,
                'master_share', s.master_share,
                'salon_share', s.salon_share,
                'late_minutes', s.late_minutes,
                'hours_worked', s.hours_worked,
                'hourly_rate', s.hourly_rate,
                'guaranteed_amount', s.guaranteed_amount,
                'topup_amount', s.topup_amount,
                'items_count', (
                    select count(*)
                    from public.staff_shift_items
                    where shift_id = s.id
                )
            )
            order by s.shift_date desc
        ), '[]'::jsonb),
        'closed_stats', jsonb_build_object(
            'count', count(*),
            'total_amount', coalesce(sum(s.total_amount), 0),
            'total_master', coalesce(sum(s.master_share), 0),
            'total_salon', coalesce(sum(s.salon_share), 0),
            'total_consumables', coalesce(sum(s.consumables_amount), 0),
            'total_late_minutes', coalesce(sum(s.late_minutes), 0)
        )
    )
    into v_result
    from public.staff_shifts s
    where s.staff_id = p_staff_id
      and s.biz_id = p_biz_id
      and s.status = 'closed'
      and s.shift_date >= p_date_from
      and s.shift_date <= p_date_to;
    
    -- Если нужно включить открытые смены
    if p_include_open then
        -- Проверяем, есть ли открытая смена на сегодня
        select id
        into v_open_shift_id
        from public.staff_shifts
        where staff_id = p_staff_id
          and biz_id = p_biz_id
          and shift_date = v_today
          and status = 'open'
        limit 1;
        
        if v_open_shift_id is not null then
            -- Получаем данные открытой смены с агрегацией позиций
            select jsonb_build_object(
                'id', s.id,
                'shift_date', s.shift_date,
                'status', s.status,
                'opened_at', s.opened_at,
                'closed_at', s.closed_at,
                'late_minutes', s.late_minutes,
                'hourly_rate', coalesce(s.hourly_rate, st.hourly_rate),
                'percent_master', coalesce(s.percent_master, st.percent_master, 60),
                'percent_salon', coalesce(s.percent_salon, st.percent_salon, 40),
                'items', coalesce(
                    jsonb_agg(
                        jsonb_build_object(
                            'id', si.id,
                            'client_name', si.client_name,
                            'service_name', si.service_name,
                            'service_amount', si.service_amount,
                            'consumables_amount', si.consumables_amount,
                            'note', si.note,
                            'booking_id', si.booking_id
                        )
                        order by si.created_at
                    ) filter (where si.id is not null),
                    '[]'::jsonb
                ),
                'calculated', jsonb_build_object(
                    'total_amount', coalesce(sum(si.service_amount), 0),
                    'total_consumables', coalesce(sum(si.consumables_amount), 0),
                    'items_count', count(si.id)
                )
            )
            into v_open_shift_data
            from public.staff_shifts s
            left join public.staff st on st.id = s.staff_id
            left join public.staff_shift_items si on si.shift_id = s.id
            where s.id = v_open_shift_id
            group by s.id, s.shift_date, s.status, s.opened_at, s.closed_at, 
                     s.late_minutes, s.hourly_rate, s.percent_master, s.percent_salon,
                     st.hourly_rate, st.percent_master, st.percent_salon;
            
            -- Добавляем открытую смену в результат
            v_result := v_result || jsonb_build_object(
                'open_shift', v_open_shift_data,
                'has_open_shift', true
            );
        else
            v_result := v_result || jsonb_build_object(
                'open_shift', null,
                'has_open_shift', false
            );
        end if;
    end if;
    
    return v_result;
end;
$function$
;

-- signature: public.get_staff_finance_stats(uuid,uuid,date,date,boolean)
CREATE OR REPLACE FUNCTION public.get_staff_finance_stats(p_staff_id uuid, p_biz_id uuid, p_date_from date, p_date_to date, p_include_open boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    perform public.assert_finance_access(p_biz_id,p_staff_id);
    return public.get_staff_finance_stats_impl_20261109(p_staff_id,p_biz_id,p_date_from,p_date_to,p_include_open);
end;
$function$
;

-- signature: public.grant_branch_admin(uuid,uuid)
CREATE OR REPLACE FUNCTION public.grant_branch_admin(p_branch_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_biz uuid; v_actor uuid:=auth.uid();
begin
 select biz_id into v_biz from public.branches where id=p_branch_id for update;
 if v_biz is null or p_user_id is null or v_actor is null or not (
  public.is_super_admin() or public.has_role('owner',v_biz) or public.has_role('admin',v_biz)
  or public.has_role('manager',v_biz)
  or exists(select 1 from public.businesses where id=v_biz and owner_id=v_actor)
 ) then raise exception using errcode='42501',message='BRANCH_ADMIN_FORBIDDEN'; end if;
 insert into public.branch_admins(branch_id,user_id) values(p_branch_id,p_user_id)
 on conflict(branch_id,user_id) do nothing;
end $function$
;

-- signature: public.guard_direct_shift_finance_write()
CREATE OR REPLACE FUNCTION public.guard_direct_shift_finance_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if current_user in ('anon','authenticated') then
        raise exception using errcode='42501',message='SHIFT_COMMAND_REQUIRED';
    end if;
    if tg_op='DELETE' then return old; end if;
    return new;
end;
$function$
;

-- signature: public.guard_last_super_admin()
CREATE OR REPLACE FUNCTION public.guard_last_super_admin()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_sa uuid;
begin
  select id into v_sa from public.roles where key='super_admin';
  if OLD.role_id = v_sa and OLD.biz_id is null then
    perform 1
      from public.user_roles
      where biz_id is null and role_id = v_sa and user_id <> OLD.user_id
      limit 1;
    if not found then
      raise exception 'Нельзя удалить последнего super_admin' using errcode='P0001';
    end if;
  end if;
  return OLD;
end $function$
;

-- signature: public.guard_legacy_staff_schedule_write()
CREATE OR REPLACE FUNCTION public.guard_legacy_staff_schedule_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare target uuid;
begin
    target := case when TG_OP='DELETE' then old.staff_id else new.staff_id end;
    perform 1 from public.staff where id=target for update;
    if exists(select 1 from public.staff_schedule_versions where staff_id=target)
        or (TG_OP='UPDATE' and exists(select 1 from public.staff_schedule_versions where staff_id=old.staff_id))
        then raise exception 'SCHEDULE_USE_PUBLICATION_EDITOR'; end if;
    if TG_OP='DELETE' then return old; end if;
    return new;
end;
$function$
;

-- signature: public.guard_shift_day_hours()
CREATE OR REPLACE FUNCTION public.guard_shift_day_hours()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text; v_hours numeric;
begin
    if new.hours_worked is not null then
        v_tz:=public.finance_business_timezone(new.biz_id);
        v_hours:=extract(epoch from (((new.shift_date+1)::timestamp at time zone v_tz)-(new.shift_date::timestamp at time zone v_tz)))/3600;
        if new.hours_worked<0 or new.hours_worked>v_hours or new.hours_worked::text in ('NaN','Infinity','-Infinity') then
            raise exception using errcode='23514',message='SHIFT_HOURS_OUTSIDE_LOCAL_DAY';
        end if;
    end if;
    return new;
end;
$function$
;

-- signature: public.guard_staff_absence_booking()
CREATE OR REPLACE FUNCTION public.guard_staff_absence_booking()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                    declare business_tz text;
                                                                    begin
                                                                     if tg_op='UPDATE' then
                                                                        if old.cancelled_at is not null or new.cancelled_at is null or new.cancelled_by is null or (to_jsonb(new)-'cancelled_at'-'cancelled_by') is distinct from (to_jsonb(old)-'cancelled_at'-'cancelled_by') then raise exception 'SCHEDULE_INVALID'; end if;
                                                                         else
                                                                            if new.cancelled_at is not null or new.cancelled_by is not null then raise exception 'SCHEDULE_INVALID'; end if;
                                                                             end if;
                                                                              perform 1 from public.staff where id=new.staff_id and biz_id=new.biz_id for update;
                                                                               if not found then raise exception 'SCHEDULE_NOT_FOUND'; end if;
                                                                                if tg_op='UPDATE' then return new; end if;
                                                                                 if new.date_from is null or new.date_to is null or new.date_to<new.date_from then raise exception 'SCHEDULE_INVALID'; end if;
                                                                                  if exists(select 1 from public.staff_time_off t where t.staff_id=new.staff_id and t.biz_id=new.biz_id and t.cancelled_at is null and t.date_from<=new.date_to and t.date_to>=new.date_from) then raise exception 'SCHEDULE_ABSENCE_OVERLAP'; end if;
                                                                                   select coalesce(tz,'Asia/Bishkek') into business_tz from public.businesses where id=new.biz_id;
                                                                                    if exists(select 1 from public.bookings b where b.staff_id=new.staff_id and b.biz_id=new.biz_id and (b.status::text in ('confirmed','paid') or (b.status::text='hold' and b.expires_at>now())) and b.end_at>now() and b.start_at<((new.date_to+1)::timestamp at time zone business_tz) and b.end_at>(new.date_from::timestamp at time zone business_tz)) then raise exception 'SCHEDULE_BOOKING_CONFLICT'; end if;
                                                                                     return new;
                                                                                     end $function$
;

-- signature: public.guard_staff_home_change()
CREATE OR REPLACE FUNCTION public.guard_staff_home_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if new.branch_id is distinct from old.branch_id and not exists(
        select 1 from public.staff_home_branch_changes c where c.staff_id=old.id
        and c.from_branch_id is not distinct from old.branch_id and c.to_branch_id=new.branch_id
        and c.transaction_id=txid_current()) then raise exception 'SCHEDULE_USE_TRANSFER_COMMAND'; end if;
    return new;
end;
$function$
;

-- signature: public.guard_user_lifecycle_assignment()
CREATE OR REPLACE FUNCTION public.guard_user_lifecycle_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare target uuid;
begin
  if tg_table_name='businesses' then target:=new.owner_id; else target:=new.user_id; end if;
  if target is null then return new; end if;
  perform pg_advisory_xact_lock(184207,1);
  if not exists(select 1 from auth.users where id=target)
    or exists(select 1 from public.user_suspensions where user_id=target)
    or exists(select 1 from public.user_lifecycle_commands where user_id=target and not completed) then
    raise exception 'USER_LIFECYCLE_ASSIGNMENT_BLOCKED';
  end if;
  return new;
end;
$function$
;

-- signature: public.guard_user_lifecycle_session()
CREATE OR REPLACE FUNCTION public.guard_user_lifecycle_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare until_time timestamptz;
begin
  select banned_until into until_time from auth.users where id=new.user_id for share;
  if not found or until_time>now() or exists(select 1 from public.user_suspensions where user_id=new.user_id) then
    raise exception 'USER_SUSPENDED' using errcode='42501';
  end if;
  return new;
end;
$function$
;

-- signature: public.has_branch_admin(uuid)
CREATE OR REPLACE FUNCTION public.has_branch_admin(p_branch_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
       -- владелец бизнеса всегда проходит
       exists (
         select 1
         from public.businesses bb
         join public.branches br on br.biz_id = bb.id
         where br.id = p_branch_id
           and bb.owner_id = auth.uid()
       )
    or -- бизнес-админ тоже проходит (админ уровня бизнеса)
       exists (
         select 1
         from public.user_roles ur
         join public.roles r on r.id = ur.role_id
         join public.branches br on br.id = p_branch_id
         where ur.user_id = auth.uid()
           and r.key = 'admin'
           and ur.biz_id = br.biz_id
       )
    or -- конкретный админ этого филиала
       exists (
         select 1
         from public.branch_admins ba
         where ba.branch_id = p_branch_id
           and ba.user_id   = auth.uid()
       );
$function$
;

-- signature: public.has_role(text,uuid)
CREATE OR REPLACE FUNCTION public.has_role(p_role_key text, p_biz_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists(
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = auth.uid()
      and r.key = p_role_key
      and (p_biz_id is null and ur.biz_id is null or ur.biz_id = p_biz_id)
  );
$function$
;

-- signature: public.has_role(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.has_role(p_user_id uuid, p_biz_id uuid, p_role_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = p_user_id
      and ur.biz_id  = p_biz_id
      and r.key = p_role_key
  );
$function$
;

-- signature: public.hold_complex_slot_guest(uuid,uuid,uuid,timestamp with time zone,jsonb,text,text,text)
CREATE OR REPLACE FUNCTION public.hold_complex_slot_guest(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_services jsonb, p_client_name text, p_client_phone text, p_client_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_booking_id uuid;
    v_expires_at timestamptz;
    v_total_duration_min integer := 0;
    v_item jsonb;
    v_service_id uuid;
    v_duration_min integer;
    v_order_index integer;
    v_index integer := 0;
    v_end timestamptz;
    v_client_name_trimmed text;
    v_client_phone_trimmed text;
    v_client_email_trimmed text;
begin
    if p_client_name is null or trim(p_client_name) = '' then
        raise exception 'client_name is required';
    end if;
    if p_client_phone is null or trim(p_client_phone) = '' then
        raise exception 'client_phone is required';
    end if;

    v_client_name_trimmed := trim(p_client_name);
    v_client_phone_trimmed := trim(p_client_phone);
    v_client_email_trimmed := case when p_client_email is not null then trim(p_client_email) else null end;

    if not exists (
        select 1 from public.branches
        where id = p_branch_id and biz_id = p_biz_id and is_active = true
    ) then
        raise exception 'branch not found or inactive';
    end if;

    if not exists (
        select 1 from public.staff
        where id = p_staff_id and biz_id = p_biz_id and (branch_id = p_branch_id or exists (select 1 from public.staff_schedule_versions v where v.staff_id = p_staff_id)) and is_active = true
    ) then
        raise exception 'staff not found or inactive';
    end if;

    if p_services is null or jsonb_typeof(p_services) <> 'array'
       or jsonb_array_length(p_services) = 0 or jsonb_array_length(p_services) > 20 then
        raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;
    if p_start < now() - interval '5 minutes' then
        raise exception using errcode = '22023', message = 'SLOT_IN_PAST';
    end if;

    -- Each service: the branch's, active, performed by the master; duration from the catalog.
    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_service_id := (p_services->v_index->>'service_id')::uuid;
        if v_service_id is null then
            raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
        end if;

        select s.duration_min into v_duration_min
          from public.services s
         where s.id = v_service_id and s.biz_id = p_biz_id and s.branch_id = p_branch_id and s.active = true;
        if not found then
            raise exception using errcode = '22023', message = 'service not found or inactive';
        end if;
        if not public._staff_performs_service(p_staff_id, v_service_id, p_branch_id) then
            raise exception using errcode = '22023', message = 'STAFF_DOES_NOT_PERFORM_SERVICE';
        end if;

        v_total_duration_min := v_total_duration_min + v_duration_min;
    end loop;

    if v_total_duration_min <= 0 then
        raise exception using errcode = '22023', message = 'INVALID_BOOKING_REQUEST';
    end if;

    v_end := p_start + (v_total_duration_min || ' minutes')::interval;
    if not public.schedule_contains_booking(p_staff_id, p_branch_id, p_start, v_end) then
        raise exception 'SCHEDULE_OUTSIDE_WORKING_HOURS';
    end if;
    v_expires_at := now() + interval '2 minutes';

    if exists (
        select 1 from public.bookings
        where staff_id = p_staff_id
          and (status in ('confirmed','paid') or (status = 'hold' and expires_at > now()))
          and tstzrange(start_at, end_at, '[)') && tstzrange(p_start, v_end, '[)')
    ) then
        raise exception 'time slot is already booked';
    end if;

    insert into public.bookings (
        biz_id, branch_id, service_id, staff_id,
        client_id, client_name, client_phone, client_email,
        start_at, end_at, status, expires_at
    )
    values (
        p_biz_id, p_branch_id, (p_services->0->>'service_id')::uuid, p_staff_id,
        null, v_client_name_trimmed, v_client_phone_trimmed, v_client_email_trimmed,
        p_start, v_end, 'hold'::booking_status, v_expires_at
    )
    returning id into v_booking_id;

    for v_index in 0 .. jsonb_array_length(p_services) - 1 loop
        v_item := p_services->v_index;
        v_service_id := (v_item->>'service_id')::uuid;
        v_order_index := coalesce((v_item->>'order_index')::integer, v_index);
        select s.duration_min into v_duration_min from public.services s where s.id = v_service_id;

        insert into public.booking_services (booking_id, service_id, duration_min, order_index)
        values (v_booking_id, v_service_id, v_duration_min, v_order_index);
    end loop;

    return v_booking_id;
end;
$function$
;

-- signature: public.hold_complex_slot(uuid,uuid,uuid,timestamp with time zone,jsonb)
CREATE OR REPLACE FUNCTION public.hold_complex_slot(p_biz_id uuid, p_branch_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_services jsonb)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public._hold_complex_slot_for_actor(p_biz_id,p_branch_id,p_staff_id,p_start,p_services,auth.uid());
$function$
;

-- signature: public.hold_slot_guest(uuid,uuid,uuid,uuid,timestamp with time zone,text,text,text)
CREATE OR REPLACE FUNCTION public.hold_slot_guest(p_biz_id uuid, p_branch_id uuid, p_service_id uuid, p_staff_id uuid, p_start timestamp with time zone, p_client_name text, p_client_phone text, p_client_email text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_service_duration_min int;
  v_end timestamptz;
  v_expires_at timestamptz;
  v_booking_id uuid;
  v_client_name_trimmed text;
  v_client_phone_trimmed text;
  v_client_email_trimmed text;
begin
  if p_client_name is null or trim(p_client_name)='' then
    raise exception 'client_name is required';
  end if;
  if p_client_phone is null or trim(p_client_phone)='' then
    raise exception 'client_phone is required';
  end if;
  v_client_name_trimmed:=trim(p_client_name);
  v_client_phone_trimmed:=trim(p_client_phone);
  v_client_email_trimmed:=case when p_client_email is not null then trim(p_client_email) else null end;
  select duration_min into v_service_duration_min from public.services
    where id=p_service_id and biz_id=p_biz_id and branch_id=p_branch_id and active=true;
  if not found then raise exception using errcode='22023', message='service not found or inactive'; end if;
  if not exists(select 1 from public.staff where id=p_staff_id and biz_id=p_biz_id and is_active=true) then
    raise exception 'staff not found or inactive';
  end if;
  if not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id and is_active=true) then
    raise exception 'branch not found or inactive';
  end if;
  if not public._staff_performs_service(p_staff_id,p_service_id,p_branch_id) then
    raise exception using errcode='22023', message='STAFF_DOES_NOT_PERFORM_SERVICE';
  end if;
  if p_start < now() - interval '5 minutes' then
    raise exception using errcode='22023', message='SLOT_IN_PAST';
  end if;
  v_end:=p_start+(v_service_duration_min||' minutes')::interval;
  if not public.schedule_contains_booking(p_staff_id,p_branch_id,p_start,v_end) then
    raise exception 'SCHEDULE_OUTSIDE_WORKING_HOURS';
  end if;
  v_expires_at:=now()+interval '2 minutes';
  if exists(
    select 1 from public.bookings where staff_id=p_staff_id and status in('confirmed','paid')
      and tstzrange(start_at,end_at,'[)')&&tstzrange(p_start,v_end,'[)')
    union all
    select 1 from public.bookings where staff_id=p_staff_id and status='hold'
      and (expires_at is null or expires_at>=now())
      and tstzrange(start_at,end_at,'[)')&&tstzrange(p_start,v_end,'[)')
  ) then raise exception 'time slot is already booked'; end if;
  insert into public.bookings(biz_id,branch_id,service_id,staff_id,client_id,
    client_name,client_phone,client_email,start_at,end_at,status,expires_at)
  values(p_biz_id,p_branch_id,p_service_id,p_staff_id,null,
    v_client_name_trimmed,v_client_phone_trimmed,v_client_email_trimmed,p_start,v_end,
    'hold'::booking_status,v_expires_at)
  returning id into v_booking_id;
  return v_booking_id;
end;
$function$
;

-- signature: public.hold_slot(uuid,uuid,uuid,uuid,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.hold_slot(p_biz_id uuid, p_branch_id uuid, p_service_id uuid, p_staff_id uuid, p_start timestamp with time zone)
 RETURNS uuid
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public._hold_slot_for_actor(p_biz_id,p_branch_id,p_service_id,p_staff_id,p_start,auth.uid());
$function$
;

-- signature: public.initialize_all_ratings(integer)
CREATE OR REPLACE FUNCTION public.initialize_all_ratings(p_days_back integer DEFAULT 30)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
    v_config public.rating_global_config;
    v_start_date date;
    v_end_date date;
    r_staff record;
    r_branch record;
    r_biz record;
    v_staff_rating numeric;
    v_branch_rating numeric;
    v_biz_rating numeric;
    v_default_rating numeric := 50.0; -- Стартовый рейтинг для новых бизнесов
begin
    raise notice 'Starting rating initialization (last % days)', p_days_back;
    
    -- Получаем активную конфигурацию
    select * into v_config
    from public.rating_global_config
    where is_active = true
    order by valid_from desc
    limit 1;
    
    if v_config is null then
        raise exception 'No active rating configuration found';
    end if;
    
    -- Определяем диапазон дат для пересчета
    v_end_date := timezone('Asia/Bishkek', now())::date - interval '1 day'; -- Вчера
    v_start_date := v_end_date - (p_days_back || ' days')::interval;
    
    raise notice 'Recalculating metrics from % to %', v_start_date, v_end_date;
    
    -- Пересчитываем метрики за весь диапазон
    perform public.recalculate_ratings_for_date_range(v_start_date, v_end_date);
    
    raise notice 'Updating aggregated ratings...';
    
    -- 4. Обновляем агрегированные рейтинги в таблицах staff, branches, businesses
    for r_staff in select id from public.staff loop
        begin
            v_staff_rating := public.calculate_staff_rating(r_staff.id);
            -- Если рейтинг NULL или 0, устанавливаем начальный рейтинг
            if v_staff_rating is null or v_staff_rating = 0 then
                v_staff_rating := v_default_rating;
            end if;
            update public.staff set rating_score = v_staff_rating where id = r_staff.id;
        exception when others then
            raise notice 'Error updating staff rating for staff_id=%: %', r_staff.id, SQLERRM;
            -- Устанавливаем минимальный рейтинг при ошибке
            update public.staff set rating_score = v_default_rating where id = r_staff.id and (rating_score is null or rating_score = 0);
        end;
    end loop;

    for r_branch in select id from public.branches loop
        begin
            v_branch_rating := public.calculate_branch_rating(r_branch.id);
            -- Если рейтинг NULL или 0, рассчитываем как средний рейтинг сотрудников
            if v_branch_rating is null or v_branch_rating = 0 then
                select coalesce(avg(rating_score), v_default_rating) into v_branch_rating
                from public.staff
                where branch_id = r_branch.id and is_active = true;
            end if;
            update public.branches set rating_score = v_branch_rating where id = r_branch.id;
        exception when others then
            raise notice 'Error updating branch rating for branch_id=%: %', r_branch.id, SQLERRM;
            -- Устанавливаем минимальный рейтинг при ошибке
            update public.branches set rating_score = v_default_rating where id = r_branch.id and (rating_score is null or rating_score = 0);
        end;
    end loop;

    for r_biz in select id from public.businesses loop
        begin
            v_biz_rating := public.calculate_biz_rating(r_biz.id);
            -- Если рейтинг NULL или 0, рассчитываем как средний рейтинг филиалов
            if v_biz_rating is null or v_biz_rating = 0 then
                select coalesce(avg(rating_score), v_default_rating) into v_biz_rating
                from public.branches
                where biz_id = r_biz.id and is_active = true;
            end if;
            update public.businesses set rating_score = v_biz_rating where id = r_biz.id;
        exception when others then
            raise notice 'Error updating biz rating for biz_id=%: %', r_biz.id, SQLERRM;
            -- Устанавливаем минимальный рейтинг при ошибке
            update public.businesses set rating_score = v_default_rating where id = r_biz.id and (rating_score is null or rating_score = 0);
        end;
    end loop;
    
    raise notice 'Rating initialization completed';
end;
$function$
;

-- signature: public.is_super_admin()
CREATE OR REPLACE FUNCTION public.is_super_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
 select auth.uid() is not null and (
  exists(select 1 from public.user_global_roles g join public.roles r on r.id=g.role_id
   where g.user_id=auth.uid() and r.scope='platform' and r.key='super_admin')
  or exists(select 1 from public.super_admins_legacy l where l.user_id=auth.uid())
  or exists(select 1 from public.user_roles u join public.roles r on r.id=u.role_id
   where u.user_id=auth.uid() and u.biz_id is null and r.key='super_admin')
 );
$function$
;

-- signature: public.lock_shift_for_item_write()
CREATE OR REPLACE FUNCTION public.lock_shift_for_item_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_shift_id uuid; v_shift record; v_booking record;
begin
    if tg_op='UPDATE' and new.shift_id is distinct from old.shift_id then
        raise exception using errcode='42501',message='SHIFT_ITEM_SCOPE';
    end if;
    v_shift_id:=case when tg_op='DELETE' then old.shift_id else new.shift_id end;
    select * into v_shift from public.staff_shifts where id=v_shift_id for update;
    if found then
        perform public.assert_finance_access(v_shift.biz_id,v_shift.staff_id);
        if v_shift.status<>'open' then raise exception using errcode='40001',message='SHIFT_CLOSED'; end if;
        if tg_op<>'DELETE' and new.booking_id is not null then
            select * into v_booking from public.bookings where id=new.booking_id for update;
            if not found or v_booking.biz_id is distinct from v_shift.biz_id or v_booking.staff_id is distinct from v_shift.staff_id
                or (v_booking.start_at at time zone public.finance_business_timezone(v_shift.biz_id))::date is distinct from v_shift.shift_date then
                raise exception using errcode='42501',message='SHIFT_BOOKING_SCOPE';
            end if;
            if v_booking.status='cancelled' then raise exception using errcode='22023',message='SHIFT_BOOKING_CANCELLED'; end if;
        end if;
        -- Every writer, including legacy SQL and direct table writes, participates in the fence.
        update public.staff_shifts set ledger_revision=ledger_revision where id=v_shift_id;
    end if;
    if tg_op='DELETE' then return old; end if;
    return new;
end;
$function$
;

-- signature: public.log_api_metric(text,text,integer,integer,uuid,uuid,uuid,text,text,integer,integer,jsonb,inet,text)
CREATE OR REPLACE FUNCTION public.log_api_metric(p_endpoint text, p_method text, p_status_code integer, p_duration_ms integer, p_user_id uuid DEFAULT NULL::uuid, p_staff_id uuid DEFAULT NULL::uuid, p_biz_id uuid DEFAULT NULL::uuid, p_error_message text DEFAULT NULL::text, p_error_type text DEFAULT NULL::text, p_request_size_bytes integer DEFAULT NULL::integer, p_response_size_bytes integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT NULL::jsonb, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_metric_id uuid;
begin
    -- Валидация статус кода
    if p_status_code < 100 or p_status_code >= 600 then
        raise exception 'Invalid status_code: %', p_status_code;
    end if;
    
    -- Валидация типа ошибки
    if p_error_type is not null and p_error_type not in ('validation', 'database', 'auth', 'server', 'network') then
        raise exception 'Invalid error_type: %', p_error_type;
    end if;
    
    -- Вставляем метрику
    insert into public.api_request_metrics (
        endpoint,
        method,
        status_code,
        duration_ms,
        user_id,
        staff_id,
        biz_id,
        error_message,
        error_type,
        request_size_bytes,
        response_size_bytes,
        metadata,
        ip_address,
        user_agent
    )
    values (
        p_endpoint,
        p_method,
        p_status_code,
        p_duration_ms,
        p_user_id,
        p_staff_id,
        p_biz_id,
        p_error_message,
        p_error_type,
        p_request_size_bytes,
        p_response_size_bytes,
        p_metadata,
        p_ip_address,
        p_user_agent
    )
    returning id into v_metric_id;
    
    return v_metric_id;
end;
$function$
;

-- signature: public.log_booking_analytics_event()
CREATE OR REPLACE FUNCTION public.log_booking_analytics_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    -- Логируем создание бронирования
    if tg_op = 'INSERT' then
        insert into public.analytics_events (
            event_type,
            biz_id,
            branch_id,
            booking_id,
            client_id,
            source,
            session_id,
            metadata
        )
        values (
            'booking_created',
            new.biz_id,
            new.branch_id,
            new.id,
            new.client_id,
            coalesce(current_setting('app.booking_source', true), 'system'),
            null,
            jsonb_build_object(
                'status', new.status
            )
        );
        return new;
    end if;

    -- Логируем переход в confirmed/paid
    if tg_op = 'UPDATE' then
        -- Только если статус реально изменился
        if (old.status is distinct from new.status)
           and (new.status in ('confirmed', 'paid')) then
            insert into public.analytics_events (
                event_type,
                biz_id,
                branch_id,
                booking_id,
                client_id,
                source,
                session_id,
                metadata
            )
            values (
                'booking_confirmed_or_paid',
                new.biz_id,
                new.branch_id,
                new.id,
                new.client_id,
                coalesce(current_setting('app.booking_source', true), 'system'),
                null,
                jsonb_build_object(
                    'previous_status', old.status,
                    'status', new.status
                )
            );
        end if;
        return new;
    end if;

    return new;
end;
$function$
;

-- signature: public.log_finance_operation(uuid,uuid,text,text,text,uuid,date,jsonb,jsonb,jsonb,text,text,inet,text)
CREATE OR REPLACE FUNCTION public.log_finance_operation(p_staff_id uuid, p_biz_id uuid, p_operation_type text, p_message text, p_log_level text DEFAULT 'info'::text, p_shift_id uuid DEFAULT NULL::uuid, p_shift_date date DEFAULT NULL::date, p_metadata jsonb DEFAULT NULL::jsonb, p_before_data jsonb DEFAULT NULL::jsonb, p_after_data jsonb DEFAULT NULL::jsonb, p_error_message text DEFAULT NULL::text, p_error_stack text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_log_id uuid;
begin
    -- Валидация типа операции
    if p_operation_type not in ('shift_open', 'shift_close', 'item_create', 'item_update', 'item_delete', 'items_save', 'error') then
        raise exception 'Invalid operation_type: %', p_operation_type;
    end if;
    
    -- Валидация уровня логирования
    if p_log_level not in ('debug', 'info', 'warn', 'error') then
        raise exception 'Invalid log_level: %', p_log_level;
    end if;
    
    -- Вставляем лог
    insert into public.staff_finance_operation_logs (
        staff_id,
        biz_id,
        shift_id,
        shift_date,
        operation_type,
        log_level,
        message,
        metadata,
        before_data,
        after_data,
        error_message,
        error_stack,
        ip_address,
        user_agent
    )
    values (
        p_staff_id,
        p_biz_id,
        p_shift_id,
        p_shift_date,
        p_operation_type,
        p_log_level,
        p_message,
        p_metadata,
        p_before_data,
        p_after_data,
        p_error_message,
        p_error_stack,
        p_ip_address,
        p_user_agent
    )
    returning id into v_log_id;
    
    return v_log_id;
end;
$function$
;

-- signature: public.log_shift_close_trigger()
CREATE OR REPLACE FUNCTION public.log_shift_close_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    -- Логируем только если статус изменился на 'closed'
    if new.status = 'closed' and old.status = 'open' then
        perform public.log_finance_operation(
            new.staff_id,
            new.biz_id,
            'shift_close',
            format('Смена закрыта для сотрудника %s на дату %s', new.staff_id, new.shift_date),
            'info',
            new.id,
            new.shift_date,
            jsonb_build_object(
                'closed_at', new.closed_at,
                'total_amount', new.total_amount,
                'consumables_amount', new.consumables_amount,
                'master_share', new.master_share,
                'salon_share', new.salon_share,
                'guaranteed_amount', new.guaranteed_amount,
                'topup_amount', new.topup_amount,
                'hours_worked', new.hours_worked
            ),
            jsonb_build_object(
                'id', old.id,
                'status', old.status,
                'opened_at', old.opened_at
            ), -- before_data
            jsonb_build_object(
                'id', new.id,
                'status', new.status,
                'closed_at', new.closed_at,
                'total_amount', new.total_amount,
                'master_share', new.master_share,
                'salon_share', new.salon_share
            ) -- after_data
        );
    end if;
    
    return new;
end;
$function$
;

-- signature: public.log_shift_items_trigger()
CREATE OR REPLACE FUNCTION public.log_shift_items_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
    v_shift_record record;
    v_operation_type text;
    v_message text;
begin
    -- Получаем информацию о смене
    select staff_id, biz_id, shift_date, id
    into v_shift_record
    from public.staff_shifts
    where id = coalesce(new.shift_id, old.shift_id);
    
    if v_shift_record is null then
        return coalesce(new, old);
    end if;
    
    -- Определяем тип операции
    if tg_op = 'INSERT' then
        v_operation_type := 'item_create';
        v_message := format('Создана позиция смены: клиент "%s", услуга "%s", сумма %s', 
            coalesce(new.client_name, 'не указан'),
            coalesce(new.service_name, 'не указана'),
            new.service_amount
        );
        
        perform public.log_finance_operation(
            v_shift_record.staff_id,
            v_shift_record.biz_id,
            v_operation_type,
            v_message,
            'info',
            v_shift_record.id,
            v_shift_record.shift_date,
            jsonb_build_object(
                'item_id', new.id,
                'client_name', new.client_name,
                'service_name', new.service_name,
                'service_amount', new.service_amount,
                'consumables_amount', new.consumables_amount,
                'booking_id', new.booking_id
            ),
            null, -- before_data
            jsonb_build_object(
                'id', new.id,
                'client_name', new.client_name,
                'service_amount', new.service_amount
            ) -- after_data
        );
    elsif tg_op = 'DELETE' then
        v_operation_type := 'item_delete';
        v_message := format('Удалена позиция смены: клиент "%s", услуга "%s", сумма %s', 
            coalesce(old.client_name, 'не указан'),
            coalesce(old.service_name, 'не указана'),
            old.service_amount
        );
        
        perform public.log_finance_operation(
            v_shift_record.staff_id,
            v_shift_record.biz_id,
            v_operation_type,
            v_message,
            'info',
            v_shift_record.id,
            v_shift_record.shift_date,
            jsonb_build_object(
                'item_id', old.id,
                'client_name', old.client_name,
                'service_name', old.service_name,
                'service_amount', old.service_amount
            ),
            jsonb_build_object(
                'id', old.id,
                'client_name', old.client_name,
                'service_amount', old.service_amount
            ), -- before_data
            null -- after_data
        );
    elsif tg_op = 'UPDATE' then
        v_operation_type := 'item_update';
        v_message := format('Обновлена позиция смены: клиент "%s"', 
            coalesce(new.client_name, 'не указан')
        );
        
        perform public.log_finance_operation(
            v_shift_record.staff_id,
            v_shift_record.biz_id,
            v_operation_type,
            v_message,
            'info',
            v_shift_record.id,
            v_shift_record.shift_date,
            jsonb_build_object(
                'item_id', new.id,
                'changes', jsonb_build_object(
                    'client_name', jsonb_build_object('old', old.client_name, 'new', new.client_name),
                    'service_name', jsonb_build_object('old', old.service_name, 'new', new.service_name),
                    'service_amount', jsonb_build_object('old', old.service_amount, 'new', new.service_amount),
                    'consumables_amount', jsonb_build_object('old', old.consumables_amount, 'new', new.consumables_amount)
                )
            ),
            jsonb_build_object(
                'id', old.id,
                'client_name', old.client_name,
                'service_amount', old.service_amount
            ), -- before_data
            jsonb_build_object(
                'id', new.id,
                'client_name', new.client_name,
                'service_amount', new.service_amount
            ) -- after_data
        );
    end if;
    
    return coalesce(new, old);
end;
$function$
;

-- signature: public.log_shift_open_trigger()
CREATE OR REPLACE FUNCTION public.log_shift_open_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    -- Логируем при INSERT с status='open' или при UPDATE когда статус сменился на 'open'.
    -- При INSERT OLD не определён — не обращаемся к OLD.
    if new.status = 'open' and (TG_OP = 'INSERT' or old.status != 'open') then
        perform public.log_finance_operation(
            new.staff_id,
            new.biz_id,
            'shift_open',
            format('Смена открыта для сотрудника %s на дату %s', new.staff_id, new.shift_date),
            'info',
            new.id,
            new.shift_date,
            jsonb_build_object(
                'opened_at', new.opened_at,
                'expected_start', new.expected_start,
                'late_minutes', new.late_minutes
            ),
            null, -- before_data
            jsonb_build_object(
                'id', new.id,
                'status', new.status,
                'opened_at', new.opened_at,
                'shift_date', new.shift_date
            ) -- after_data
        );
    end if;

    return new;
end;
$function$
;

-- signature: public.mark_booking_attendance_command(uuid,uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.mark_booking_attendance_command(p_booking_id uuid, p_biz_id uuid, p_actor_id uuid, p_attended boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare v_booking public.bookings%rowtype; v_target public.booking_status;
    v_role text:=coalesce(nullif(current_setting('role',true),'none'),session_user);
    v_benefit jsonb; v_package boolean; v_has_ledger boolean; v_has_benefit boolean;
begin
    if v_role not in ('service_role','postgres','supabase_admin') or p_actor_id is null
        or not public.finance_can_manage_business(p_actor_id,p_biz_id) then
        raise exception using errcode='42501',message='BOOKING_FORBIDDEN';
    end if;
    if p_attended is null then raise exception using errcode='22023',message='ATTENDANCE_REQUIRED'; end if;
    -- Shared transition helper takes staff before booking, matching Save/Close.
    v_booking:=public._assert_booking_transition_access(p_booking_id);
    if v_booking.biz_id is distinct from p_biz_id then raise exception using errcode='42501',message='BOOKING_FORBIDDEN'; end if;
    v_target:=case when p_attended then 'paid'::public.booking_status else 'no_show'::public.booking_status end;
    v_has_ledger:=exists(select 1 from public.staff_shift_items where booking_id=p_booking_id);
    v_has_benefit:=v_booking.promotion_applied is not null or v_booking.subscription_applied is not null
        or exists(select 1 from public.client_visit_package_uses where booking_id=p_booking_id)
        or exists(select 1 from public.client_promotion_usage where booking_id=p_booking_id);
    if v_booking.status=v_target and (v_target='paid' or not (v_has_ledger or v_has_benefit)) then
        -- Exact replay is read-only; use the persisted benefit snapshot below.
        null;
    else
        if v_has_ledger or v_has_benefit or v_booking.status not in ('hold','confirmed') then
            raise exception using errcode='40001',message='BOOKING_FINANCIAL_REVIEW_REQUIRED';
        end if;
        if v_booking.start_at is null or v_booking.start_at>=statement_timestamp() then
            raise exception using errcode='22023',message='BOOKING_NOT_IN_PAST';
        end if;
        if v_target='paid' then
            perform public.update_booking_status_with_promotion(p_booking_id,v_target);
        else
            perform public.update_booking_status_no_check(p_booking_id,v_target);
        end if;
        select * into v_booking from public.bookings where id=p_booking_id;
        if v_booking.status<>v_target then raise exception using errcode='P0001',message='ATTENDANCE_UNCONFIRMED'; end if;
    end if;
    v_package:=v_booking.subscription_applied is not null;
    v_benefit:=coalesce(v_booking.subscription_applied,v_booking.promotion_applied);
    return jsonb_build_object('ok',true,'status',v_booking.status,
        'promotion_applied',v_booking.promotion_applied is not null and not v_package,
        'subscription_applied',v_package,
        'promotion_info',case when v_benefit is null then null else jsonb_build_object(
            'title',coalesce(v_benefit->>'plan_name_ru',v_benefit->>'promotion_title',''),
            'discount_percent',coalesce((v_benefit->>'discount_percent')::numeric,0),
            'discount_amount',coalesce((v_benefit->>'discount_amount')::numeric,0),
            'final_amount',coalesce((v_benefit->>'final_amount')::numeric,0)) end);
end;
$function$
;

-- signature: public.members_of_biz(uuid)
CREATE OR REPLACE FUNCTION public.members_of_biz(p_biz_id uuid)
 RETURNS TABLE(user_id uuid, email text, phone text, full_name text, roles text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- доступ: глобальный супер или владелец/админ конкретного бизнеса
  if not ( public.is_super_admin()
           or public.has_role('owner'::text, p_biz_id)
           or public.has_role('admin'::text, p_biz_id) ) then
    raise exception 'forbidden' using errcode = 'P0001';
  end if;

  return query
  select
    u.user_id,
    u.email::text,
    u.phone::text,
    u.full_name::text,
    array_agg(distinct u.role_key order by u.role_key)::text[] as roles
  from public.user_roles_with_user u
  where u.biz_id = p_biz_id
  group by u.user_id, u.email, u.phone, u.full_name
  order by coalesce(u.full_name, u.email::text, u.phone, u.user_id::text);
end;
$function$
;

-- signature: public.my_role_keys()
CREATE OR REPLACE FUNCTION public.my_role_keys()
 RETURNS text[]
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with role_rows as (
    select r.key::text as rk               -- <== замени r.key на твоё поле (key/slug/name)
    from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = auth.uid()
  ),
  owner_rows as (
    select 'owner'::text as rk
    from public.businesses b
    where b.owner_id = auth.uid()
  )
  select coalesce(array_agg(distinct rk), '{}')
  from (
    select rk from role_rows
    union all
    select rk from owner_rows
  ) x;
$function$
;

-- signature: public.open_staff_shift_safe(uuid,uuid,uuid,date,timestamp with time zone,timestamp with time zone,integer)
CREATE OR REPLACE FUNCTION public.open_staff_shift_safe(p_staff_id uuid, p_biz_id uuid, p_branch_id uuid, p_shift_date date, p_opened_at timestamp with time zone, p_expected_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_late_minutes integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_existing public.staff_shifts%rowtype; v_today date; v_tz text;
begin
    perform public.assert_finance_access(p_biz_id,p_staff_id);
    perform 1 from public.staff where id=p_staff_id and biz_id=p_biz_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    v_tz:=public.finance_business_timezone(p_biz_id);
    v_today:=(statement_timestamp() at time zone v_tz)::date;
    p_shift_date:=coalesce(p_shift_date,v_today);
    if p_shift_date>v_today then raise exception using errcode='40001',message='SHIFT_FUTURE_DATE'; end if;
    if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id) then
        raise exception using errcode='42501',message='FINANCE_FORBIDDEN';
    end if;
    select * into v_existing from public.staff_shifts where staff_id=p_staff_id and shift_date=p_shift_date for update;
    if found then
        if v_existing.biz_id is distinct from p_biz_id then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
        if v_existing.status='open' then return jsonb_build_object('ok',true,'action','already_open','shift',to_jsonb(v_existing)); end if;
        -- Reopen is a manager operation. It preserves the original attendance interval.
        if auth.role()<>'service_role' and not public.finance_can_manage_business(auth.uid(),p_biz_id) then
            raise exception using errcode='42501',message='FINANCE_FORBIDDEN';
        end if;
        update public.staff_shifts set status='open',closed_at=null where id=v_existing.id returning * into v_existing;
        perform public.update_shift_aggregates(p_staff_id,p_biz_id,p_shift_date,0,0,0,0,0,0);
        return jsonb_build_object('ok',true,'action','reopened','shift',to_jsonb(v_existing));
    end if;
    if p_shift_date<>v_today then raise exception using errcode='40001',message='SHIFT_DATE_REQUIRES_EXISTING_SHIFT'; end if;
    -- The caller supplies schedule/late data, but cannot invent a historical opening time.
    if p_opened_at is null or (p_opened_at at time zone v_tz)::date<>v_today then
        raise exception using errcode='40001',message='SHIFT_OPEN_TIME_MISMATCH';
    end if;
    insert into public.staff_shifts(staff_id,biz_id,branch_id,shift_date,status,opened_at,expected_start,late_minutes)
        values(p_staff_id,p_biz_id,p_branch_id,p_shift_date,'open',statement_timestamp(),p_expected_start,p_late_minutes)
        returning * into v_existing;
    return jsonb_build_object('ok',true,'action','created','shift',to_jsonb(v_existing));
end;
$function$
;

-- signature: public.prepare_booking_notification_deliveries(uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.prepare_booking_notification_deliveries(p_event_id uuid, p_lease_token uuid, p_deliveries jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox; v_delivery jsonb;
begin
    select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
    if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp() then
        raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
    end if;
    if not exists(select 1 from public.bookings where id=v_event.booking_id and notification_revision=v_event.booking_revision) then
        raise exception 'OUTBOX_EVENT_OBSOLETE' using errcode='40001';
    end if;
    if v_event.prepared_at is not null then return; end if;
    if p_deliveries is null or jsonb_typeof(p_deliveries)<>'array' or jsonb_array_length(p_deliveries)>200 then
        raise exception 'INVALID_OUTBOX_DELIVERIES' using errcode='22023';
    end if;
    for v_delivery in select value from jsonb_array_elements(p_deliveries) loop
        if octet_length((v_delivery->'payload')::text)>262144 then
            raise exception 'OUTBOX_PAYLOAD_TOO_LARGE' using errcode='22023';
        end if;
        insert into public.booking_notification_deliveries(event_id,delivery_key,channel,payload)
            values(p_event_id,v_delivery->>'key',v_delivery->>'channel',v_delivery->'payload');
    end loop;
    update public.booking_notification_outbox set prepared_at=now() where id=p_event_id;
end;
$function$
;

-- signature: public.prepare_user_lifecycle(uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.prepare_user_lifecycle(p_actor_id uuid, p_user_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare c public.user_lifecycle_commands;
begin
  if coalesce(nullif(current_setting('role',true),'none'),session_user) not in ('service_role','postgres','supabase_admin') then
    raise exception 'USER_LIFECYCLE_SERVICE_ONLY' using errcode='42501';
  end if;
  if p_actor_id is null or p_user_id is null or p_action is null or p_action not in ('block','unblock','delete') or length(p_reason)>500 then
    raise exception 'USER_LIFECYCLE_INVALID_INPUT' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(184207,1);
  if not exists(select 1 from auth.users where id=p_actor_id and coalesce(banned_until,now())<=now())
    or exists(select 1 from public.user_suspensions where user_id=p_actor_id)
    or not public.finance_is_platform_admin(p_actor_id) then
    raise exception 'USER_LIFECYCLE_FORBIDDEN' using errcode='42501';
  end if;
  if p_actor_id=p_user_id then raise exception 'USER_LIFECYCLE_SELF' using errcode='22023'; end if;
  select * into c from public.user_lifecycle_commands where user_id=p_user_id for update;
  if found and c.action=p_action and c.reason is not distinct from p_reason then
    -- Another verified administrator can recover an unfinished command after
    -- its original actor loses access. The operation identity stays unchanged.
    if not c.completed then update public.user_lifecycle_commands set actor_id=p_actor_id where user_id=p_user_id; end if;
    return jsonb_build_object('commandId',c.command_id,'completed',c.completed,'action',c.action);
  end if;
  if c.user_id is not null and not c.completed then raise exception 'USER_LIFECYCLE_PENDING' using errcode='P0001'; end if;
  if not exists(select 1 from auth.users where id=p_user_id) then raise exception 'USER_LIFECYCLE_NOT_FOUND' using errcode='P0002'; end if;
  if public.finance_is_platform_admin(p_user_id) then raise exception 'USER_LIFECYCLE_PROTECTED' using errcode='P0001'; end if;
  if p_action='delete' and exists(select 1 from public.businesses where owner_id=p_user_id) then
    raise exception 'USER_LIFECYCLE_OWNER' using errcode='P0001';
  end if;
  insert into public.user_lifecycle_commands(user_id,actor_id,action,reason)
    values(p_user_id,p_actor_id,p_action,p_reason)
    on conflict(user_id) do update set command_id=gen_random_uuid(),actor_id=excluded.actor_id,
      action=excluded.action,reason=excluded.reason,completed=false,created_at=now(),completed_at=null returning * into c;
  return jsonb_build_object('commandId',c.command_id,'completed',false,'action',c.action);
end;
$function$
;

-- signature: public.prevent_application_for_existing_business()
CREATE OR REPLACE FUNCTION public.prevent_application_for_existing_business()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
    if exists (
        select 1
        from public.businesses b
        where lower(regexp_replace(btrim(b.name), '[[:space:]]+', ' ', 'g'))
            = lower(regexp_replace(btrim(new.business_name), '[[:space:]]+', ' ', 'g'))
    ) then
        raise exception using
            errcode = 'P0001',
            message = 'APPLICATION_POLICY:business_exists';
    end if;

    return new;
end;
$function$
;

-- signature: public.prevent_owner_suspended()
CREATE OR REPLACE FUNCTION public.prevent_owner_suspended()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.owner_id is not null
     and exists (select 1 from public.user_suspensions where user_id = new.owner_id) then
    raise exception 'USER_SUSPENDED';
  end if;
  return new;
end;
$function$
;

-- signature: public.prevent_roles_for_suspended()
CREATE OR REPLACE FUNCTION public.prevent_roles_for_suspended()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if exists (select 1 from public.user_suspensions where user_id = new.user_id) then
    raise exception 'USER_SUSPENDED';
  end if;
  return new;
end;
$function$
;

-- signature: public.process_whatsapp_inbox(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.process_whatsapp_inbox(p_id uuid, p_token uuid, p_receiver text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
 SET lock_timeout TO '3s'
AS $function$
declare
  item public.whatsapp_inbox; profile_id uuid; profile_count integer; booking_ids uuid[];
  target public.bookings; target_staff uuid; booking_id uuid; booking_count integer; reply text; list_text text; outcome text;
begin
  item:=public._locked_whatsapp_inbox(p_id,p_token);
  if item.receiver is distinct from p_receiver then raise exception 'INBOX_INVALID_INPUT'; end if;
  if item.reply_payload is not null then return jsonb_build_object('outcome',item.command_receipt->>'outcome','payload',item.reply_payload); end if;
  if exists(select 1 from public.whatsapp_messages where whatsapp_message_id=item.message_id) then raise exception 'INBOX_LEGACY_OUTCOME_UNKNOWN'; end if;
  if item.provider_timestamp<clock_timestamp()-interval '24 hours' then raise exception 'INBOX_MESSAGE_EXPIRED'; end if;
  -- Lock matching profiles while establishing ownership; ambiguous duplicate phone records cannot select an identity.
  select count(*), (array_agg(p.id))[1] into profile_count,profile_id
    from (select id from public.profiles where phone=item.sender for share) p;
  if profile_count>1 then
    outcome:='identity_ambiguous'; reply:='Не удалось однозначно определить профиль. Откройте запись на сайте или обратитесь к администратору.';
  elsif item.command='media' then
    outcome:='media_ack'; reply:='Сообщение получено. Для управления записью отправьте текст: помощь, напомни, подтвердить или отмена.';
  elsif item.command='help' then
    outcome:='help'; reply:=E'Команды: «напомни» — записи; «подтвердить 1» — подтвердить; «отмена 1» — отменить; «помощь». Номер выбирается из текущего списка записей.';
  else
    -- Match the signed sender to the current profile phone; phone-only fallback is restricted to actual guest rows.
    select array_agg(b.id order by b.start_at,b.id) into booking_ids from (
      select b.id,b.start_at from public.bookings b
      where ((profile_id is not null and b.client_id=profile_id) or (profile_id is null and b.client_id is null and b.client_phone=item.sender))
        and b.status::text in ('hold','confirmed','paid') and b.start_at>=clock_timestamp()
      order by b.start_at,b.id limit 10
    ) b;
    booking_count:=coalesce(array_length(booking_ids,1),0);
    select string_agg(format('%s. %s (%s) — %s; %s; %s; %s',
      array_position(booking_ids,b.id),to_char(b.start_at at time zone coalesce(to_jsonb(biz)->>'tz','Asia/Bishkek'),'DD.MM.YYYY HH24:MI'),
      coalesce(to_jsonb(biz)->>'tz','Asia/Bishkek'),
      left(coalesce(to_jsonb(s)->>'name_ru','услуга'),60),left(coalesce(to_jsonb(st)->>'full_name','мастер'),60),
      left(coalesce(to_jsonb(br)->>'name','филиал'),60),left(coalesce(to_jsonb(br)->>'address',''),80)),E'\n' order by array_position(booking_ids,b.id))
      into list_text from public.bookings b
      left join public.businesses biz on biz.id=b.biz_id left join public.services s on s.id=b.service_id
      left join public.staff st on st.id=b.staff_id left join public.branches br on br.id=b.branch_id
      where b.id=any(booking_ids);
    if booking_count=0 then
      outcome:='no_active_bookings'; reply:='Активных предстоящих записей не найдено. Проверьте запись на сайте.';
    elsif item.command in ('remind','booking_info') then
      outcome:='booking_list'; reply:=E'Ваши ближайшие записи (не более 10):\n'||list_text||E'\nКоманды: «подтвердить 1», «отмена 1», «помощь».';
    elsif (item.booking_number is null and booking_count>1) or (item.booking_number is not null and item.booking_number not between 1 and booking_count) then
      outcome:='booking_choice_required'; reply:=E'Укажите номер из текущего списка:\n'||list_text||E'\nНапример: «подтвердить 1» или «отмена 1».';
    else
      booking_id:=booking_ids[coalesce(item.booking_number,1)];
      -- Booking/finance commands use staff -> booking lock order. Never invert it here.
      select staff_id into target_staff from public.bookings where id=booking_id;
      perform 1 from public.staff where id=target_staff for update;
      select * into target from public.bookings where id=booking_id for update;
      -- Recheck after acquiring the booking row lock: selection was a snapshot, not authorization.
      if not found or target.staff_id is distinct from target_staff or target.start_at<clock_timestamp() or target.status::text not in ('hold','confirmed','paid')
        or not ((profile_id is not null and target.client_id=profile_id) or
          (profile_id is null and target.client_id is null and target.client_phone=item.sender)) then
        outcome:='booking_changed'; reply:='Запись изменилась. Запросите список командой «напомни» и проверьте запись на сайте.';
      elsif item.command='confirm' and target.status::text in ('confirmed','paid') then
        outcome:='already_confirmed'; reply:='Запись уже подтверждена.';
      elsif item.command='cancel' and target.status::text='paid' then
        outcome:='paid_requires_review'; reply:='Для отмены оплаченной записи и проверки возврата обратитесь к администратору.';
      else
        if item.command='confirm' then
          perform public.confirm_booking(booking_id);
          if not exists(select 1 from public.bookings where id=booking_id and status::text in ('confirmed','paid')) then raise exception 'INBOX_TRANSITION_FAILED'; end if;
          outcome:='confirmed'; reply:='Запись подтверждена.';
        elsif item.command='cancel' then
          begin
            perform public.cancel_booking(booking_id);
            if not exists(select 1 from public.bookings where id=booking_id and status::text='cancelled') then raise exception 'INBOX_TRANSITION_FAILED'; end if;
            outcome:='cancelled'; reply:='Запись отменена.';
          exception when raise_exception then
            if sqlerrm='BOOKING_FINANCIAL_REVERSAL_REQUIRED' then
              outcome:='financial_reversal_required'; reply:='Для отмены этой записи требуется финансовая сверка. Обратитесь к администратору.';
            else raise; end if;
          end;
        else raise exception 'INBOX_INVALID_INPUT'; end if;
      end if;
    end if;
  end if;
  -- Booking transition, its notification trigger, and immutable command/reply receipt share one commit.
  update public.whatsapp_inbox set command_receipt=jsonb_build_object('outcome',outcome,'booking_id',booking_id,'completed_at',clock_timestamp()),
    reply_payload=jsonb_build_object('messaging_product','whatsapp','recipient_type','individual','to',substring(item.sender from 2),'type','text','text',jsonb_build_object('body',reply))
    where id=p_id returning * into item;
  return jsonb_build_object('outcome',outcome,'payload',item.reply_payload);
end;
$function$
;

-- signature: public.protect_profile_identity_columns()
CREATE OR REPLACE FUNCTION public.protect_profile_identity_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if current_user not in ('anon', 'authenticated') then
        return new;
    end if;

    if tg_op = 'INSERT' then
        new.whatsapp_phone := null;
        new.whatsapp_verified := false;
        new.telegram_id := null;
        new.telegram_username := null;
        new.telegram_photo_url := null;
        new.telegram_verified := false;
        new.yandex_id := null;
        new.yandex_username := null;
    else
        new.whatsapp_phone := old.whatsapp_phone;
        new.whatsapp_verified := old.whatsapp_verified;
        new.telegram_id := old.telegram_id;
        new.telegram_username := old.telegram_username;
        new.telegram_photo_url := old.telegram_photo_url;
        new.telegram_verified := old.telegram_verified;
        new.yandex_id := old.yandex_id;
        new.yandex_username := old.yandex_username;
    end if;

    return new;
end;
$function$
;

-- signature: public.prune_booking_notifications(integer)
CREATE OR REPLACE FUNCTION public.prune_booking_notifications(p_limit integer DEFAULT 1000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_count integer;
begin
    if p_limit is null or p_limit not between 1 and 5000 then raise exception 'INVALID_OUTBOX_PRUNE_LIMIT' using errcode='22023'; end if;
    with expired as (select id from public.booking_notification_outbox where
        (completed_at<now()-interval '30 days' or prepared_at<now()-interval '30 days')
        and payloads_pruned_at is null and (status<>'processing' or lease_until<=now())
        order by coalesce(prepared_at,completed_at) for update skip locked limit p_limit),
    deleted as (delete from public.booking_notification_deliveries d using expired e where d.event_id=e.id)
    update public.booking_notification_outbox o set payloads_pruned_at=now(),
        status=case when o.status in ('pending','processing') then 'failed' else o.status end,
        completed_at=coalesce(o.completed_at,now()),lease_token=null,lease_until=null
        from expired e where o.id=e.id;
    get diagnostics v_count=row_count;
    return v_count;
end;
$function$
;

-- signature: public.prune_whatsapp_inbox(integer)
CREATE OR REPLACE FUNCTION public.prune_whatsapp_inbox(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare affected integer;
begin
  perform public._require_whatsapp_inbox_service();
  if p_limit is null or p_limit not between 1 and 100 then raise exception 'INBOX_INVALID_INPUT'; end if;
  with old as (select id from public.whatsapp_inbox where pruned_at is null and (
      completed_at<clock_timestamp()-interval '30 days' or
      (created_at<clock_timestamp()-interval '30 days' and status in ('pending','processing') and (lease_until is null or lease_until<=clock_timestamp())))
    order by created_at for update skip locked limit p_limit)
  update public.whatsapp_inbox i set sender=null,message_type=null,message_text=null,command=null,booking_number=null,
    command_receipt=null,reply_payload=null,provider_reply_id=null,pruned_at=clock_timestamp(),
    status=case when i.status in ('pending','processing') then case when reply_started_at is not null then 'ambiguous' else 'expired' end else i.status end,
    last_error_code=case when i.status in ('pending','processing') then case when reply_started_at is not null then 'reply_outcome_unknown' else 'message_expired' end else i.last_error_code end,
    completed_at=coalesce(i.completed_at,clock_timestamp()),lease_token=null,lease_until=null
    from old where i.id=old.id;
  get diagnostics affected=row_count;
  return affected;
end;
$function$
;

-- signature: public.publish_staff_schedule(uuid,uuid,uuid,bigint,text,date,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.publish_staff_schedule(p_staff uuid, p_biz uuid, p_actor uuid, p_expected_revision bigint, p_kind text, p_from date, p_branch uuid, p_days jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st record; tz text; rev bigint; k text; conflicts jsonb; created_id uuid; weekday int;
begin
    if not public.schedule_actor_can_manage(p_actor,p_biz) then raise exception 'SCHEDULE_FORBIDDEN'; end if;
    -- Serializes competing publications and booking writes for this employee.
    select * into st from public.staff where id=p_staff and biz_id=p_biz for update;
    if not found or not st.is_active then raise exception 'SCHEDULE_NOT_FOUND'; end if;
    select coalesce(b.tz,'Asia/Bishkek') into tz from public.businesses b where b.id=p_biz;
    if p_from is null or p_from<(now() at time zone tz)::date or p_kind not in ('week','day')
        or p_kind is null or p_days is null or jsonb_typeof(p_days)<>'object' then raise exception 'SCHEDULE_INVALID'; end if;
    if not exists(select 1 from public.branches where id=p_branch and biz_id=p_biz and is_active)
        then raise exception 'SCHEDULE_INVALID_BRANCH'; end if;
    select coalesce(max(revision),0) into rev from public.staff_schedule_versions where staff_id=p_staff;
    if p_expected_revision is distinct from rev then raise exception 'SCHEDULE_STALE'; end if;
    if (select count(*) from jsonb_object_keys(p_days))<>(case when p_kind='week' then 7 else 1 end)
        then raise exception 'SCHEDULE_INVALID'; end if;
    foreach k in array (case when p_kind='week' then array['1','2','3','4','5','6','7'] else array['day'] end) loop
        perform public.schedule_validate_day(p_days->k);
        weekday := case when p_kind='day' then extract(dow from p_from)::int else k::int % 7 end;
        if exists(select 1 from jsonb_array_elements(p_days->k->'intervals') work where not exists(
            select 1 from public.branch_working_hours h cross join lateral jsonb_array_elements(h.intervals) bounds
            where h.biz_id=p_biz and h.branch_id=p_branch and h.day_of_week=weekday
                and bounds->>'start'<=work->>'start' and bounds->>'end'>=work->>'end'))
        then raise exception 'SCHEDULE_OUTSIDE_BRANCH_HOURS'; end if;
    end loop;
    -- Nested transaction: failed conflict preview rolls back the candidate version.
    begin
        insert into public.staff_schedule_versions(staff_id,biz_id,branch_id,kind,effective_from,days,revision,created_by)
        values(p_staff,p_biz,p_branch,p_kind,p_from,p_days,rev+1,p_actor) returning id into created_id;
        select jsonb_agg(jsonb_build_object('id',b.id,'start_at',b.start_at,'end_at',b.end_at)) into conflicts
        from public.bookings b where b.staff_id=p_staff and b.biz_id=p_biz
            and (b.status::text in ('confirmed','paid') or (b.status::text='hold' and b.expires_at>now()))
            and (b.start_at at time zone tz)::date>=p_from
            and (p_kind='week' or (b.start_at at time zone tz)::date=p_from)
            and not public.schedule_contains_booking(p_staff,b.branch_id,b.start_at,b.end_at);
        if conflicts is not null then raise exception 'SCHEDULE_BOOKING_CONFLICT'; end if;
    exception when raise_exception then
        if sqlerrm='SCHEDULE_BOOKING_CONFLICT' then
            return jsonb_build_object('ok',false,'error','SCHEDULE_BOOKING_CONFLICT','conflicts',conflicts);
        end if;
        raise;
    end;
    return jsonb_build_object('ok',true,'revision',rev+1,'id',created_id);
end;
$function$
;

-- signature: public.purge_expired_holds()
CREATE OR REPLACE FUNCTION public.purge_expired_holds()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update bookings
     set status='cancelled', expires_at = null
   where status='hold' and expires_at is not null and expires_at < now();
end $function$
;

-- signature: public.read_analytics_report_snapshot(date,date,uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.read_analytics_report_snapshot(p_date_from date, p_date_to date, p_biz_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid, p_kind text DEFAULT 'daily'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_result jsonb;
begin
    if p_date_from is null or p_date_to is null or p_date_to-p_date_from not between 0 and 365 or p_kind not in ('daily','hourly','global') then
        raise exception using errcode='22023',message='REPORT_SCOPE_OR_RANGE_INVALID';
    end if;
    if (p_kind='global' and (p_biz_id is not null or p_branch_id is not null)) or (p_kind<>'global' and p_biz_id is null) then
        raise exception using errcode='22023',message='REPORT_SCOPE_INVALID';
    end if;
    if p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id) then
        raise exception using errcode='42501',message='REPORT_SCOPE_INVALID';
    end if;
    if p_kind='global' then
        with selected as materialized (select * from public.business_daily_stats where date between p_date_from and p_date_to), days as (
            select date,count(distinct biz_id) as active_businesses,sum(home_views) as home_views,sum(business_page_views) as business_page_views,
                sum(booking_flow_starts) as booking_flow_starts,sum(bookings_created) as bookings_created,
                sum(bookings_confirmed_or_paid) as bookings_confirmed_or_paid,sum(promo_bookings) as promo_bookings,
                sum(promo_revenue) as promo_revenue,sum(total_revenue) as total_revenue from selected group by date
        ) select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(d) order by date) from days d),'[]'::jsonb),
            'activeBusinesses',(select count(distinct biz_id) from selected)) into v_result;
    elsif p_kind='daily' then
        if p_branch_id is not null then raise exception using errcode='22023',message='DAILY_BRANCH_BREAKDOWN_UNAVAILABLE'; end if;
        select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(d) order by date),'[]'::jsonb)) into v_result
        from public.business_daily_stats d where biz_id=p_biz_id and date between p_date_from and p_date_to;
    else
        -- Preserve per-branch points and their counts. Distinct clients/staff across branches
        -- cannot be recovered by adding preaggregated counts; do not claim those are unique.
        select jsonb_build_object('rows',coalesce(jsonb_agg(to_jsonb(h) order by date,hour,branch_id),'[]'::jsonb)) into v_result
        from public.business_hourly_load h where biz_id=p_biz_id and date between p_date_from and p_date_to and (p_branch_id is null or branch_id=p_branch_id);
    end if;
    return v_result;
end;
$function$
;

-- signature: public.read_booking_notification_deliveries(uuid,uuid)
CREATE OR REPLACE FUNCTION public.read_booking_notification_deliveries(p_event_id uuid, p_lease_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox; v_result jsonb;
begin
  select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
  if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp() then
    raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('delivery_key',d.delivery_key,'channel',d.channel,'payload',d.payload,
    'status',d.status,'sent_at',d.sent_at,'first_attempt_at',d.first_attempt_at,'last_error_code',d.last_error_code) order by d.delivery_key),'[]')
    into v_result from public.booking_notification_deliveries d where d.event_id=p_event_id;
  if jsonb_array_length(v_result)>200 then raise exception 'INVALID_OUTBOX_DELIVERIES'; end if;
  return v_result;
end;
$function$
;

-- signature: public.read_business_finance_calendar(uuid)
CREATE OR REPLACE FUNCTION public.read_business_finance_calendar(p_biz_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text:=public.finance_business_timezone(p_biz_id);
begin
    return jsonb_build_object('todayDate',(statement_timestamp() at time zone v_tz)::date,'timezone',v_tz);
end;
$function$
;

-- signature: public.read_cron_execution_health()
CREATE OR REPLACE FUNCTION public.read_cron_execution_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) from (
        select job,max(started_at) as last_started_at,max(completed_at) as last_completed_at,
            max(completed_at) filter(where outcome='succeeded') as last_success_at,
            max(completed_at) filter(where outcome='failed') as last_failure_at,
            min(started_at) filter(where outcome='running') as oldest_running_at,
            count(*) filter(where outcome='running') as running_count
        from public.cron_executions where started_at>=now()-interval '30 days' group by job
    ) s;
$function$
;

-- signature: public.read_finance_report_snapshot(uuid,date,date,uuid,uuid)
CREATE OR REPLACE FUNCTION public.read_finance_report_snapshot(p_biz_id uuid, p_date_from date, p_date_to date, p_staff_id uuid DEFAULT NULL::uuid, p_branch_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text;
begin
    if p_biz_id is null or p_date_from is null or p_date_to is null or p_date_to-p_date_from not between 0 and 365 then
        raise exception using errcode='22023',message='REPORT_SCOPE_OR_RANGE_INVALID';
    end if;
    if p_staff_id is not null and not exists(select 1 from public.staff where id=p_staff_id and biz_id=p_biz_id)
       or p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id) then
        raise exception using errcode='42501',message='REPORT_SCOPE_INVALID';
    end if;
    if exists(select 1 from public.staff_shifts sh left join public.staff st on st.id=sh.staff_id and st.biz_id=p_biz_id
        where sh.biz_id=p_biz_id and sh.shift_date between p_date_from and p_date_to
        and (p_staff_id is null or sh.staff_id=p_staff_id) and (p_branch_id is null or sh.branch_id=p_branch_id) and st.id is null) then
        raise exception using errcode='23514',message='REPORT_STAFF_REFERENCE_INVALID';
    end if;
    v_tz:=public.finance_business_timezone(p_biz_id);
    return (with selected_shifts as materialized (
    select s.* from public.staff_shifts s
    where s.biz_id=p_biz_id and s.shift_date between p_date_from and p_date_to
      and (p_staff_id is null or s.staff_id=p_staff_id)
      and (p_branch_id is null or s.branch_id=p_branch_id)
), selected_staff as materialized (
    select s.id,s.full_name,s.is_active,s.hourly_rate,s.percent_master,s.percent_salon,s.branch_id
    from public.staff s where s.biz_id=p_biz_id and (p_staff_id is null or s.id=p_staff_id)
      and (p_branch_id is null or s.branch_id=p_branch_id or exists(select 1 from selected_shifts sh where sh.staff_id=s.id))
), closed as (
    select staff_id,count(*) as closed_shifts,coalesce(sum(total_amount),0) as total_amount,
        coalesce(sum(master_share),0) as total_master,coalesce(sum(salon_share),0) as total_salon,
        coalesce(sum(consumables_amount),0) as total_consumables,coalesce(sum(late_minutes),0) as total_late_minutes
    from selected_shifts where status='closed' group by staff_id
), details as (
    select s.*,v_tz as timezone,
        s.shift_date::timestamp at time zone v_tz as day_start,
        (s.shift_date+1)::timestamp at time zone v_tz as day_end,
        extract(epoch from ((s.shift_date+1)::timestamp at time zone v_tz)-(s.shift_date::timestamp at time zone v_tz))/3600 as day_hours,
        jsonb_build_object('hourly_rate',st.hourly_rate,'percent_master',st.percent_master,'percent_salon',st.percent_salon) as staff,
        coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at,i.id) from public.staff_shift_items i where i.shift_id=s.id),'[]'::jsonb) as items
    from selected_shifts s join selected_staff st on st.id=s.staff_id
    where p_staff_id is not null or s.status='open'
)
select jsonb_build_object(
    'branches',coalesce((select jsonb_agg(jsonb_build_object('id',b.id,'name',b.name) order by b.name,b.id) from public.branches b where b.biz_id=p_biz_id),'[]'::jsonb),
    'staff',coalesce((select jsonb_agg(to_jsonb(st) order by st.full_name,st.id) from selected_staff st),'[]'::jsonb),
    'closedStats',coalesce((select jsonb_agg(to_jsonb(c) order by c.staff_id) from closed c),'[]'::jsonb),
    'shifts',coalesce((select jsonb_agg(to_jsonb(d) order by d.shift_date desc,d.id) from details d),'[]'::jsonb)
));
end;
$function$
;

-- signature: public.read_platform_admin_states(uuid,uuid[])
CREATE OR REPLACE FUNCTION public.read_platform_admin_states(p_actor_id uuid, p_target_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result jsonb;
begin
  if coalesce(nullif(current_setting('role',true),'none'),session_user) not in ('service_role','postgres','supabase_admin') then
    raise exception using errcode='42501',message='PLATFORM_ADMIN_SERVICE_ONLY';
  end if;
  if p_actor_id is null or p_target_ids is null or cardinality(p_target_ids)>200 or array_position(p_target_ids,null) is not null then
    raise exception using errcode='22023',message='PLATFORM_ADMIN_INVALID_INPUT';
  end if;
  if not exists(select 1 from auth.users where id=p_actor_id) or not public.finance_is_platform_admin(p_actor_id) then
    raise exception using errcode='42501',message='PLATFORM_ADMIN_FORBIDDEN';
  end if;
  select coalesce(jsonb_object_agg(target::text,public.finance_is_platform_admin(target)),'{}'::jsonb)
    into result from (select distinct unnest(p_target_ids) as target) ids;
  return result;
end;
$function$
;

-- signature: public.read_promotion_analytics_snapshot(uuid,date,date,uuid,text)
CREATE OR REPLACE FUNCTION public.read_promotion_analytics_snapshot(p_biz_id uuid, p_date_from date, p_date_to date, p_branch_id uuid DEFAULT NULL::uuid, p_default_tz text DEFAULT 'Asia/Bishkek'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text; v_result jsonb;
begin
    if p_biz_id is null or p_date_from is null or p_date_to is null or p_date_to-p_date_from not between 0 and 365 then
        raise exception using errcode='22023',message='REPORT_SCOPE_OR_RANGE_INVALID';
    end if;
    select coalesce(nullif(btrim(tz),''),p_default_tz) into v_tz from public.businesses where id=p_biz_id;
    if v_tz is null or (p_branch_id is not null and not exists(select 1 from public.branches where id=p_branch_id and biz_id=p_biz_id)) then
        raise exception using errcode='42501',message='REPORT_SCOPE_INVALID';
    end if;
    with amounts as materialized (
        select (k.start_at at time zone v_tz)::date as date,nullif(k.promotion_applied->>'promotion_type','') as promotion_type,
            case when coalesce(k.promotion_applied->>'promotion_type','')<>'' then coalesce((k.promotion_applied->>'final_amount')::numeric,0)
                when s.price_from is not null and s.price_to is not null then (s.price_from::numeric+s.price_to::numeric)/2
                else coalesce(s.price_from,s.price_to,0)::numeric end as amount,
            case when coalesce(k.promotion_applied->>'promotion_type','')<>'' then greatest(0,coalesce((k.promotion_applied->>'original_amount')::numeric,0)-coalesce((k.promotion_applied->>'final_amount')::numeric,0)) else 0 end as discount
        from public.bookings k left join public.services s on s.id=k.service_id
        where k.biz_id=p_biz_id and (p_branch_id is null or k.branch_id=p_branch_id) and k.status in ('confirmed','paid')
            and k.start_at>=p_date_from::timestamp at time zone v_tz and k.start_at<(p_date_to+1)::timestamp at time zone v_tz
    ), days as (
        select date,count(*) filter(where promotion_type is not null) as "promoBookings",
            coalesce(sum(amount) filter(where promotion_type is not null),0) as "promoRevenue",sum(amount) as "totalRevenue" from amounts group by date
    ), types as (
        select promotion_type as "promotionType",count(*) as bookings,sum(amount) as revenue,sum(discount) as "discountGiven"
        from amounts where promotion_type is not null group by promotion_type
    ) select jsonb_build_object('summary',jsonb_build_object('promoBookings',(select count(*) from amounts where promotion_type is not null),
        'promoRevenue',coalesce((select sum(amount) from amounts where promotion_type is not null),0),'totalRevenue',coalesce((select sum(amount) from amounts),0)),
        'byDay',coalesce((select jsonb_agg(to_jsonb(d) order by date) from days d),'[]'::jsonb),
        'byType',coalesce((select jsonb_agg(to_jsonb(t) order by "promotionType") from types t),'[]'::jsonb)) into v_result;
    if v_result->'summary'->>'totalRevenue' in ('NaN','Infinity','-Infinity') or v_result->'summary'->>'promoRevenue' in ('NaN','Infinity','-Infinity')
        or exists(select 1 from jsonb_array_elements(v_result->'byType') t where t->>'discountGiven' in ('NaN','Infinity','-Infinity')) then
        raise exception using errcode='22023',message='ANALYTICS_AMOUNT_INVALID';
    end if;
    return v_result;
end;
$function$
;

-- signature: public.read_staff_finance_calendar(uuid,uuid,date,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.read_staff_finance_calendar(p_biz_id uuid, p_staff_id uuid, p_date date DEFAULT NULL::date, p_instant timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_tz text; v_date date; v_start timestamptz; v_end timestamptz;
begin
    perform public.assert_finance_access(p_biz_id,p_staff_id);
    v_tz:=public.finance_business_timezone(p_biz_id);
    v_date:=coalesce(p_date,(coalesce(p_instant,statement_timestamp()) at time zone v_tz)::date);
    v_start:=v_date::timestamp at time zone v_tz;
    v_end:=(v_date+1)::timestamp at time zone v_tz;
    return jsonb_build_object('date',v_date,'todayDate',(statement_timestamp() at time zone v_tz)::date,
        'timezone',v_tz,'dayStart',v_start,'dayEnd',v_end,'dayHours',extract(epoch from v_end-v_start)/3600);
end;
$function$
;

-- signature: public.read_staff_finance_history(uuid,uuid,date,date)
CREATE OR REPLACE FUNCTION public.read_staff_finance_history(p_biz_id uuid, p_staff_id uuid, p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if p_biz_id is null or p_staff_id is null or (p_date_from is not null and p_date_to is not null and p_date_from>p_date_to) then
        raise exception using errcode='22023',message='REPORT_SCOPE_OR_RANGE_INVALID';
    end if;
    if not exists(select 1 from public.staff where id=p_staff_id and biz_id=p_biz_id) then
        raise exception using errcode='42501',message='REPORT_SCOPE_INVALID';
    end if;
    return coalesce((select jsonb_agg(to_jsonb(s) order by shift_date desc,id) from (
        select id,shift_date,status,total_amount,master_share,salon_share,late_minutes,guaranteed_amount,topup_amount
        from public.staff_shifts where biz_id=p_biz_id and staff_id=p_staff_id
            and (p_date_from is null or shift_date>=p_date_from) and (p_date_to is null or shift_date<=p_date_to)
    ) s),'[]'::jsonb);
end;
$function$
;

-- signature: public.read_staff_schedule_draft(uuid,uuid,date,text)
CREATE OR REPLACE FUNCTION public.read_staff_schedule_draft(p_staff uuid, p_biz uuid, p_day date, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st record; v record; result jsonb; days jsonb; branch uuid; source text := 'unconfigured';
begin
    select * into st from public.staff where id=p_staff and biz_id=p_biz and is_active;
    if not found then raise exception 'SCHEDULE_NOT_FOUND'; end if;
    if p_day is null or p_kind is null or p_kind not in ('week','day') then raise exception 'SCHEDULE_INVALID'; end if;
    branch := st.branch_id;
    if p_kind='day' then
        result := public.schedule_effective_day(p_staff,p_day);
        branch := (result->>'branch_id')::uuid;
        days := jsonb_build_object('day',jsonb_build_object('intervals',result->'intervals','breaks',result->'breaks'));
        source := result->>'source';
    else
        select * into v from public.staff_schedule_versions where staff_id=p_staff and kind='week'
            and effective_from<=p_day order by effective_from desc,revision desc limit 1;
        if found then days:=v.days; branch:=v.branch_id; source:='week';
        else
            select jsonb_object_agg(k::text,jsonb_build_object('intervals',coalesce(w.intervals,'[]'::jsonb),
                'breaks',coalesce(w.breaks,'[]'::jsonb))) into days
                from generate_series(1,7) k left join public.working_hours w
                on w.staff_id=p_staff and w.biz_id=p_biz and w.day_of_week=k%7;
            if exists(select 1 from public.working_hours where staff_id=p_staff and biz_id=p_biz) then source:='legacy'; end if;
        end if;
    end if;
    return jsonb_build_object('days',days,'branchId',branch,'source',source,
        'revision',(select coalesce(max(revision),0) from public.staff_schedule_versions where staff_id=p_staff));
end;
$function$
;

-- signature: public.read_staff_schedule(uuid,uuid,date,date)
CREATE OR REPLACE FUNCTION public.read_staff_schedule(p_staff uuid, p_biz uuid, p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare tz text; result jsonb;
begin
    if p_from is null or p_to is null or p_to<p_from or p_to-p_from>62 then raise exception 'SCHEDULE_INVALID'; end if;
    select coalesce(b.tz,'Asia/Bishkek') into tz from public.staff s join public.businesses b on b.id=s.biz_id
        where s.id=p_staff and s.biz_id=p_biz;
    if not found then raise exception 'SCHEDULE_NOT_FOUND'; end if;
    select jsonb_agg(public.schedule_effective_day(p_staff,p_from+i) order by i) into result
        from generate_series(0,p_to-p_from) i;
    return jsonb_build_object('revision',(select coalesce(max(revision),0) from public.staff_schedule_versions where staff_id=p_staff),
        'timezone',tz,'today',(now() at time zone tz)::date,'days',result);
end;
$function$
;

-- signature: public.read_staff_shift_adjustment_snapshot(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.read_staff_shift_adjustment_snapshot(p_shift_id uuid, p_biz_id uuid, p_actor_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_shift public.staff_shifts%rowtype; v_tz text;
    v_role text:=coalesce(nullif(current_setting('role',true),'none'),session_user);
begin
    if v_role not in ('service_role','postgres','supabase_admin') or p_actor_id is null
        or not public.finance_can_manage_business(p_actor_id,p_biz_id) then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    select * into v_shift from public.staff_shifts where id=p_shift_id and biz_id=p_biz_id;
    if not found then raise exception using errcode='P0002',message='SHIFT_NOT_FOUND'; end if;
    v_tz:=public.finance_business_timezone(p_biz_id);
    return jsonb_build_object('shift',to_jsonb(v_shift),'timezone',v_tz,'dayHours',
        extract(epoch from ((v_shift.shift_date+1)::timestamp at time zone v_tz)-(v_shift.shift_date::timestamp at time zone v_tz))/3600);
end;
$function$
;

-- signature: public.read_staff_shift_close_snapshot(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.read_staff_shift_close_snapshot(p_biz_id uuid, p_staff_id uuid, p_shift_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_result jsonb;
begin
    if p_biz_id is null or p_staff_id is null or p_shift_id is null then raise exception using errcode='22023',message='FINANCE_SCOPE_REQUIRED'; end if;
    select jsonb_build_object('shift',to_jsonb(sh),'staff',jsonb_build_object('percent_master',st.percent_master,'percent_salon',st.percent_salon,'hourly_rate',st.hourly_rate),
        'timezone',public.finance_business_timezone(sh.biz_id),'dayStart',sh.shift_date::timestamp at time zone public.finance_business_timezone(sh.biz_id),
        'dayHours',extract(epoch from (((sh.shift_date+1)::timestamp at time zone public.finance_business_timezone(sh.biz_id))-(sh.shift_date::timestamp at time zone public.finance_business_timezone(sh.biz_id))))/3600,'closeBoundary',(sh.shift_date+1)::timestamp at time zone public.finance_business_timezone(sh.biz_id),
        'items',coalesce((select jsonb_agg(to_jsonb(i) order by i.id) from public.staff_shift_items i where i.shift_id=sh.id),'[]'::jsonb)) into v_result
    from public.staff_shifts sh join public.staff st on st.id=sh.staff_id and st.biz_id=sh.biz_id
    where sh.id=p_shift_id and sh.staff_id=p_staff_id and sh.biz_id=p_biz_id;
    if v_result is null then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    return v_result;
end;
$function$
;

-- signature: public.read_staff_shift_snapshot(uuid,uuid,date)
CREATE OR REPLACE FUNCTION public.read_staff_shift_snapshot(p_biz_id uuid, p_staff_id uuid, p_shift_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if p_biz_id is null or p_staff_id is null or p_shift_date is null then raise exception using errcode='22023',message='FINANCE_SCOPE_REQUIRED'; end if;
    return (select to_jsonb(sh)||jsonb_build_object('staff_shift_items',coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc,i.id)
        from public.staff_shift_items i where i.shift_id=sh.id),'[]'::jsonb))
        from public.staff_shifts sh where sh.biz_id=p_biz_id and sh.staff_id=p_staff_id and sh.shift_date=p_shift_date);
end;
$function$
;

-- signature: public.read_staff_work_locations(uuid,date,date)
CREATE OR REPLACE FUNCTION public.read_staff_work_locations(p_biz uuid, p_from date, p_to date)
 RETURNS TABLE(staff_id uuid, branch_id uuid, date_on date)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>62 then raise exception 'SCHEDULE_INVALID'; end if;
 return query select s.id,(d.value->>'branch_id')::uuid,p_from+i
 from public.staff s cross join generate_series(0,p_to-p_from) i
 cross join lateral (select public.schedule_effective_day(s.id,p_from+i) value) d
 where s.biz_id=p_biz and s.is_active and jsonb_array_length(d.value->'intervals')>0;
end;
$function$
;

-- signature: public.read_user_lifecycle(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.read_user_lifecycle(p_actor_id uuid, p_user_id uuid, p_command_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
  if coalesce(nullif(current_setting('role',true),'none'),session_user) not in ('service_role','postgres','supabase_admin')
    or not public.finance_is_platform_admin(p_actor_id)
    or not exists(select 1 from auth.users where id=p_actor_id and coalesce(banned_until,now())<=now())
    or exists(select 1 from public.user_suspensions where user_id=p_actor_id) then
    raise exception 'USER_LIFECYCLE_FORBIDDEN' using errcode='42501';
  end if;
  return coalesce((select completed from public.user_lifecycle_commands where user_id=p_user_id and command_id=p_command_id),false);
end;
$function$
;

-- signature: public.recalculate_business_daily_stats(date,text)
CREATE OR REPLACE FUNCTION public.recalculate_business_daily_stats(p_date date, p_default_tz text DEFAULT 'Asia/Bishkek'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_rows jsonb; v_updated integer;
begin
    if p_date is null then raise exception using errcode='22023',message='ANALYTICS_DATE_REQUIRED'; end if;
    perform pg_advisory_xact_lock(7101201,p_date-date '2000-01-01');
    with bounds as materialized (
        select b.id, p_date::timestamp at time zone coalesce(nullif(btrim(b.tz),''),p_default_tz) as starts_at,
            (p_date+1)::timestamp at time zone coalesce(nullif(btrim(b.tz),''),p_default_tz) as ends_at
        from public.businesses b
    ), events as (
        select b.id as biz_id,
            count(*) filter(where e.event_type='home_view') as home_views,
            count(*) filter(where e.event_type='business_page_view') as business_page_views,
            count(*) filter(where e.event_type='booking_flow_start') as booking_flow_starts,
            count(*) filter(where e.event_type='booking_created') as bookings_created,
            count(*) filter(where e.event_type='booking_confirmed_or_paid') as bookings_confirmed_or_paid
        from bounds b join public.analytics_events e on e.biz_id=b.id and e.created_at>=b.starts_at and e.created_at<b.ends_at
        group by b.id
    ), amounts as (
        select b.id as biz_id, coalesce(k.promotion_applied->>'promotion_type','')<>'' as promoted,
            case when coalesce(k.promotion_applied->>'promotion_type','')<>''
                then coalesce((k.promotion_applied->>'final_amount')::numeric,0)
                when s.price_from is not null and s.price_to is not null then (s.price_from::numeric+s.price_to::numeric)/2
                else coalesce(s.price_from,s.price_to,0)::numeric end as amount
        from bounds b join public.bookings k on k.biz_id=b.id and k.start_at>=b.starts_at and k.start_at<b.ends_at
            and k.status in ('confirmed','paid')
        left join public.services s on s.id=k.service_id
    ), revenue as (
        select biz_id,count(*) filter(where promoted) as promo_bookings,
            coalesce(sum(amount) filter(where promoted),0) as promo_revenue,coalesce(sum(amount),0) as total_revenue
        from amounts group by biz_id
    ), rows as (
        select coalesce(e.biz_id,r.biz_id) as biz_id,p_date as date,
            coalesce(e.home_views,0) as home_views,coalesce(e.business_page_views,0) as business_page_views,
            coalesce(e.booking_flow_starts,0) as booking_flow_starts,coalesce(e.bookings_created,0) as bookings_created,
            coalesce(e.bookings_confirmed_or_paid,0) as bookings_confirmed_or_paid,
            coalesce(r.promo_bookings,0) as promo_bookings,coalesce(r.promo_revenue,0) as promo_revenue,coalesce(r.total_revenue,0) as total_revenue
        from events e full join revenue r on r.biz_id=e.biz_id
    ) select coalesce(jsonb_agg(to_jsonb(rows)),'[]'::jsonb) into v_rows from rows;
    -- Invalid numeric metadata must fail the whole replacement, not save NaN/Infinity.
    if exists(select 1 from jsonb_array_elements(v_rows) r where r->>'total_revenue' in ('NaN','Infinity','-Infinity') or r->>'promo_revenue' in ('NaN','Infinity','-Infinity')) then
        raise exception using errcode='22023',message='ANALYTICS_AMOUNT_INVALID';
    end if;
    insert into public.business_daily_stats(biz_id,date,home_views,business_page_views,booking_flow_starts,
        bookings_created,bookings_confirmed_or_paid,promo_bookings,promo_revenue,total_revenue,updated_at)
    select biz_id,date,home_views,business_page_views,booking_flow_starts,bookings_created,bookings_confirmed_or_paid,
        promo_bookings,promo_revenue,total_revenue,now()
    from jsonb_to_recordset(v_rows) as r(biz_id uuid,date date,home_views integer,business_page_views integer,
        booking_flow_starts integer,bookings_created integer,bookings_confirmed_or_paid integer,promo_bookings integer,
        promo_revenue numeric,total_revenue numeric)
    on conflict(biz_id,date) do update set home_views=excluded.home_views,business_page_views=excluded.business_page_views,
        booking_flow_starts=excluded.booking_flow_starts,bookings_created=excluded.bookings_created,
        bookings_confirmed_or_paid=excluded.bookings_confirmed_or_paid,promo_bookings=excluded.promo_bookings,
        promo_revenue=excluded.promo_revenue,total_revenue=excluded.total_revenue,updated_at=excluded.updated_at;
    get diagnostics v_updated=row_count;
    delete from public.business_daily_stats s where s.date=p_date and not exists(
        select 1 from jsonb_array_elements(v_rows) r where (r->>'biz_id')::uuid=s.biz_id);
    return jsonb_build_object('date',p_date,'updated',v_updated);
end;
$function$
;

-- signature: public.recalculate_business_hourly_load(date,text)
CREATE OR REPLACE FUNCTION public.recalculate_business_hourly_load(p_date date, p_default_tz text DEFAULT 'Asia/Bishkek'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_rows jsonb; v_updated integer;
begin
    if p_date is null then raise exception using errcode='22023',message='ANALYTICS_DATE_REQUIRED'; end if;
    perform pg_advisory_xact_lock(7101202,p_date-date '2000-01-01');
    with bounds as materialized (
        select b.id,coalesce(nullif(btrim(b.tz),''),p_default_tz) as tz,
            p_date::timestamp at time zone coalesce(nullif(btrim(b.tz),''),p_default_tz) as starts_at,
            (p_date+1)::timestamp at time zone coalesce(nullif(btrim(b.tz),''),p_default_tz) as ends_at
        from public.businesses b
    ), rows as (
        select b.id as biz_id,k.branch_id,p_date as date,extract(hour from k.start_at at time zone b.tz)::integer as hour,
            count(*) as bookings_count,count(*) filter(where coalesce(k.promotion_applied->>'promotion_type','')<>'') as promo_bookings_count,
            nullif(count(distinct k.staff_id),0) as staff_count,nullif(count(distinct k.client_id),0) as unique_clients_count
        from bounds b join public.bookings k on k.biz_id=b.id and k.start_at>=b.starts_at and k.start_at<b.ends_at
            and k.status in ('confirmed','paid') and k.branch_id is not null
        group by b.id,k.branch_id,extract(hour from k.start_at at time zone b.tz)
    ) select coalesce(jsonb_agg(to_jsonb(rows)),'[]'::jsonb) into v_rows from rows;
    insert into public.business_hourly_load(biz_id,branch_id,date,hour,bookings_count,promo_bookings_count,staff_count,unique_clients_count,updated_at)
    select biz_id,branch_id,date,hour,bookings_count,promo_bookings_count,staff_count,unique_clients_count,now()
    from jsonb_to_recordset(v_rows) as r(biz_id uuid,branch_id uuid,date date,hour integer,bookings_count integer,
        promo_bookings_count integer,staff_count integer,unique_clients_count integer)
    on conflict(biz_id,branch_id,date,hour) do update set bookings_count=excluded.bookings_count,
        promo_bookings_count=excluded.promo_bookings_count,staff_count=excluded.staff_count,
        unique_clients_count=excluded.unique_clients_count,updated_at=excluded.updated_at;
    get diagnostics v_updated=row_count;
    delete from public.business_hourly_load s where s.date=p_date and not exists(select 1 from jsonb_array_elements(v_rows) r
        where (r->>'biz_id')::uuid=s.biz_id and (r->>'branch_id')::uuid=s.branch_id and (r->>'hour')::integer=s.hour);
    return jsonb_build_object('date',p_date,'updated',v_updated);
end;
$function$
;

-- signature: public.recalculate_ratings_for_date_range(date,date)
CREATE OR REPLACE FUNCTION public.recalculate_ratings_for_date_range(p_start_date date, p_end_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
    v_current_date date;
    r_staff record;
    r_branch record;
    r_biz record;
begin
    raise notice 'Initializing ratings from % to %', p_start_date, p_end_date;
    
    -- Пересчитываем метрики за каждый день в диапазоне
    v_current_date := p_start_date;
    while v_current_date <= p_end_date loop
        raise notice 'Processing date: %', v_current_date;
        
        -- 1. Пересчитываем ежедневные метрики для всех сотрудников за эту дату
        for r_staff in select id, biz_id, branch_id from public.staff loop
            begin
                perform public.calculate_staff_day_metrics(r_staff.id, v_current_date);
            exception when others then
                raise notice 'Error calculating staff metrics for staff_id=%, date=%: %', r_staff.id, v_current_date, SQLERRM;
            end;
        end loop;

        -- 2. Пересчитываем ежедневные метрики для всех филиалов за эту дату
        for r_branch in select id, biz_id from public.branches loop
            begin
                perform public.calculate_branch_day_metrics(r_branch.id, v_current_date);
            exception when others then
                raise notice 'Error calculating branch metrics for branch_id=%, date=%: %', r_branch.id, v_current_date, SQLERRM;
            end;
        end loop;

        -- 3. Пересчитываем ежедневные метрики для всех бизнесов за эту дату
        for r_biz in select id from public.businesses loop
            begin
                perform public.calculate_biz_day_metrics(r_biz.id, v_current_date);
            exception when others then
                raise notice 'Error calculating biz metrics for biz_id=%, date=%: %', r_biz.id, v_current_date, SQLERRM;
            end;
        end loop;
        
        v_current_date := v_current_date + interval '1 day';
    end loop;
    
    raise notice 'Finished processing date range';
end;
$function$
;

-- signature: public.recalculate_ratings_for_date(date)
CREATE OR REPLACE FUNCTION public.recalculate_ratings_for_date(p_date date DEFAULT (CURRENT_DATE - '1 day'::interval))
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_staff record;
    v_branch record;
    v_biz record;
begin
    -- Пересчитываем метрики для всех активных сотрудников за указанную дату
    for v_staff in
        select id from public.staff where is_active = true
    loop
        begin
            perform public.calculate_staff_day_metrics(v_staff.id, p_date);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_staff.id, 'staff', p_date, SQLERRM);
            raise warning 'Error calculating metrics for staff %: %', v_staff.id, sqlerrm;
        end;
    end loop;

    for v_branch in
        select id from public.branches where is_active = true
    loop
        begin
            perform public.calculate_branch_day_metrics(v_branch.id, p_date);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_branch.id, 'branch', p_date, SQLERRM);
            raise warning 'Error calculating metrics for branch %: %', v_branch.id, sqlerrm;
        end;
    end loop;

    for v_biz in
        select id from public.businesses where is_approved = true
    loop
        begin
            perform public.calculate_biz_day_metrics(v_biz.id, p_date);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_biz.id, 'business', p_date, SQLERRM);
            raise warning 'Error calculating metrics for biz %: %', v_biz.id, sqlerrm;
        end;
    end loop;

    -- Пересчитываем агрегированные рейтинги
    for v_staff in
        select id from public.staff where is_active = true
    loop
        begin
            perform public.calculate_staff_rating(v_staff.id);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_staff.id, 'staff', p_date, 'aggregate: ' || SQLERRM);
            raise warning 'Error calculating rating for staff %: %', v_staff.id, sqlerrm;
        end;
    end loop;

    for v_branch in
        select id from public.branches where is_active = true
    loop
        begin
            perform public.calculate_branch_rating(v_branch.id);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_branch.id, 'branch', p_date, 'aggregate: ' || SQLERRM);
            raise warning 'Error calculating rating for branch %: %', v_branch.id, sqlerrm;
        end;
    end loop;

    for v_biz in
        select id from public.businesses where is_approved = true
    loop
        begin
            perform public.calculate_biz_rating(v_biz.id);
        exception when others then
            insert into public.rating_recalc_errors (entity_id, entity_type, metric_date, error_message)
            values (v_biz.id, 'business', p_date, 'aggregate: ' || SQLERRM);
            raise warning 'Error calculating rating for biz %: %', v_biz.id, sqlerrm;
        end;
    end loop;
end;
$function$
;

-- signature: public.receive_whatsapp_inbox(text,jsonb)
CREATE OR REPLACE FUNCTION public.receive_whatsapp_inbox(p_receiver text, p_messages jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare m jsonb; existing public.whatsapp_inbox; inserted_count integer:=0; legacy boolean; stamp timestamptz;
begin
  perform public._require_whatsapp_inbox_service();
  if p_receiver is null or p_receiver !~ '^[0-9]{1,32}$' or p_messages is null
     or jsonb_typeof(p_messages)<>'array' or jsonb_array_length(p_messages)>100 or octet_length(p_messages::text)>524288 then
    raise exception 'INBOX_INVALID_INPUT';
  end if;
  for m in select value from jsonb_array_elements(p_messages) loop
    if jsonb_typeof(m)<>'object' or m->>'receiver' is distinct from p_receiver
      or coalesce(length(m->>'message_id'),0) not between 1 and 512
      or coalesce(m->>'sender','') !~ '^\+[0-9]{7,15}$'
      or coalesce(m->>'payload_hash','') !~ '^[a-f0-9]{64}$'
      or coalesce(m->>'message_type','') !~ '^[a-z_]{1,32}$'
      or m->>'text' is null or length(m->>'text')>4096
      or coalesce(m->>'command','') not in ('confirm','cancel','remind','help','booking_info','media')
      or m->>'provider_timestamp' is null
      or (m->>'booking_number' is not null and (m->>'booking_number') !~ '^[0-9]{1,6}$') then
      raise exception 'INBOX_INVALID_INPUT';
    end if;
    stamp:=(m->>'provider_timestamp')::timestamptz;
    if not isfinite(stamp) or stamp>clock_timestamp()+interval '5 minutes' then raise exception 'INBOX_INVALID_INPUT'; end if;
    -- Pre-existing rows may already have performed a command or sent a reply even when processed=false.
    select exists(select 1 from public.whatsapp_messages where whatsapp_message_id=m->>'message_id') into legacy;
    insert into public.whatsapp_inbox(receiver,message_id,payload_hash,provider_timestamp,sender,message_type,message_text,command,booking_number,status,completed_at,last_error_code)
    values(p_receiver,m->>'message_id',m->>'payload_hash',stamp,m->>'sender',m->>'message_type',m->>'text',m->>'command',(m->>'booking_number')::integer,
      case when legacy then 'legacy_manual' when stamp<clock_timestamp()-interval '24 hours' then 'expired' else 'pending' end,
      case when legacy or stamp<clock_timestamp()-interval '24 hours' then clock_timestamp() end,
      case when legacy then 'legacy_outcome_unknown' when stamp<clock_timestamp()-interval '24 hours' then 'message_expired' end)
    on conflict(receiver,message_id) do nothing;
    if found then inserted_count:=inserted_count+1; end if;
    select * into strict existing from public.whatsapp_inbox where receiver=p_receiver and message_id=m->>'message_id';
    if existing.payload_hash is distinct from m->>'payload_hash' or existing.provider_timestamp is distinct from stamp then
      raise exception 'INBOX_PAYLOAD_CONFLICT';
    end if;
  end loop;
  return inserted_count;
end;
$function$
;

-- signature: public.record_booking_notification_delivery(uuid,uuid,text,text)
CREATE OR REPLACE FUNCTION public.record_booking_notification_delivery(p_event_id uuid, p_lease_token uuid, p_delivery_key text, p_provider_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_event public.booking_notification_outbox;
begin
    select * into v_event from public.booking_notification_outbox where id=p_event_id for update;
    if not found or v_event.status<>'processing' or v_event.lease_token is distinct from p_lease_token or v_event.lease_until<=clock_timestamp() then
        raise exception 'OUTBOX_LEASE_LOST' using errcode='40001';
    end if;
    update public.booking_notification_deliveries set status='sent',sent_at=coalesce(sent_at,now()),provider_id=coalesce(provider_id,left(p_provider_id,200))
        where event_id=p_event_id and delivery_key=p_delivery_key and status in ('sending','sent');
    if not found then raise exception 'OUTBOX_DELIVERY_NOT_FOUND' using errcode='P0002'; end if;
end;
$function$
;

-- signature: public.record_whatsapp_inbox_reply(uuid,uuid,text)
CREATE OR REPLACE FUNCTION public.record_whatsapp_inbox_reply(p_id uuid, p_token uuid, p_provider_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare item public.whatsapp_inbox;
begin
  item:=public._locked_whatsapp_inbox(p_id,p_token);
  if item.reply_started_at is null or p_provider_id is null or length(p_provider_id) not between 1 and 512 then raise exception 'INBOX_INVALID_INPUT'; end if;
  update public.whatsapp_inbox set status='sent',provider_reply_id=p_provider_id,completed_at=clock_timestamp(),lease_token=null,lease_until=null,last_error_code=null where id=p_id;
end;
$function$
;

-- signature: public.register_whatsapp_mobile_otp_failure(uuid)
CREATE OR REPLACE FUNCTION public.register_whatsapp_mobile_otp_failure(p_attempt_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare failures integer;
begin
    update public.whatsapp_otp_codes
       set failed_attempts = coalesce(failed_attempts, 0) + 1,
           status = case when coalesce(failed_attempts, 0) + 1 >= 5 then 'failed' else 'pending' end,
           locked_until = case when coalesce(failed_attempts, 0) + 1 >= 5 then now() + interval '10 minutes' else locked_until end
     where id = p_attempt_id and used_at is null and consumed_at is null
       and status = 'pending' and expires_at > now() and coalesce(failed_attempts, 0) < 5
     returning failed_attempts into failures;
    return coalesce(failures, 5);
end $function$
;

-- signature: public.reject_application_with_policy(text,uuid,uuid,text,integer)
CREATE OR REPLACE FUNCTION public.reject_application_with_policy(p_application_kind text, p_application_id uuid, p_reviewer_user_id uuid, p_reason text DEFAULT NULL::text, p_block_days integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_user_id uuid;
    v_phone text;
    v_biz_id uuid;
    v_role text;
    v_blocked_until timestamptz;
begin
    if p_block_days < 0 or p_block_days > 365 then
        raise exception using errcode = '22023', message = 'invalid block duration';
    end if;

    if p_application_kind = 'business_registration' then
        update public.business_registration_applications
           set status = 'rejected', reviewed_at = now(), reviewed_by = p_reviewer_user_id,
               review_note = nullif(btrim(p_reason), ''), updated_at = now()
         where id = p_application_id and status in ('new', 'contacted')
         returning applicant_user_id, phone into v_user_id, v_phone;
        if not found then return false; end if;
    elsif p_application_kind in ('owner', 'staff') then
        update public.business_role_applications
           set status = 'rejected', reviewed_at = now(), reviewed_by = p_reviewer_user_id,
               review_note = nullif(btrim(p_reason), ''), updated_at = now()
         where id = p_application_id and status = 'pending' and requested_role = p_application_kind
         returning applicant_user_id, biz_id, requested_role into v_user_id, v_biz_id, v_role;
        if not found then return false; end if;
    else
        raise exception using errcode = '22023', message = 'invalid application kind';
    end if;

    if p_block_days > 0 then
        v_blocked_until := now() + make_interval(days => p_block_days);
        insert into public.application_submission_blocks(
            application_kind, subject_user_id, subject_phone, biz_id,
            blocked_until, reason, created_by
        ) values (
            p_application_kind, v_user_id, case when v_user_id is null then v_phone else null end,
            v_biz_id, v_blocked_until, nullif(btrim(p_reason), ''), p_reviewer_user_id
        );
    end if;

    insert into public.application_moderation_actions(
        application_kind, application_id, action, actor_user_id,
        target_user_id, biz_id, reason, blocked_until
    ) values (
        p_application_kind, p_application_id,
        case when p_block_days > 0 then 'rejected_and_blocked' else 'rejected' end,
        p_reviewer_user_id, v_user_id, v_biz_id, nullif(btrim(p_reason), ''), v_blocked_until
    );
    return true;
end;
$function$
;

-- signature: public.release_application_submission_block(uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.release_application_submission_block(p_block_id uuid, p_application_id uuid, p_reviewer_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_block public.application_submission_blocks%rowtype;
begin
    update public.application_submission_blocks
       set blocked_until = least(blocked_until, now()),
           released_at = now(),
           released_by = p_reviewer_user_id
     where id = p_block_id
       and blocked_until > now()
       and released_at is null
     returning * into v_block;

    if not found then return false; end if;

    insert into public.application_moderation_actions(
        application_kind, application_id, action, actor_user_id,
        target_user_id, biz_id, reason, metadata
    ) values (
        v_block.application_kind, p_application_id, 'unblocked', p_reviewer_user_id,
        v_block.subject_user_id, v_block.biz_id, 'Блокировка снята модератором',
        jsonb_build_object('block_id', v_block.id)
    );
    return true;
end;
$function$
;

-- signature: public.release_auth_phone(uuid,text)
CREATE OR REPLACE FUNCTION public.release_auth_phone(p_user_id uuid, p_phone_digits text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_count integer;
    v_spellings text[];
begin
    if p_user_id is null then
        raise exception using errcode = '22023', message = 'INVALID_USER';
    end if;
    if p_phone_digits is null or p_phone_digits !~ '^[0-9]{8,15}$' then
        raise exception using errcode = '22023', message = 'INVALID_PHONE';
    end if;
    -- GoTrue stores the number with or without '+'.
    v_spellings := array[p_phone_digits, '+' || p_phone_digits];

    update auth.users u
       set phone = case when u.phone = any (v_spellings) then null else u.phone end,
           phone_confirmed_at = case when u.phone = any (v_spellings) then null else u.phone_confirmed_at end,
           phone_change = case when u.phone_change = any (v_spellings) then '' else u.phone_change end,
           phone_change_token = case when u.phone_change = any (v_spellings) then '' else u.phone_change_token end,
           phone_change_sent_at = case when u.phone_change = any (v_spellings) then null else u.phone_change_sent_at end,
           raw_user_meta_data = case
               when regexp_replace(coalesce(u.raw_user_meta_data ->> 'phone', ''), '[^0-9]', '', 'g') = p_phone_digits
                   then u.raw_user_meta_data - 'phone'
               else u.raw_user_meta_data end
     where u.id = p_user_id
       and (u.phone = any (v_spellings)
            or u.phone_change = any (v_spellings)
            or regexp_replace(coalesce(u.raw_user_meta_data ->> 'phone', ''), '[^0-9]', '', 'g') = p_phone_digits);
    get diagnostics v_count = row_count;

    delete from auth.identities i
     where i.user_id = p_user_id
       and i.provider = 'phone'
       and (i.provider_id = any (v_spellings)
            or regexp_replace(coalesce(i.identity_data ->> 'phone', ''), '[^0-9]', '', 'g') = p_phone_digits);

    return v_count;
end;
$function$
;

-- signature: public.release_staff_shift_claims(uuid,uuid[])
CREATE OR REPLACE FUNCTION public.release_staff_shift_claims(p_claim_token uuid, p_shift_ids uuid[])
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '3s'
 SET lock_timeout TO '1s'
AS $function$
    update public.staff_shift_close_attempts set lease_until=now() where claim_token=p_claim_token and shift_id=any(p_shift_ids);
$function$
;

-- signature: public.release_unconfirmed_phone(text)
CREATE OR REPLACE FUNCTION public.release_unconfirmed_phone(p_phone_digits text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_count integer;
begin
    if p_phone_digits is null or p_phone_digits !~ '^[0-9]{8,15}$' then
        raise exception using errcode = '22023', message = 'INVALID_PHONE';
    end if;

    update auth.users
       set phone = null
     where phone in (p_phone_digits, '+' || p_phone_digits)
       and phone_confirmed_at is null;
    get diagnostics v_count = row_count;
    return v_count;
end;
$function$
;

-- signature: public.release_whatsapp_inbox(uuid,uuid)
CREATE OR REPLACE FUNCTION public.release_whatsapp_inbox(p_id uuid, p_token uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare item public.whatsapp_inbox;
begin
  item:=public._locked_whatsapp_inbox(p_id,p_token);
  if item.reply_started_at is not null then raise exception 'INBOX_UNSAFE_RETRY'; end if;
  update public.whatsapp_inbox set status='pending',attempts=attempts-1,lease_token=null,lease_until=null where id=p_id;
end;
$function$
;

-- signature: public.remove_user_notification_email_source(uuid,text)
CREATE OR REPLACE FUNCTION public.remove_user_notification_email_source(target_user_id uuid, target_source text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    delete from public.user_notification_email_sources source
    using public.user_notification_emails email
    where source.email_id = email.id
      and email.user_id = target_user_id
      and source.source = target_source;

    delete from public.user_notification_emails email
    where email.user_id = target_user_id
      and not exists (
          select 1
          from public.user_notification_email_sources source
          where source.email_id = email.id
      );

    if not exists (
        select 1
        from public.user_notification_emails
        where user_id = target_user_id
          and enabled
          and verified
    ) then
        update public.user_notification_emails
        set enabled = true,
            updated_at = now()
        where id = (
            select id
            from public.user_notification_emails
            where user_id = target_user_id
              and verified
            order by created_at
            limit 1
        );
    end if;
end;
$function$
;

-- signature: public.replace_branch_schedule(uuid,uuid,uuid,jsonb)
CREATE OR REPLACE FUNCTION public.replace_branch_schedule(p_biz uuid, p_branch uuid, p_actor uuid, p_days jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare item jsonb;
begin
    if not public.schedule_actor_can_manage(p_actor,p_biz) then raise exception 'SCHEDULE_FORBIDDEN'; end if;
    perform 1 from public.branches where id=p_branch and biz_id=p_biz and is_active for update;
    if not found then raise exception 'SCHEDULE_INVALID_BRANCH'; end if;
    if p_days is null or jsonb_typeof(p_days)<>'array' then raise exception 'SCHEDULE_INVALID'; end if;
    if jsonb_array_length(p_days)<>7 or (select count(distinct x->>'day_of_week') from jsonb_array_elements(p_days) x)<>7
        then raise exception 'SCHEDULE_INVALID'; end if;
    for item in select * from jsonb_array_elements(p_days) loop
        if item->>'day_of_week' is null or item->>'day_of_week' !~ '^[0-6]$' then raise exception 'SCHEDULE_INVALID'; end if;
        perform public.schedule_validate_day(item);
    end loop;
    -- Same lock ordering for all employees, including those temporarily in this branch.
    perform 1 from public.staff where biz_id=p_biz order by id for update;
    delete from public.branch_working_hours where biz_id=p_biz and branch_id=p_branch;
    insert into public.branch_working_hours(biz_id,branch_id,day_of_week,intervals,breaks)
        select p_biz,p_branch,(x->>'day_of_week')::int,x->'intervals',x->'breaks' from jsonb_array_elements(p_days) x;
    if exists(select 1 from public.bookings b where b.biz_id=p_biz and b.branch_id=p_branch and b.end_at>now()
        and (b.status::text in ('confirmed','paid') or (b.status::text='hold' and b.expires_at>now()))
        and exists(select 1 from public.staff_schedule_versions v where v.staff_id=b.staff_id)
        and not public.schedule_contains_booking(b.staff_id,b.branch_id,b.start_at,b.end_at))
        then raise exception 'SCHEDULE_BOOKING_CONFLICT'; end if;
end;
$function$
;

-- signature: public.reset_staff_schedule_day(uuid,uuid,uuid,bigint,date)
CREATE OR REPLACE FUNCTION public.reset_staff_schedule_day(p_staff uuid, p_biz uuid, p_actor uuid, p_expected_revision bigint, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare target_branch uuid;
begin
 if not public.schedule_actor_can_manage(p_actor,p_biz) then raise exception 'SCHEDULE_FORBIDDEN'; end if;
 perform 1 from public.staff where id=p_staff and biz_id=p_biz and is_active for update;
 if not found then raise exception 'SCHEDULE_NOT_FOUND'; end if;
 select branch_id into target_branch from public.staff_schedule_versions
 where staff_id=p_staff and kind='week' and effective_from<=p_day
 order by effective_from desc,revision desc limit 1;
 if not found then raise exception 'SCHEDULE_WEEK_REQUIRED'; end if;
 return public.publish_staff_schedule(p_staff,p_biz,p_actor,p_expected_revision,'day',p_day,target_branch,
   '{"day":{"intervals":[],"breaks":[],"use_regular":true}}'::jsonb);
end $function$
;

-- signature: public.resolve_staff_day_legacy(uuid,date)
CREATE OR REPLACE FUNCTION public.resolve_staff_day_legacy(p_staff_id uuid, p_date date)
 RETURNS TABLE(branch_id uuid, tz text, intervals jsonb, breaks jsonb)
 LANGUAGE plpgsql
AS $function$
                                          declare v_row record; v_sched_found boolean:=false; v_biz uuid; v_branch uuid; v_tz text; v_intervals jsonb:='[]'::jsonb; v_breaks jsonb:='[]'::jsonb; dow int:=extract(dow from p_date);
                                          begin
                                           if exists(select 1 from public.staff_time_off t where t.staff_id=p_staff_id and t.cancelled_at is null and p_date between t.date_from and t.date_to) then return; end if;
                                            select st.biz_id,b.tz into v_biz,v_tz from public.staff st join public.businesses b on b.id=st.biz_id where st.id=p_staff_id;
                                             if v_biz is null then return; end if;
                                              for v_row in select * from public.staff_schedule_rules r where r.staff_id=p_staff_id and r.is_active and ((r.kind='date' and r.date_on=p_date) or (r.kind='range' and p_date between r.date_from and r.date_to) or (r.kind='weekly' and r.day_of_week=dow)) order by case r.kind when 'date' then 3 when 'range' then 2 else 1 end desc,r.priority desc,r.created_at desc loop
                                                 branch_id:=v_row.branch_id; tz:=coalesce(v_row.tz,v_tz,'Asia/Bishkek'); intervals:=coalesce(v_row.intervals,'[]'::jsonb); breaks:=coalesce(v_row.breaks,'[]'::jsonb); v_sched_found:=true; return next; return;
                                                  end loop;
                                                   if not v_sched_found then
                                                      select st.branch_id into v_branch from public.staff st where st.id=p_staff_id;
                                                         if v_branch is null then return; end if;
                                                            select wh.intervals,wh.breaks into v_intervals,v_breaks from public.working_hours wh where wh.staff_id=p_staff_id and wh.day_of_week=dow and wh.biz_id=v_biz limit 1;
                                                               if v_intervals is null then return; end if;
                                                                  branch_id:=v_branch; tz:=coalesce(v_tz,'Asia/Bishkek'); intervals:=v_intervals; breaks:=coalesce(v_breaks,'[]'::jsonb); return next; return;
                                                                   end if;
                                                                    return;
                                                                    end
                                                                    $function$
;

-- signature: public.resolve_staff_day(uuid,date)
CREATE OR REPLACE FUNCTION public.resolve_staff_day(p_staff_id uuid, p_date date)
 RETURNS TABLE(branch_id uuid, tz text, intervals jsonb, breaks jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d jsonb; st record;
begin
    select * into st from public.staff where id=p_staff_id;
    if not found then return; end if;
    -- Direct browser calls are revoked. Existing public slot generators execute
    -- as their owner; the server read endpoint verifies employee/business scope.
    d := public.schedule_effective_day(p_staff_id,p_date);
    if d->>'source' in ('unconfigured','absence') then return; end if;
    return query select (d->>'branch_id')::uuid,d->>'tz',d->'intervals',d->'breaks';
end;
$function$
;

-- signature: public.reviews_set_client_id()
CREATE OR REPLACE FUNCTION public.reviews_set_client_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if tg_op = 'INSERT' then
        new.client_id := auth.uid();
        if current_user in ('anon', 'authenticated') then
            new.created_at := now();
        end if;
    elsif current_user in ('anon', 'authenticated')
          and (new.id, new.booking_id, new.client_id, new.created_at)
              is distinct from (old.id, old.booking_id, old.client_id, old.created_at) then
        raise exception 'REVIEW_FIELD_READ_ONLY' using errcode = '42501';
    end if;
    new.updated_at := now();
    return new;
end;
$function$
;

-- signature: public.revoke_branch_admin(uuid,uuid)
CREATE OR REPLACE FUNCTION public.revoke_branch_admin(p_branch_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_biz uuid; v_actor uuid:=auth.uid();
begin
 select biz_id into v_biz from public.branches where id=p_branch_id for update;
 if v_biz is null or p_user_id is null or v_actor is null or not (
  public.is_super_admin() or public.has_role('owner',v_biz) or public.has_role('admin',v_biz)
  or public.has_role('manager',v_biz)
  or exists(select 1 from public.businesses where id=v_biz and owner_id=v_actor)
 ) then raise exception using errcode='42501',message='BRANCH_ADMIN_FORBIDDEN'; end if;
 delete from public.branch_admins where branch_id=p_branch_id and user_id=p_user_id;
end $function$
;

-- signature: public.role_id(text)
CREATE OR REPLACE FUNCTION public.role_id(p_key text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id from public.roles where key = p_key
$function$
;

-- signature: public.save_shift_items_atomic(uuid,jsonb)
CREATE OR REPLACE FUNCTION public.save_shift_items_atomic(p_shift_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_shift_status text;
    v_result jsonb;
    v_item jsonb;
    v_inserted_count integer := 0;
    v_deleted_count integer := 0;
begin
    -- Проверяем, что смена существует и открыта
    select status
    into v_shift_status
    from public.staff_shifts
    where id = p_shift_id
    for update;  -- Блокируем строку для обновления
    
    if v_shift_status is null then
        return jsonb_build_object(
            'ok', false,
            'error', 'Смена не найдена'
        );
    end if;
    
    if v_shift_status != 'open' then
        return jsonb_build_object(
            'ok', false,
            'error', 'Смена должна быть открыта для сохранения позиций'
        );
    end if;
    
    -- Удаляем все существующие позиции для этой смены
    delete from public.staff_shift_items
    where shift_id = p_shift_id;
    
    get diagnostics v_deleted_count = row_count;
    
    -- Вставляем новые позиции
    if p_items is not null and jsonb_array_length(p_items) > 0 then
        insert into public.staff_shift_items (
            shift_id,
            client_name,
            service_name,
            service_amount,
            consumables_amount,
            booking_id,
            note,
            created_at
        )
        select
            p_shift_id,
            (item->>'clientName')::text,
            (item->>'serviceName')::text,
            coalesce(((item->>'serviceAmount')::numeric), 0),
            coalesce(((item->>'consumablesAmount')::numeric), 0),
            case when (item->>'bookingId')::text = '' then null else (item->>'bookingId')::uuid end,
            (item->>'note')::text,
            coalesce(
                ((item->>'createdAt')::timestamptz),
                timezone('utc'::text, now())
            )
        from jsonb_array_elements(p_items) as item
        where
            -- Сохраняем только если есть данные
            coalesce(((item->>'serviceAmount')::numeric), 0) > 0
            or coalesce(((item->>'consumablesAmount')::numeric), 0) > 0
            or (item->>'bookingId')::text is not null
            or ((item->>'clientName')::text is not null and (item->>'clientName')::text != '');
        
        get diagnostics v_inserted_count = row_count;
    end if;
    
    -- Возвращаем результат
    return jsonb_build_object(
        'ok', true,
        'deleted_count', v_deleted_count,
        'inserted_count', v_inserted_count
    );
    
exception
    when others then
        return jsonb_build_object(
            'ok', false,
            'error', 'Ошибка при сохранении позиций: ' || sqlerrm
        );
end;
$function$
;

-- signature: public.save_staff_shift_command_internal_v1(uuid,uuid,date,jsonb,uuid,boolean,bigint)
CREATE OR REPLACE FUNCTION public.save_staff_shift_command_internal_v1(p_staff_id uuid, p_biz_id uuid, p_shift_date date, p_items jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_allow_create boolean DEFAULT false, p_expected_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_actor uuid; v_staff record; v_shift public.staff_shifts%rowtype;
    v_item jsonb; v_items jsonb:='[]'; v_id uuid; v_booking_id uuid; v_booking record;
    v_amount numeric; v_consumables numeric; v_total numeric; v_total_consumables numeric;
    v_pm numeric; v_ps numeric; v_sum numeric; v_master numeric; v_name text; v_service text;
    v_ids uuid[]:='{}'; v_booking_ids uuid[]:='{}'; v_position integer:=0; v_existing_count integer; v_written integer;
begin
    v_actor:=case when auth.role()='service_role' then p_actor_id else auth.uid() end;
    if v_actor is null then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform public.assert_finance_access(p_biz_id,p_staff_id,p_actor_id);
    if p_shift_date is null or jsonb_typeof(p_items) is distinct from 'array' or jsonb_array_length(p_items)>1000 then
        raise exception using errcode='22023',message='SHIFT_ITEMS_INVALID';
    end if;
    -- The same lock order is used by close: staff, shift, sorted bookings, package.
    select * into v_staff from public.staff where id=p_staff_id and biz_id=p_biz_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    select * into v_shift from public.staff_shifts where staff_id=p_staff_id and shift_date=p_shift_date for update;
    if not found then
        if not p_allow_create or not public.finance_can_manage_business(v_actor,p_biz_id) then
            raise exception using errcode='22023',message='SHIFT_NOT_OPEN';
        end if;
        insert into public.staff_shifts(staff_id,biz_id,branch_id,shift_date,status,opened_at)
        values(p_staff_id,p_biz_id,v_staff.branch_id,p_shift_date,'open',now())
        on conflict(staff_id,shift_date) do nothing;
        select * into v_shift from public.staff_shifts where staff_id=p_staff_id and shift_date=p_shift_date for update;
    end if;
    if v_shift.biz_id is distinct from p_biz_id then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    if v_shift.status<>'open' then raise exception using errcode='40001',message='SHIFT_CLOSED'; end if;
    if p_expected_revision is not null and v_shift.ledger_revision<>p_expected_revision then
        raise exception using errcode='40001',message='SHIFT_STALE';
    end if;

    -- Validate all supplied identities and amounts before any booking/ledger mutation.
    for v_item in select value from jsonb_array_elements(p_items) loop
        if jsonb_typeof(v_item)<>'object' then raise exception using errcode='22023',message='SHIFT_ITEMS_INVALID'; end if;
        v_id:=coalesce(nullif(v_item->>'id','')::uuid,nullif(v_item->>'clientId','')::uuid,gen_random_uuid());
        if v_id=any(v_ids) then raise exception using errcode='22023',message='SHIFT_ITEM_DUPLICATE'; end if;
        v_ids:=array_append(v_ids,v_id);
        if exists(select 1 from public.staff_shift_items where id=v_id and shift_id<>v_shift.id)
            or (nullif(v_item->>'id','') is not null and not exists(select 1 from public.staff_shift_items where id=v_id and shift_id=v_shift.id)) then
            raise exception using errcode='42501',message='SHIFT_ITEM_SCOPE';
        end if;
        v_booking_id:=nullif(v_item->>'bookingId','')::uuid;
        if v_booking_id is not null then
            if v_booking_id=any(v_booking_ids) then raise exception using errcode='22023',message='SHIFT_BOOKING_DUPLICATE'; end if;
            v_booking_ids:=array_append(v_booking_ids,v_booking_id);
        end if;
        v_amount:=coalesce((v_item->>'serviceAmount')::numeric,0);
        v_consumables:=coalesce((v_item->>'consumablesAmount')::numeric,0);
        v_name:=nullif(btrim(v_item->>'clientName'),''); v_service:=nullif(btrim(v_item->>'serviceName'),'');
        if v_amount::text in ('NaN','Infinity','-Infinity') or v_consumables::text in ('NaN','Infinity','-Infinity')
            or v_amount<0 or v_consumables<0 or v_amount>100000000 or v_consumables>100000000
            or length(v_name)>200 or length(v_service)>200 then raise exception using errcode='22023',message='SHIFT_ITEMS_INVALID'; end if;
        if v_amount>0 or v_consumables>0 or v_booking_id is not null or v_name is not null
            or exists(select 1 from public.staff_shift_items where id=v_id and shift_id=v_shift.id) then
            v_items:=v_items||jsonb_build_array(jsonb_build_object('id',v_id,'booking_id',v_booking_id,
                'client_name',v_name,'service_name',v_service,'service_amount',v_amount,'consumables_amount',v_consumables,
                'created_at',now()+v_position*interval '1 millisecond'));
        end if;
        v_position:=v_position+1;
    end loop;
    for v_booking_id in select unnest(v_booking_ids) order by 1 loop
        select * into v_booking from public.bookings where id=v_booking_id for update;
        if not found or v_booking.biz_id is distinct from p_biz_id or v_booking.staff_id is distinct from p_staff_id
            or (v_booking.start_at at time zone public.finance_business_timezone(p_biz_id))::date is distinct from p_shift_date then
            raise exception using errcode='42501',message='SHIFT_BOOKING_SCOPE';
        end if;
        if v_booking.status='cancelled' then raise exception using errcode='22023',message='SHIFT_BOOKING_CANCELLED'; end if;
    end loop;
    select count(*) into v_existing_count from public.staff_shift_items where shift_id=v_shift.id;
    if v_existing_count>10 and jsonb_array_length(v_items)=0 then
        raise exception using errcode='22023',message='SHIFT_CLEAR_REQUIRES_REVIEW';
    end if;
    for v_booking_id in select unnest(v_booking_ids) order by 1 loop
        if exists(select 1 from public.bookings where id=v_booking_id and status not in ('paid','no_show') and start_at<=now()) then
            perform public.update_booking_status_with_promotion(v_booking_id,'paid');
        end if;
    end loop;

    delete from public.staff_shift_items s where s.shift_id=v_shift.id
        and not exists(select 1 from jsonb_array_elements(v_items) i where (i->>'id')::uuid=s.id);
    insert into public.staff_shift_items(id,shift_id,client_name,service_name,service_amount,consumables_amount,booking_id,created_at)
    select i.id,v_shift.id,i.client_name,i.service_name,
        coalesce((coalesce(b.subscription_applied,b.promotion_applied)->>'final_amount')::numeric,i.service_amount),
        i.consumables_amount,i.booking_id,i.created_at
    from jsonb_to_recordset(v_items) as i(id uuid,client_name text,service_name text,service_amount numeric,consumables_amount numeric,booking_id uuid,created_at timestamptz)
    left join public.bookings b on b.id=i.booking_id
    on conflict(id) do update set client_name=excluded.client_name,service_name=excluded.service_name,
        service_amount=excluded.service_amount,consumables_amount=excluded.consumables_amount,booking_id=excluded.booking_id
    where public.staff_shift_items.shift_id=v_shift.id;
    get diagnostics v_written=row_count;
    if v_written<>jsonb_array_length(v_items) then raise exception using errcode='42501',message='SHIFT_ITEM_SCOPE'; end if;

    select coalesce(sum(service_amount),0),coalesce(sum(consumables_amount),0) into v_total,v_total_consumables
        from public.staff_shift_items where shift_id=v_shift.id;
    v_pm:=coalesce(v_staff.percent_master,60); v_ps:=coalesce(v_staff.percent_salon,40);
    if v_pm<0 or v_pm::text in ('NaN','Infinity','-Infinity') then v_pm:=60; end if;
    if v_ps<0 or v_ps::text in ('NaN','Infinity','-Infinity') then v_ps:=40; end if;
    v_sum:=case when v_pm+v_ps=0 then 100 else v_pm+v_ps end;
    v_master:=round(v_total*v_pm/v_sum);
    update public.staff_shifts set total_amount=v_total,consumables_amount=v_total_consumables,
        percent_master=v_pm*100/v_sum,percent_salon=v_ps*100/v_sum,
        master_share=v_master,salon_share=v_total-v_master+v_total_consumables
        where id=v_shift.id returning * into v_shift;
    return jsonb_build_object('ok',true,'shift_id',v_shift.id,'revision',v_shift.ledger_revision);
end;
$function$
;

-- signature: public.save_staff_shift_command(uuid,uuid,date,jsonb,uuid,boolean,bigint,uuid)
CREATE OR REPLACE FUNCTION public.save_staff_shift_command(p_staff_id uuid, p_biz_id uuid, p_shift_date date, p_items jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_allow_create boolean DEFAULT false, p_expected_revision bigint DEFAULT NULL::bigint, p_expected_shift_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_shift public.staff_shifts%rowtype; v_result jsonb; v_items jsonb; v_today date; v_date date;
begin
    perform public.assert_finance_access(p_biz_id,p_staff_id,p_actor_id);
    -- Use the same ordering as Save and Close. The staff lock also serializes
    -- competing creation attempts when there is no shift row to lock yet.
    perform 1 from public.staff where id=p_staff_id and biz_id=p_biz_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    v_today:=(statement_timestamp() at time zone public.finance_business_timezone(p_biz_id))::date;
    if p_expected_shift_id is not null then
        select shift_date into v_date from public.staff_shifts where id=p_expected_shift_id and staff_id=p_staff_id and biz_id=p_biz_id;
        if not found or (p_shift_date is not null and p_shift_date<>v_date) then
            raise exception using errcode='40001',message='SHIFT_DATE_MISMATCH';
        end if;
        p_shift_date:=v_date;
    else
        p_shift_date:=coalesce(p_shift_date,v_today);
    end if;
    select * into v_shift from public.staff_shifts
        where staff_id=p_staff_id and shift_date=p_shift_date for update;
    if found then
        if v_shift.biz_id is distinct from p_biz_id then
            raise exception using errcode='42501',message='FINANCE_FORBIDDEN';
        end if;
        if v_shift.status<>'open' then raise exception using errcode='40001',message='SHIFT_CLOSED'; end if;
        if p_expected_shift_id is distinct from v_shift.id or
            p_expected_revision is distinct from v_shift.ledger_revision then
            raise exception using errcode='40001',message='SHIFT_STALE';
        end if;
    elsif p_expected_shift_id is not null or p_expected_revision is not null then
        raise exception using errcode='40001',message='SHIFT_STALE';
    end if;
    if p_shift_date>v_today or (v_shift.id is null and p_shift_date<>v_today) then
        raise exception using errcode='40001',message='SHIFT_DATE_REQUIRES_EXISTING_SHIFT';
    end if;
    v_result:=public.save_staff_shift_command_internal_v1(
        p_staff_id,p_biz_id,p_shift_date,p_items,p_actor_id,p_allow_create,p_expected_revision);
    -- The inner command still owns its locks. Return persisted IDs and effective
    -- promotion/package amounts from this transaction, never a later HTTP read.
    select coalesce(jsonb_agg(jsonb_build_object(
        'id',id,'clientName',coalesce(client_name,''),'serviceName',coalesce(service_name,''),
        'serviceAmount',service_amount,'consumablesAmount',consumables_amount,
        'bookingId',booking_id,'note',note,'createdAt',created_at
    ) order by created_at desc,id),'[]'::jsonb) into v_items
    from public.staff_shift_items where shift_id=(v_result->>'shift_id')::uuid;
    return v_result||jsonb_build_object('items',v_items);
end;
$function$
;

-- signature: public.schedule_actor_can_manage(uuid,uuid)
CREATE OR REPLACE FUNCTION public.schedule_actor_can_manage(p_actor uuid, p_biz uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select p_actor is not null and (
        exists(select 1 from public.businesses where id=p_biz and owner_id=p_actor)
        or exists(select 1 from public.user_roles ur join public.roles r on r.id=ur.role_id
                  where ur.user_id=p_actor and (r.key='super_admin' or (ur.biz_id=p_biz and r.key in ('owner','admin','manager'))))
    );
$function$
;

-- signature: public.schedule_bound_to_branch(jsonb,uuid,date)
CREATE OR REPLACE FUNCTION public.schedule_bound_to_branch(p_day jsonb, p_biz uuid, p_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare hours record; effective jsonb; pauses jsonb;
begin
    select wh.* into hours from public.branch_working_hours wh
        join public.branches b on b.id=wh.branch_id and b.is_active
        where wh.biz_id=p_biz and wh.branch_id=(p_day->>'branch_id')::uuid
        and wh.day_of_week=extract(dow from p_date)::int;
    if not found then return p_day || jsonb_build_object('intervals','[]'::jsonb,'breaks','[]'::jsonb); end if;
    select coalesce(jsonb_agg(jsonb_build_object('start',a,'end',z) order by a),'[]'::jsonb) into effective from (
        select greatest(s->>'start',b->>'start') a,least(s->>'end',b->>'end') z
        from jsonb_array_elements(p_day->'intervals') s cross join jsonb_array_elements(hours.intervals) b
        where greatest(s->>'start',b->>'start')<least(s->>'end',b->>'end')
    ) ranges;
    pauses:=coalesce(p_day->'breaks','[]'::jsonb)||coalesce(hours.breaks,'[]'::jsonb);
    return p_day || jsonb_build_object('intervals',effective,'breaks',pauses);
end;
$function$
;

-- signature: public.schedule_contains_booking(uuid,uuid,timestamp with time zone,timestamp with time zone)
CREATE OR REPLACE FUNCTION public.schedule_contains_booking(p_staff uuid, p_branch uuid, p_start timestamp with time zone, p_end timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d jsonb; day date; tz text; a timestamp; z timestamp;
begin
    select coalesce(b.tz,'Asia/Bishkek') into tz from public.staff s join public.businesses b on b.id=s.biz_id where s.id=p_staff;
    day:=(p_start at time zone tz)::date;
    d:=public.schedule_effective_day(p_staff,day);
    a:=p_start at time zone tz; z:=p_end at time zone tz;
    return coalesce((d->>'branch_id')::uuid=p_branch and z>a and z::date=day
        and exists(select 1 from jsonb_array_elements(d->'intervals') w
            where day+(w->>'start')::time<=a and day+(w->>'end')::time>=z)
        and not exists(select 1 from jsonb_array_elements(d->'breaks') w
            where tsrange(day+(w->>'start')::time,day+(w->>'end')::time,'[)') && tsrange(a,z,'[)')),false);
end;
$function$
;

-- signature: public.schedule_effective_day(uuid,date)
CREATE OR REPLACE FUNCTION public.schedule_effective_day(p_staff uuid, p_day date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st record; v record; legacy record; regular_day boolean := false; result jsonb; business_tz text;
begin
 select s.*,coalesce(b.tz,'Asia/Bishkek') as business_tz into st from public.staff s join public.businesses b on b.id=s.biz_id where s.id=p_staff;
  if not found then raise exception 'SCHEDULE_NOT_FOUND'; end if;
   business_tz:=st.business_tz;
    result:=jsonb_build_object('date',p_day,'branch_id',st.branch_id,'tz',business_tz,'source','unconfigured','intervals','[]'::jsonb,'breaks','[]'::jsonb);
     if not st.is_active then return result; end if;
      if exists(select 1 from public.staff_time_off t where t.staff_id=p_staff and t.biz_id=st.biz_id and t.cancelled_at is null and p_day between t.date_from and t.date_to) then return result||jsonb_build_object('source','absence'); end if;
       select * into v from public.staff_schedule_versions where staff_id=p_staff and kind='day' and effective_from=p_day order by revision desc limit 1;
        regular_day:=found and coalesce(v.days->'day'->>'use_regular','false')='true';
         if found and not regular_day then return public.schedule_bound_to_branch(result||(v.days->'day')||jsonb_build_object('branch_id',v.branch_id,'source','day'),st.biz_id,p_day); end if;
          if not regular_day and exists(select 1 from public.staff_schedule_rules r where r.staff_id=p_staff and r.is_active and ((r.kind='date' and r.date_on=p_day) or (r.kind='range' and p_day between r.date_from and r.date_to))) then
             select * into legacy from public.resolve_staff_day_legacy(p_staff,p_day);
                if found then return result||to_jsonb(legacy)||jsonb_build_object('source','legacy'); end if;
                 end if;
                  select * into v from public.staff_schedule_versions where staff_id=p_staff and kind='week' and effective_from<=p_day order by effective_from desc,revision desc limit 1;
                   if found then return public.schedule_bound_to_branch(result||(v.days->extract(isodow from p_day)::int::text)||jsonb_build_object('branch_id',v.branch_id,'source','week'),st.biz_id,p_day); end if;
                    select * into legacy from public.resolve_staff_day_legacy(p_staff,p_day);
                     if found then
                        if not exists(select 1 from public.staff_schedule_rules r where r.staff_id=p_staff and r.is_active and r.kind='weekly' and r.day_of_week=extract(dow from p_day)::int)
                             and exists(select 1 from public.staff_home_branch_changes c where c.staff_id=p_staff) then
                                  legacy.branch_id:=coalesce((select c.to_branch_id from public.staff_home_branch_changes c where c.staff_id=p_staff and c.effective_on<=p_day order by c.effective_on desc,c.id desc limit 1),(select c.from_branch_id from public.staff_home_branch_changes c where c.staff_id=p_staff order by c.effective_on,c.id limit 1));
                                     end if;
                                        return result||to_jsonb(legacy)||jsonb_build_object('source','legacy');
                                         end if;
                                          return result;
                                          end;
                                          $function$
;

-- signature: public.schedule_validate_day(jsonb)
CREATE OR REPLACE FUNCTION public.schedule_validate_day(p_day jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare k text; part jsonb; last_end text; a text; z text;
begin
    if p_day is null or jsonb_typeof(p_day)<>'object' then raise exception 'SCHEDULE_INVALID'; end if;
    foreach k in array array['intervals','breaks'] loop
        if p_day->k is null or jsonb_typeof(p_day->k)<>'array' then raise exception 'SCHEDULE_INVALID'; end if;
        if jsonb_array_length(p_day->k)>8 then raise exception 'SCHEDULE_INVALID'; end if;
        last_end := '';
        for part in select * from jsonb_array_elements(p_day->k) loop
            a:=part->>'start'; z:=part->>'end';
            if a is null or z is null or a !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
                or z !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$' or a>=z or a<last_end then
                raise exception 'SCHEDULE_INVALID';
            end if;
            if k='breaks' and not exists(select 1 from jsonb_array_elements(p_day->'intervals') w
                where w->>'start'<=a and w->>'end'>=z) then raise exception 'SCHEDULE_INVALID'; end if;
            last_end:=z;
        end loop;
    end loop;
end;
$function$
;

-- signature: public.set_my_notification_email_preferences(boolean,text[])
CREATE OR REPLACE FUNCTION public.set_my_notification_email_preferences(target_enabled boolean, target_emails text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    normalized_emails text[] := coalesce(
        (
            select array_agg(distinct lower(btrim(value)))
            from unnest(coalesce(target_emails, array[]::text[])) value
            where btrim(value) <> ''
        ),
        array[]::text[]
    );
begin
    if auth.uid() is null then
        raise exception 'Authentication required';
    end if;
    if target_enabled and cardinality(normalized_emails) = 0 then
        raise exception 'Select at least one notification email';
    end if;
    if exists (
        select 1
        from unnest(normalized_emails) selected_email
        where not exists (
            select 1
            from public.user_notification_emails email
            where email.user_id = auth.uid()
              and email.email = selected_email
              and email.verified
        )
    ) then
        raise exception 'Unknown or unverified notification email';
    end if;

    update public.user_notification_emails
    set enabled = email = any(normalized_emails),
        updated_at = now()
    where user_id = auth.uid();

    update public.profiles
    set notify_email = target_enabled
    where id = auth.uid();
end;
$function$
;

-- signature: public.set_platform_admin_role(uuid,uuid,boolean)
CREATE OR REPLACE FUNCTION public.set_platform_admin_role(p_actor_id uuid, p_target_user_id uuid, p_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '5s'
AS $function$
declare v_role_id uuid; effective boolean;
begin
  if coalesce(nullif(current_setting('role',true),'none'),session_user) not in ('service_role','postgres','supabase_admin') then
    raise exception using errcode='42501',message='PLATFORM_ADMIN_SERVICE_ONLY';
  end if;
  if p_actor_id is null or p_target_user_id is null or p_enabled is null then
    raise exception using errcode='22023',message='PLATFORM_ADMIN_INVALID_INPUT';
  end if;
  -- All grant/revoke commands share this lock, including concurrent self-revocations.
  perform pg_advisory_xact_lock(184207,1);
  perform 1 from auth.users where id in (p_actor_id,p_target_user_id) order by id for update;
  if not exists(select 1 from auth.users where id=p_actor_id) or not public.finance_is_platform_admin(p_actor_id) then
    raise exception using errcode='42501',message='PLATFORM_ADMIN_FORBIDDEN';
  end if;
  if not exists(select 1 from auth.users where id=p_target_user_id) then
    raise exception using errcode='P0002',message='PLATFORM_ADMIN_TARGET_NOT_FOUND';
  end if;
  if not p_enabled and p_actor_id=p_target_user_id and not exists (
    select 1 from (
      select g.user_id from public.user_global_roles g join public.roles r on r.id=g.role_id where r.scope='platform' and r.key='super_admin'
      union select user_id from public.super_admins_legacy
      union select u.user_id from public.user_roles u join public.roles r on r.id=u.role_id where u.biz_id is null and r.key='super_admin'
    ) candidates join auth.users a on a.id=candidates.user_id where a.id<>p_target_user_id
  ) then raise exception using errcode='P0001',message='PLATFORM_ADMIN_LAST_ADMIN'; end if;

  if p_enabled then
    select id into v_role_id from public.roles where key='super_admin' and scope='platform' for share;
    if v_role_id is null then raise exception 'PLATFORM_ADMIN_ROLE_NOT_CONFIGURED'; end if;
    insert into public.user_global_roles(user_id,role_id) values(p_target_user_id,v_role_id)
      on conflict(user_id,role_id) do nothing;
  else
    delete from public.user_global_roles g using public.roles r
      where g.user_id=p_target_user_id and g.role_id=r.id and r.scope='platform' and r.key='super_admin';
    delete from public.user_roles u using public.roles r
      where u.user_id=p_target_user_id and u.role_id=r.id and u.biz_id is null and r.key='super_admin';
    delete from public.super_admins_legacy where user_id=p_target_user_id;
  end if;
  effective:=public.finance_is_platform_admin(p_target_user_id);
  if effective is distinct from p_enabled then raise exception 'PLATFORM_ADMIN_STATE_UNCONFIRMED'; end if;
  return effective;
end;
$function$
;

-- signature: public.set_timestamp_updated_at()
CREATE OR REPLACE FUNCTION public.set_timestamp_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    new.updated_at = timezone('utc'::text, now());
    return new;
end;
$function$
;

-- signature: public.staff_guard_client_write()
CREATE OR REPLACE FUNCTION public.staff_guard_client_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if current_user not in ('anon', 'authenticated') then
        return new;
    end if;

    if tg_op = 'INSERT' then
        if not public.staff_write_allowed(new.biz_id, new.branch_id) then
            raise exception 'STAFF_WRITE_FORBIDDEN' using errcode = '42501';
        end if;
        new.rating_score := null;
        new.rating_updated_at := null;
        new.last_rating_recalculated_at := null;
        return new;
    end if;

    if new.id is distinct from old.id
       or new.biz_id is distinct from old.biz_id
       or new.created_at is distinct from old.created_at
       or new.rating_score is distinct from old.rating_score
       or new.rating_updated_at is distinct from old.rating_updated_at
       or new.last_rating_recalculated_at is distinct from old.last_rating_recalculated_at then
        raise exception 'STAFF_FIELD_READ_ONLY' using errcode = '42501';
    end if;

    if (new.user_id, new.branch_id, new.is_active, new.email, new.phone,
        new.percent_master, new.percent_salon, new.hourly_rate)
       is distinct from
       (old.user_id, old.branch_id, old.is_active, old.email, old.phone,
        old.percent_master, old.percent_salon, old.hourly_rate)
       and not public.staff_write_allowed(old.biz_id, new.branch_id) then
        raise exception 'STAFF_WRITE_FORBIDDEN' using errcode = '42501';
    end if;

    return new;
end;
$function$
;

-- signature: public.staff_private_fields(uuid)
CREATE OR REPLACE FUNCTION public.staff_private_fields(p_staff_id uuid)
 RETURNS TABLE(id uuid, biz_id uuid, branch_id uuid, full_name text, email text, phone text, user_id uuid, avatar_url text, is_active boolean, percent_master numeric, percent_salon numeric, hourly_rate numeric, rating_score numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_staff public.staff%rowtype;
    v_actor uuid := auth.uid();
    v_allowed boolean;
begin
    select * into v_staff from public.staff s where s.id = p_staff_id;
    if not found then
        return;
    end if;

    -- Every term is a definite boolean: a staff row without a linked account (user_id null)
    -- must not slip through a NULL comparison.
    v_allowed := coalesce(auth.role(), '') = 'service_role'
        or (v_actor is not null and v_staff.user_id is not null and v_staff.user_id = v_actor)
        or coalesce(public.finance_can_manage_business(v_actor, v_staff.biz_id), false);
    if not coalesce(v_allowed, false) then
        raise exception 'STAFF_FORBIDDEN' using errcode = '42501';
    end if;

    return query select
        v_staff.id, v_staff.biz_id, v_staff.branch_id, v_staff.full_name, v_staff.email, v_staff.phone,
        v_staff.user_id, v_staff.avatar_url, v_staff.is_active, v_staff.percent_master,
        v_staff.percent_salon, v_staff.hourly_rate, v_staff.rating_score;
end;
$function$
;

-- signature: public.staff_write_allowed(uuid,uuid)
CREATE OR REPLACE FUNCTION public.staff_write_allowed(p_biz_id uuid, p_branch_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
    select coalesce(public.finance_can_manage_business(auth.uid(), p_biz_id), false)
       and (p_branch_id is null or exists (
            select 1 from public.branches b where b.id = p_branch_id and b.biz_id = p_biz_id));
$function$
;

-- signature: public.start_cron_execution(uuid,text)
CREATE OR REPLACE FUNCTION public.start_cron_execution(p_id uuid, p_job text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_job text;
begin
    if p_id is null or p_job is null or p_job !~ '^[a-z][a-z0-9-]{0,63}$' then
        raise exception using errcode='22023',message='CRON_EXECUTION_INVALID';
    end if;
    -- A terminated worker cannot leave a perpetual running badge after recovery.
    update public.cron_executions set outcome='failed',completed_at=clock_timestamp(),error_code='execution_expired'
    where job=p_job and outcome='running' and started_at<clock_timestamp()-interval '15 minutes';
    delete from public.cron_executions where id in (
        select id from public.cron_executions where started_at<clock_timestamp()-interval '30 days'
        order by started_at limit 200
    );
    insert into public.cron_executions(id,job) values(p_id,p_job) on conflict(id) do nothing;
    select job into strict v_job from public.cron_executions where id=p_id;
    if v_job<>p_job then raise exception using errcode='22023',message='CRON_EXECUTION_CONFLICT'; end if;
    return p_id;
end $function$
;

-- signature: public.sync_auth_user_notification_email()
CREATE OR REPLACE FUNCTION public.sync_auth_user_notification_email()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
    if tg_op = 'UPDATE' and old.email is distinct from new.email then
        perform public.remove_user_notification_email_source(new.id, 'account');
    end if;

    if new.email is not null and new.email_confirmed_at is not null then
        perform public.sync_user_notification_email(new.id, new.email, 'account', new.id::text);
    end if;
    return new;
end;
$function$
;

-- signature: public.sync_user_notification_email(uuid,text,text,text)
CREATE OR REPLACE FUNCTION public.sync_user_notification_email(target_user_id uuid, target_email text, target_source text, target_provider_subject text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    normalized_email text := lower(btrim(target_email));
    notification_email_id uuid;
    should_enable boolean;
    proven boolean;
begin
    if target_source not in ('account', 'google', 'yandex') then
        raise exception 'Unsupported notification email source';
    end if;
    if normalized_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
        raise exception 'Invalid notification email';
    end if;

    proven := case target_source
        when 'account' then exists (
            select 1 from auth.users u
             where u.id = target_user_id
               and lower(btrim(u.email)) = normalized_email
               and u.email_confirmed_at is not null)
        when 'google' then exists (
            select 1 from auth.identities i
             where i.user_id = target_user_id
               and i.provider = 'google'
               and lower(btrim(i.identity_data ->> 'email')) = normalized_email
               and coalesce(i.identity_data ->> 'email_verified', 'true') <> 'false')
        else exists (
            select 1 from public.profiles p
             where p.id = target_user_id
               and p.yandex_id is not null
               and p.yandex_id = target_provider_subject)
    end;
    if not proven then
        raise exception 'NOTIFICATION_EMAIL_NOT_PROVEN' using detail = target_source;
    end if;

    select not exists (
        select 1 from public.user_notification_emails where user_id = target_user_id
    ) into should_enable;

    insert into public.user_notification_emails(user_id, email, verified, enabled)
    values (target_user_id, normalized_email, true, should_enable)
    on conflict (user_id, email) do update
    set verified = true,
        updated_at = now()
    returning id into notification_email_id;

    insert into public.user_notification_email_sources(email_id, source, provider_subject)
    values (notification_email_id, target_source, target_provider_subject)
    on conflict (email_id, source) do update
    set provider_subject = excluded.provider_subject;
end;
$function$
;

-- signature: public.transfer_staff_home(uuid,uuid,uuid,uuid,uuid)
CREATE OR REPLACE FUNCTION public.transfer_staff_home(p_staff uuid, p_biz uuid, p_actor uuid, p_expected_branch uuid, p_target uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare st record; today date; tz text;
begin
    if not public.schedule_actor_can_manage(p_actor,p_biz) then raise exception 'SCHEDULE_FORBIDDEN'; end if;
    -- Same branch -> staff lock order as replacement of branch opening hours.
    perform 1 from public.branches where id=p_target and biz_id=p_biz and is_active for update;
    if not found then raise exception 'SCHEDULE_INVALID_BRANCH'; end if;
    select * into st from public.staff where id=p_staff and biz_id=p_biz for update;
    if not found or not st.is_active then raise exception 'SCHEDULE_NOT_FOUND'; end if;
    if st.branch_id is distinct from p_expected_branch then raise exception 'SCHEDULE_STALE'; end if;
    if st.branch_id=p_target then raise exception 'SCHEDULE_SAME_BRANCH'; end if;
    select coalesce(b.tz,'Asia/Bishkek') into tz from public.businesses b where b.id=p_biz;
    today := (now() at time zone tz)::date;
    -- Never delete a separately planned future assignment to make today's transfer fit.
    if exists(select 1 from public.staff_branch_assignments where staff_id=p_staff and valid_from>today)
        then raise exception 'SCHEDULE_FUTURE_ASSIGNMENT'; end if;
    update public.staff_branch_assignments set valid_to=today-1
        where staff_id=p_staff and valid_from<today and (valid_to is null or valid_to>=today);
    delete from public.staff_branch_assignments where staff_id=p_staff and valid_from=today;
    insert into public.staff_branch_assignments(biz_id,staff_id,branch_id,valid_from)
        values(p_biz,p_staff,p_target,today);
    insert into public.staff_home_branch_changes(staff_id,biz_id,from_branch_id,to_branch_id,effective_on,created_by)
        values(p_staff,p_biz,st.branch_id,p_target,today,p_actor);
    update public.staff set branch_id=p_target where id=p_staff;
    -- Published plans keep their branch; legacy inherited hours may change location.
    -- A conflicting future reservation aborts membership, assignments and audit together.
    if exists(select 1 from public.bookings b where b.staff_id=p_staff and b.end_at>now()
        and (b.status::text in ('confirmed','paid') or (b.status::text='hold' and b.expires_at>now()))
        and not public.schedule_contains_booking(p_staff,b.branch_id,b.start_at,b.end_at))
        then raise exception 'SCHEDULE_BOOKING_CONFLICT'; end if;
    return jsonb_build_object('note','HOME_BRANCH_CHANGED_SCHEDULE_PRESERVED');
end;
$function$
;

-- signature: public.transition_telegram_profile_link(text,text,uuid,bigint,text,text)
CREATE OR REPLACE FUNCTION public.transition_telegram_profile_link(p_hash text, p_action text, p_owner uuid DEFAULT NULL::uuid, p_telegram bigint DEFAULT NULL::bigint, p_username text DEFAULT NULL::text, p_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    a public.telegram_profile_link_attempts%rowtype;
    current_telegram bigint;
begin
    select * into a from public.telegram_profile_link_attempts where token_hash = p_hash for update;
    if not found then return jsonb_build_object('error','not_found'); end if;
    if p_action in ('finish','cancel_owner') then
        if p_owner is null or a.owner_id <> p_owner then return jsonb_build_object('error','not_found'); end if;
    elsif p_action not in ('claim','approve','cancel_bot') or p_telegram is null or p_telegram <= 0 then
        return jsonb_build_object('error','invalid_action');
    end if;
    if a.status = 'consumed' and p_action = 'finish' and a.telegram_id = p_telegram then
        return jsonb_build_object('status','consumed');
    end if;
    if a.expires_at <= now() then
        update public.telegram_profile_link_attempts set status = 'expired' where token_hash = p_hash and status in ('pending','approved');
        return jsonb_build_object('error','expired');
    end if;
    if a.status not in ('pending','approved') then return jsonb_build_object('error','closed'); end if;
    if p_action = 'cancel_owner' then
        update public.telegram_profile_link_attempts set status = 'cancelled' where token_hash = p_hash;
        return jsonb_build_object('status','cancelled');
    end if;
    if a.telegram_id is not null and a.telegram_id <> p_telegram then
        return jsonb_build_object('error','different_account');
    end if;
    if p_action = 'claim' then
        if a.status <> 'pending' then return jsonb_build_object('error','closed'); end if;
        update public.telegram_profile_link_attempts set telegram_id = p_telegram,
            telegram_username = left(p_username, 64), telegram_name = left(p_name, 128) where token_hash = p_hash;
        return jsonb_build_object('status','pending');
    end if;
    if a.telegram_id is null then return jsonb_build_object('error','not_claimed'); end if;
    if p_action in ('approve','cancel_bot') then
        update public.telegram_profile_link_attempts set status = case when p_action = 'approve' then 'approved' else 'cancelled' end where token_hash = p_hash;
        return jsonb_build_object('status',case when p_action = 'approve' then 'approved' else 'cancelled' end);
    end if;
    if p_action <> 'finish' or a.status <> 'approved' or p_telegram is null then
        return jsonb_build_object('error','not_approved');
    end if;
    select telegram_id into current_telegram from public.profiles where id = a.owner_id for update;
    if not found then return jsonb_build_object('error','profile_missing'); end if;
    if current_telegram is not null and current_telegram <> a.telegram_id then
        return jsonb_build_object('error','already_connected');
    end if;
    if exists (select 1 from public.profiles where telegram_id = a.telegram_id and id <> a.owner_id) then
        return jsonb_build_object('error','already_linked');
    end if;
    begin
        update public.profiles set telegram_id = a.telegram_id, telegram_username = a.telegram_username,
            telegram_photo_url = null, telegram_verified = true where id = a.owner_id;
        update auth.users set raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) ||
            jsonb_build_object('telegram_id',a.telegram_id,'telegram_username',a.telegram_username)
            where id = a.owner_id;
        update public.telegram_profile_link_attempts set status = 'consumed' where token_hash = p_hash;
    exception when unique_violation then
        return jsonb_build_object('error','already_linked');
    end;
    return jsonb_build_object('status','consumed');
end;
$function$
;

-- signature: public.transition_telegram_web_login(text,text,text,bigint,text)
CREATE OR REPLACE FUNCTION public.transition_telegram_web_login(p_hash text, p_action text, p_browser text DEFAULT NULL::text, p_telegram bigint DEFAULT NULL::bigint, p_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 a public.telegram_web_login_attempts%rowtype;
 uid uuid;
begin
 if p_action not in ('claim','approve','cancel_bot','cancel','finish') then
 return jsonb_build_object('error','invalid_action'); end if;
 select * into a from public.telegram_web_login_attempts where token_hash = p_hash for update;
 if not found then return jsonb_build_object('error','not_found'); end if;
 if p_action in ('cancel','finish') and (p_browser is null or p_browser <> a.browser_hash) then
 return jsonb_build_object('error','not_found'); end if;
 if a.status in ('consumed','cancelled','expired') then return jsonb_build_object('error','closed'); end if;
 if a.expires_at <= now() then
 update public.telegram_web_login_attempts set status = 'expired' where token_hash = p_hash;
 return jsonb_build_object('error','expired'); end if;
 if p_action = 'cancel' then
 update public.telegram_web_login_attempts set status = 'cancelled' where token_hash = p_hash;
 return jsonb_build_object('status','cancelled'); end if;
 if p_telegram is null or p_telegram <= 0 then return jsonb_build_object('error','invalid_account'); end if;
 if a.telegram_id is not null and a.telegram_id <> p_telegram then
 return jsonb_build_object('error','different_account'); end if;
 if p_action = 'claim' then
 update public.telegram_web_login_attempts set telegram_id = p_telegram, telegram_name = left(p_name, 160) where token_hash = p_hash;
 return jsonb_build_object('status',a.status); end if;
 if a.telegram_id is null then return jsonb_build_object('error','not_claimed'); end if;
 if p_action = 'cancel_bot' then
 update public.telegram_web_login_attempts set status = 'cancelled' where token_hash = p_hash;
 return jsonb_build_object('status','cancelled'); end if;
 if p_action = 'approve' then
 update public.telegram_web_login_attempts set status = 'approved' where token_hash = p_hash;
 return jsonb_build_object('status','approved'); end if;
 if a.status <> 'approved' then return jsonb_build_object('error','not_approved'); end if;
 select id into uid from public.profiles where telegram_id = p_telegram and telegram_verified = true for share;
 if uid is null then return jsonb_build_object('error','not_linked'); end if;
 update public.telegram_web_login_attempts set status = 'consumed' where token_hash = p_hash;
 return jsonb_build_object('status','consumed','user_id',uid);
end $function$
;

-- signature: public.unlink_auth_identity(uuid,text)
CREATE OR REPLACE FUNCTION public.unlink_auth_identity(target_user_id uuid, target_provider text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
    deleted_count integer;
begin
    if target_provider not in ('google') then
        raise exception 'Unsupported auth identity provider';
    end if;

    delete from auth.identities
    where user_id = target_user_id
      and provider = target_provider;

    get diagnostics deleted_count = row_count;
    return deleted_count;
end;
$function$
;

-- signature: public.update_all_aggregated_ratings()
CREATE OR REPLACE FUNCTION public.update_all_aggregated_ratings()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
    r_staff record;
    r_branch record;
    r_biz record;
    v_staff_rating numeric;
    v_branch_rating numeric;
    v_biz_rating numeric;
    v_default_rating numeric := 50.0;
begin
    raise notice 'Updating aggregated ratings for all active staff, branches, and approved businesses...';

    for r_staff in select id from public.staff where is_active = true loop
        begin
            v_staff_rating := public.calculate_staff_rating(r_staff.id);
            if v_staff_rating is null then
                v_staff_rating := v_default_rating;
            end if;
            update public.staff set rating_score = v_staff_rating where id = r_staff.id;
        exception when others then
            raise notice 'Error calculating staff rating for staff_id=%: %', r_staff.id, SQLERRM;
            update public.staff set rating_score = v_default_rating where id = r_staff.id and rating_score is null;
        end;
    end loop;

    for r_branch in select id from public.branches where is_active = true loop
        begin
            v_branch_rating := public.calculate_branch_rating(r_branch.id);
            if v_branch_rating is null then
                select coalesce(avg(rating_score), v_default_rating) into v_branch_rating
                from public.staff
                where branch_id = r_branch.id and is_active = true and rating_score is not null;
            end if;
            update public.branches set rating_score = v_branch_rating where id = r_branch.id;
        exception when others then
            raise notice 'Error calculating branch rating for branch_id=%: %', r_branch.id, SQLERRM;
            update public.branches set rating_score = v_default_rating where id = r_branch.id and rating_score is null;
        end;
    end loop;

    for r_biz in select id from public.businesses where is_approved = true loop
        begin
            v_biz_rating := public.calculate_biz_rating(r_biz.id);
            if v_biz_rating is null then
                select coalesce(avg(rating_score), v_default_rating) into v_biz_rating
                from public.branches
                where biz_id = r_biz.id and is_active = true and rating_score is not null;
            end if;
            update public.businesses set rating_score = v_biz_rating where id = r_biz.id;
        exception when others then
            raise notice 'Error calculating biz rating for biz_id=%: %', r_biz.id, SQLERRM;
            update public.businesses set rating_score = v_default_rating where id = r_biz.id and rating_score is null;
        end;
    end loop;

    raise notice 'Aggregated ratings update completed';
end;
$function$
;

-- signature: public.update_booking_status_no_check(uuid,public.booking_status)
CREATE OR REPLACE FUNCTION public.update_booking_status_no_check(p_booking_id uuid, p_new_status public.booking_status)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_booking record;
begin
    select * into v_booking from public.bookings where id=p_booking_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    -- A client may cancel their own pending booking, but cannot mark attendance or charge a package.
    if not (auth.uid() is not null and v_booking.client_id=auth.uid()
        and p_new_status='cancelled' and v_booking.status in ('hold','confirmed')) then
        perform public.assert_finance_access(v_booking.biz_id,v_booking.staff_id);
    end if;
    update public.bookings set status=p_new_status where id=p_booking_id;
end;
$function$
;

-- signature: public.update_booking_status_with_promotion(uuid,public.booking_status)
CREATE OR REPLACE FUNCTION public.update_booking_status_with_promotion(p_booking_id uuid, p_new_status public.booking_status)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_booking record; v_result jsonb;
begin
    select * into v_booking from public.bookings where id=p_booking_id for update;
    if not found then raise exception using errcode='42501',message='FINANCE_FORBIDDEN'; end if;
    perform public.assert_finance_access(v_booking.biz_id,v_booking.staff_id);
    if p_new_status='paid' and v_booking.status='paid' then
        return jsonb_build_object('applied',v_booking.subscription_applied is not null or v_booking.promotion_applied is not null,
            'already_paid',true)||coalesce(v_booking.subscription_applied,v_booking.promotion_applied,'{}'::jsonb);
    end if;
    perform public.update_booking_status_no_check(p_booking_id,p_new_status);
    if p_new_status<>'paid' then return jsonb_build_object('applied',false,'reason','Status is not paid'); end if;
    v_result:=public.apply_visit_package_to_booking(p_booking_id);
    if v_result->>'applied'='true' then return v_result; end if;
    -- A failed concurrent package debit is an operational failure, not permission to grant another benefit.
    if v_result->>'reason'='Package visit count race' then
        raise exception using errcode='40001',message='PACKAGE_CHANGED';
    end if;
    v_result:=public.apply_promotion_to_booking(p_booking_id);
    if v_result ? 'error' then raise exception using errcode='P0001',message='PROMOTION_APPLICATION_FAILED'; end if;
    if v_result->>'applied'='true' then
        update public.bookings set promotion_applied=jsonb_build_object(
            'promotion_id',v_result->>'promotion_id','promotion_type',v_result->>'promotion_type',
            'promotion_title',v_result->>'promotion_title','original_amount',(v_result->>'original_amount')::numeric,
            'final_amount',(v_result->>'final_amount')::numeric,'discount_percent',(v_result->>'discount_percent')::numeric,
            'discount_amount',(v_result->>'discount_amount')::numeric,'applied_at',now()) where id=p_booking_id;
    end if;
    return coalesce(v_result,jsonb_build_object('applied',false));
end;
$function$
;

-- signature: public.update_shift_aggregates(uuid,uuid,date,numeric,numeric,numeric,integer,numeric,numeric)
CREATE OR REPLACE FUNCTION public.update_shift_aggregates(p_staff_id uuid, p_biz_id uuid, p_shift_date date, p_total_amount numeric, p_master_share numeric, p_salon_share numeric, p_late_minutes integer, p_guaranteed_amount numeric DEFAULT 0, p_topup_amount numeric DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare v_period text; v_start date; v_end date; v_key text;
begin
    perform 1 from public.staff where id=p_staff_id and biz_id=p_biz_id for update;
    foreach v_period in array array['day','month','year'] loop
        v_start:=date_trunc(v_period,p_shift_date::timestamp)::date;
        v_end:=(v_start+case v_period when 'day' then interval '1 day' when 'month' then interval '1 month' else interval '1 year' end)::date;
        v_key:=to_char(p_shift_date,case v_period when 'day' then 'YYYY-MM-DD' when 'month' then 'YYYY-MM' else 'YYYY' end);
        insert into public.staff_shift_aggregates(staff_id,biz_id,period_type,period_value,shifts_count,total_amount,total_master,total_salon,total_late_minutes,updated_at)
        select p_staff_id,p_biz_id,v_period,v_key,count(*),coalesce(sum(total_amount),0),
            coalesce(sum(master_share),0),coalesce(sum(salon_share),0),coalesce(sum(late_minutes),0),now()
        from public.staff_shifts where staff_id=p_staff_id and biz_id=p_biz_id and status='closed' and shift_date>=v_start and shift_date<v_end
        on conflict(staff_id,period_type,period_value) do update set biz_id=excluded.biz_id,shifts_count=excluded.shifts_count,
            total_amount=excluded.total_amount,total_master=excluded.total_master,total_salon=excluded.total_salon,
            total_late_minutes=excluded.total_late_minutes,updated_at=excluded.updated_at;
    end loop;
end;
$function$
;

-- signature: public.user_current_business_set_updated_at()
CREATE OR REPLACE FUNCTION public.user_current_business_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at := timezone('utc'::text, now());
    RETURN NEW;
END;
$function$
;

-- signature: public.user_lifecycle_access_allowed()
CREATE OR REPLACE FUNCTION public.user_lifecycle_access_allowed()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
  select auth.uid() is null or exists (
    select 1 from auth.users u where u.id=auth.uid() and coalesce(u.banned_until,now())<=now()
      and not exists(select 1 from public.user_suspensions s where s.user_id=u.id)
      and (not exists(select 1 from public.user_lifecycle_commands c where c.user_id=u.id)
        or exists(select 1 from auth.sessions s where s.user_id=u.id and s.id::text=auth.jwt()->>'session_id'))
  );
$function$
;

-- signature: public.whatsapp_inbox_backlog_health()
CREATE OR REPLACE FUNCTION public.whatsapp_inbox_backlog_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '4s'
AS $function$
declare result jsonb; observed_at timestamptz:=clock_timestamp();
begin
  perform public._require_whatsapp_inbox_service();
  with states as (
    select i.*, (i.command_receipt is null and exists(select 1 from public.whatsapp_messages m where m.whatsapp_message_id=i.message_id)) as legacy
    from public.whatsapp_inbox i where i.status<>'sent'
  ), flags as (
    select *,
      status in ('pending','processing') and (status='pending' or lease_until<=observed_at)
        and available_at<=observed_at and attempts<8 and reply_started_at is null
        and provider_timestamp>=observed_at-interval '24 hours' and not legacy as due,
      status='ambiguous' or (status='processing' and lease_until<=observed_at and reply_started_at is not null) as uncertain,
      status in ('failed','ambiguous','legacy_manual','expired') or (status in ('pending','processing') and (status='pending' or lease_until<=observed_at)
        and (attempts>=8 or provider_timestamp<observed_at-interval '24 hours' or legacy or reply_started_at is not null)) as attention
    from states
  ) select jsonb_build_object(
      'pending',count(*) filter(where status='pending'),
      'due',count(*) filter(where due),
      'processing',count(*) filter(where status='processing'),
      'failed',count(*) filter(where attention),
      'ambiguous',count(*) filter(where uncertain),
      'oldest_due_age_seconds',coalesce(greatest(0,extract(epoch from observed_at-min(case when status='processing' then greatest(available_at,lease_until) else available_at end) filter(where due))),0)
    ) into result from flags;
  return result;
end;
$function$
;
